// كتاب الصلاة — القسم الثاني (الجزء الثاني من الباب ٣٠ إلى آخره: ص199–330)
const { NO_N, NO_O } = require('../b4/common');

module.exports = [
  {
    title: `باب خروج النساء إلى المساجد إذا لم يترتب عليه فتنة وأنها لا تخرج مطيبة (ص199–203)`,
    items: [
      { q: `تعزير المعترض على السنة (ضرب ابن عمر لابنه) وتعزير الوالد لولده وإن كان كبيرًا`, p: `201`,
        n: `قوله: (فأقبل عليه عبد الله فسبّه سبًّا سيئًا) وفي رواية: (فزبره) وفي رواية: (فضرب في صدره). فيه تعزير المعترض على السنة، والمعارض لها برأيه، وفيه تعزير الوالد ولده وإن كان كبيرًا.`,
        o: NO_O,
        s: `(ما كان ابن عمر ﵁ ليقول ذلك ويلعنه ويسبه سباً شديداً ويضربه في صدره لأنه خالف مكروهاً فقط، ظاهر الحديث أنه يُلزم الرجل أن يأذن، فإذا لم يأذن فقد خالف السنة، طالما أنها قد خرجت في صفة شرعية، وهو القيم على مراقبة الصفة الشرعية، فإذا رأى مخالفتها في صفة الخروج فله أن يمنعها بلا كراهة.) (فقد قال القائل ذلك على سبيل الديانة ومع ذلك سبه سباً شديداً وضربه في صدره، فدل ذلك على أن من عارض السنة برأيه عُقب.)`,
        f: [] },
      { q: `حكم منع النساء من المساجد: شروط الخروج (غير متطيبة ولا متزينة ولا ذات خلاخل ولا ثياب فاخرة ولا مختلطة بالرجال ولا شابة ممن يُفتتن بها)، وهل النهي للتحريم أم للتنزيه؟`, p: `201–202`,
        n: `قوله ﷺ: (لا تمنعوا إماء الله مساجد الله) هذا وشبهه من أحاديث الباب ظاهر في أنها لا تمنع المسجد لكن بشروط ذكرها العلماء مأخوذة من الأحاديث: [وهو ألا تكون متطيبة ولا متزينة ولا ذات خلاخل يُسمع صوتها ولا ثياب فاخرة ولا مختلطة بالرجال ولا شابة ونحوها ممن يُفتتن بها وأن لا يكون في الطريق ما يخاف به مفسدة ونحوها]. وهذا النهي عن منعهن من الخروج محمول على كراهة التنزيه، إذا كانت المرأة ذات زوج أو سيد ووجدت الشروط المذكورة، فإن لم يكن لها زوج ولا سيد حرم المنع إذا وجدت الشروط.`,
        o: `يُحمل النهي عن المنع على كراهة التنزيه (إذا كانت ذات زوج أو سيد)، ويحرم المنع إذا لم يكن لها زوج ولا سيد.`,
        s: `(وهو قول النبي ﷺ: «لاَ تَمْنَعُوا إِمَاءَ اللَّهِ مَسَاجِدَ اللَّهِ، وَلَكِنْ لِيَخْرُجْنَ وَهُنَّ تَفِلاَتٌ» (د) ٥٦٥ [قال الألباني]: حسن صحيح. وفي صحيح مسلم: «أَيُّمَا امْرَأَةٍ أَصَابَتْ بَخُورًا فَلاَ تَشْهَدْ مَعَنَا الْعِشَاءَ الآخِرَةَ». (وقوله «ألا تكون متزينة»:) لقوله تعالى: (وَلاَ يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِنْ زِينَتِهِنَّ). (ثياب فاخرة:) أي ثياب شهرة فتجذب الانتباه. (مختلطة بالرجال:) أي في صفوفهم وإنما تقف خلف الرجال. (شابة ونحوها:) ظاهر الحديث على الشابات والعجائز فالكلام على أنها خرجت بصفة فيها فتنة، أما أن الشابة تمنع مطلقاً فليس عليه دليل. (وذلك لأن طاعة الزوج مأمور بها، لكن الظاهر أنه يجب على الزوج أن يأذن.) (ما كان ابن عمر ﵁ ليقول ذلك... ظاهر الحديث أنه يُلزم الرجل أن يأذن...) وهذا الذي احتج به من يقول تمنع النساء الآن من المسجد والصحيح أن لا؛ إنما تمنع من أحدثت بنهي النبي ﷺ، فمن مست طيباً أو خرجت متبرجة فتمنع أما أن يمنع الجميع لأجل إحداث البعض فلا، وقد أجاب البعض: أن الله شرع على لسان نبيه ﷺ ذلك وهو ﷺ يعلم ما سوف تحدثه النساء ولم يأمر النبي ﷺ بمنع جميعهن وإنما منع من تطيبت أو مست بخوراً ونحو ذلك. فالرجل هو الذي يُقدِر هذا الأمر، فإن رآها محدثة منعها وإن رآها لم تحدث لم يمنعها، ولا يصح منع النساء بالعموم. وعائشة – رضي الله عنها – قالت ذلك اجتهاداً منها وظناً منها أن الرسول قد كان يمنع النساء جملة من باب سد ذريعة إحداث البعض، والصحيح أن النبي ﷺ أذن للنساء في ذلك ومنع من أحدث.`,
        f: [] },
      { q: `الأصل في «لا تمنعوا النساء حظوظهن من المساجد إذا استأذنوكم» (الاستئذان)، وتطيب المرأة للمسجد، ومعنى «أيما امرأة أصابت بخورًا» وإطلاق «العشاء الآخرة»`, p: `202`,
        n: `قوله ﷺ: (لا تمنعوا النساء حظوظهن من المساجد إذا استأذنوكم) هكذا وقع في أكثر الأصول (استأذنوكم)، وفي بعضها (استأذنكم) وهذا ظاهر، والأول صحيح أيضًا وعوملن معاملة الذكور لطلبهنّ الخروج إلى مجلس الذكور والله أعلم. قوله ﷺ: (إذا شهدت إحداكنّ العشاء فلا تطيّب تلك الليلة) معناه إذا أرادت شهودها، أما من شهدتها ثم عادت إلى بيتها فلا تُمنع من التطيّب بعد ذلك، وكذا قوله ﷺ: (إذا شهدت إحداكنّ المسجد فلا تمسّ طيبًا) معناه إذا أرادت شهوده. قوله ﷺ: (أيما امرأة أصابت بخورًا فلا تشهد معنا العشاء الآخرة) فيه دليل على جواز قول الإنسان العشاء الآخرة، وأما ما نُقل عن الأصمعي أنه قال: من المحال قول العامة العشاء الآخرة لأنه ليس لنا إلا عشاء واحدة فلا توصف بالآخرة فهذا القول غلط لهذا الحديث، وقد ثبت في صحيح مسلم عن جماعات من الصحابة وصفها بالعشاء الآخرة، وألفاظهم بهذا مشهورة في هذه الأبواب التي بعد هذا. (والبخور) بتخفيف الخاء وفتح الباء والله أعلم.`,
        o: `الأصمعي: لا يقال «العشاء الآخرة» لأنه ليس لنا إلا عشاء واحدة (غلط عند النووي).`,
        s: `(وذلك لأن طاعة الزوج...) (وأن المغرب هي العشاء الأولى.) (أي إلى ما نقل عن الأصمعي: وأن المغرب هي العشاء الأولى).`,
        f: [`(ص202) (فقد قال القائل ذلك على سبيل الديانة ومع ذلك سبه سباً شديداً وضربه في صدره، فدل ذلك على أن من عارض السنة برأيه عُقب.)`] },
      { q: `معنى «لو أن رسول الله ﷺ رأى ما أحدث النساء لمنعهن المسجد»`, p: `203`,
        n: `قولها (لو أن رسول الله ﷺ رأى ما أحدث النساء لمنعهن المسجد) يعني من الزينة والطيب وحسن الثياب. والله أعلم.`,
        o: NO_O,
        s: `وهذا احتج به من يقول تمنع النساء الآن من المسجد والصحيح أن لا؛ إنما تمنع من أحدثت بنهي النبي ﷺ... وعائشة – رضي الله عنها – قالت ذلك اجتهاداً منها وظناً منها أن الرسول قد كان يمنع النساء جملة من باب سد ذريعة إحداث البعض، والصحيح أن النبي ﷺ أذن للنساء في ذلك ومنع من أحدث.`,
        f: [] },
    ],
  },
  {
    title: `باب التوسط في القراءة الجهرية بين الجهر والإسرار إذا خاف من الجهر مفسدة (ص203–204)`,
    items: [
      { q: `الجهر بالقراءة والصلاة بمكبر الصوت خارج المسجد، ومعنى «ولا تجهر بصلاتك ولا تخافت بها» (في الصلاة أم الدعاء؟)`, p: `204`,
        n: `ذكر في الباب حديث ابن عباس رضي الله عنهما وهو ظاهر فيما ترجمنا له، وهو مراد مسلم بإدخال هذا الحديث هنا، وذكر تفسير عائشة رضي الله عنها عنها أن الآية نزلت في الدعاء، واختاره الطبري وغيره، لكن المختار الأظهر ما قاله ابن عباس رضي الله عنهما والله أعلم.`,
        o: `عائشة والطبري وغيره: الآية نزلت في الدعاء. ابن عباس (المختار عند النووي): في القراءة في الصلاة.`,
        s: `بل الصحيح أن الأمر يشمل الدعاء والصلاة فإن الدعاء صلاة أيضاً، فلا تعارض بين الحديثين لأن الآية تشمل الأمرين. (فالإمام مأمور أن يُسمع المأمومين ولذلك الصلاة في مكبر الصوت من غير حاجة إلى ذلك كوجود أُناس خارج المسجد أمر خلاف السنة فإنه من الجهر المبالغ فيه فيقع به من الفتن والمفاسد الكثير، ولذا لابد من الامتناع منه، وإنما يشرع استخدامه إذا احتاج الناس إلى ذلك كضيق المسجد بأهله ووجود أُناس بالخارج يحتاجون سماع الصوت، فالمقصود اسماع المصلين لا اسماع غيرهم، وإنما شرع اسماع الغير بالآذان أما الصلاة نفسها فعلى قدر سماع المأمومين.)`,
        f: [] },
    ],
  },
  {
    title: `باب الاستماع للقراءة (ص204–206)`,
    items: [
      { q: `الاستماع والإنصات للقراءة: حكمه في الصلاة وخارجها (قراءة المأموم الفاتحة مع الإنصات لقراءة الإمام، وخطبة الجمعة، وقراءة القرآن في المذياع)`, p: `206`,
        n: `قوله: (فاستمع له وأنصت) الاستماع الإصغاء له، والإنصات السكوت، فقد يستمع ولا يُنصت، فلهذا جمع بينهما كما قال الله تعالى: {فاستمعوا له وأنصتوا} قال الأزهري: يقال: أنصتَ، ونصَتَ، وانتصتَ، ثلاث لغات أفصحهنّ أنصتَ، وبها جاء القرآن العزيز.`,
        o: NO_O,
        s: `فالمأموم مأمور بالاستماع والسكوت والإنصات للقراءة في غير فاتحة الكتاب في الصلاة كما ذكرنا، وهي من الأدلة الدالة على وجوب قراءة المأموم للفاتحة، ولو قرءها أثناء قراءة الإمام لم يكن هناك تعارض بين التدبر المأمور به وبين قراءة المأموم للفاتحة، لأنه يقرأ نفس ما يقرأه الإمام من القرآن، وأما السورة فيؤمر بالسكوت والإنصات والتدبر لما يسمعه من الإمام وأما خارج الصلاة فحال خطبة الجمعة يلزمه السماع لأن الخطبة واجبة وما سواها مستحب، وأما ما كانمن غير الخطبة مثل ما يقرأ من قراءة القرآن في المذياع فاستماعه والإنصات له مستحب وليس بواجب.`,
        f: [`(ص206) «فإذا قرأناه»: فالله هو الذي أمر جبريل بقراءته أي قرأه بلسان جبريل. «ويفصم عنه»: أي ينفصل عنه.`] },
    ],
  },
  {
    title: `باب الجهر بالقراءة في الصبح والقراءة على الجن (ص207–213)`,
    items: [
      { q: `هل علم النبي ﷺ بالجن في أول مرة بالوحي أم بعد ذلك؟ (الجمع بين حديث ابن عباس «ما قرأ على الجن وما رآهم» وحديث ابن مسعود «أتاني داعي الجن»)`, p: `208–209`,
        n: `قال العلماء: هما قضيتان، فحديث ابن عباس في أول الأمر وأول النبوة حين أتوا فسمعوا قراءة {قل أوحي}. واختلف المفسرون هل علم النبي ﷺ استماعهم حال استماعهم بوحي أوحي إليه؟ أم لم يعلم بهم إلا بعد ذلك؟ وأما حديث ابن مسعود فقضية أخرى جرت بعد ذلك بزمان الله أعلم بقدره، وكان بعد اشتهار الإسلام.`,
        o: `اختلف المفسرون: هل علم النبي ﷺ استماعهم بوحي حال استماعهم؟ أم لم يعلم بهم إلا بعد ذلك.`,
        s: `فحديث ابن عباس الذي ينفي فقال: [مَا قَرَأَ رَسُولُ اللهِ ﷺ عَلَى الْجِنِّ وَمَا رَآهُمْ] أي ما قرأ متعمداً عليهم وإنما كان يقرأ لأصحابه وسمع الجن ذلك. وأما في المرة التي علم بوجودهم وقرأ عليهم والتي آذنته بهم شجرة فكانت مرة أخرى بعد هذه المرة، فحديث ابن مسعود والذي فيه أنهم افتقدوا النبي ﷺ وأن النبي ﷺ أخبرهم بأنه ذهب إليهم وأقرأهم فقال: [أَتَانِي دَاعِي الْجِنِّ فَذَهَبْتُ مَعَهُ فَقَرَأْتُ عَلَيْهِمُ الْقُرْآنَ] فنفي ابن عباس ﷺ بما قصد به أول مرة وإثبات ابن مسعود ﷺ يقصد به ثاني مرة. وأعلمته شجرة: بوحي من الله ﷻ إليها أن تخبر النبي ﷺ أن الجن قد حضروا وقرأ عليهم عند ذلك. وظاهر القرآن أن النبي ﷺ إنما علم بوجود الجن في المرة الأولى بعدما انصرفوا لأن الله قال: (قل أوحي إلي أنه استمع نفر من الجن) (فلما قضي ولوا إلى قومهم منذرين) كل ذلك مما أوحي إلى النبي ﷺ فهذا دلي ل أن هذا بعدما استمعوا وانصرفوا والله أعلم؛ فما علم بوجودهم أول مرة وإنما استمعوا قراءته وإنما أعلم بوجودهم بعد ذلك.`,
        f: [] },
      { q: `أصل رمي الشهب (النجوم) على الشياطين: هل بدأ بعد البعثة أم كانت موجودة قبلها؟ (وحيلولة الشياطين دون استراق السمع)`, p: `209–210`,
        n: `قوله: (وقد حيل بين الشياطين وبين خبر السماء، وأرسلت الشهب عليهم) – ظاهر هذا الكلام أن هذا حدث بعد نبوة نبينا ﷺ ولم يكن قبلها، ولهذا أنكرته الشياطين، وارتاعت له، وضربوا مشارق الأرض ومغاربها ليعرفوا خبره، ولهذا كانت الكهانة فاشية في العرب حتى قطع بين الشياطين وبين صعود السماء واسترّاق السمع، كما أخبر الله تعالى عنهم أنهم قالوا: {وأنا لمسنا السماء فوجدناها ملئت حرسا شديدا وشهبا وأنا كنا نقعد منها مقاعد للسمع فمن يستمع الآن يجد له شهابا رصدا} وقد جاءت أشعار العرب باستغرابهم رميها لكونهم لم يعهدوه قبل النبوة، وكان رميها من دلائل النبوة. وقال جماعة من العلماء: ما زالت الشهب منذ كانت الدنيا وهو قول ابن عباس والزهري وغيرهما، وقد جاء ذلك في أشعار العرب، ورَوى فيه ابن عباس رضي الله عنهما حديثًا قيل للزهري: فقد قال الله تعالى: {فمن يستمع الآن يجد له شهابا رصدا} فقال كانت الشهب قليلة فغلظ أمرها وكثرت حين بعث نبينا ﷺ. وقال المفسرون نحو هذا وذكروا أن الرمي بها وحراسة السماء كانت موجودة قبل النبوة ومعلومة ولكن إنما كانت تقع عند حدوث أمر عظيم من عذاب ينزل بأهل الأرض، أو إرسال رسول إليهم، وعليه تأوّلوا قوله تعالى: {وأنا لا ندري أشر أريد بمن في الأرض أم أراد بهم ربهم رشدا}.`,
        o: `قول: بدأ الرمي بالشهب بعد البعثة. قول جماعة من العلماء (ابن عباس والزهري وغيرهما): ما زالت الشهب منذ كانت الدنيا، وغلظ أمرها وكثرت حين بُعث النبي ﷺ. المفسرون: كانت موجودة قبل النبوة لكنها تقع عند حدوث أمر عظيم.`,
        s: `(وهذا هو الصحيح، لأن هذا مما لا يُشك فيه، فإن الشُهب موجودة في أخبار الأمم السابقة قبل بعثة النبي ﷺ ولم يزل أخبار الأمم متكاثرة في نزول الشهب من السماء فضلاً عن قول ابن عباس ﷺ.) (وهو قول صحيح تُألف به الآيات والأخبار وبه لا يتناقض شيء منها، فإن الكهانت كانت قبل بعثة النبي ﷺ والنبي ﷺ أخبر أنهم كانوا يكذبون معها مائة كذبه وكانوا يصدقون بالكلمة التي تُسمع من السماء، فدل ذلك على أنهم كانوا يصدقون وأحياناً يكذبون، فالحديث هنا ظاهره أنه حيل بين الشياطين وبين خبر السماء أي حيل بالكلية، فدل ذلك على أن ما أخبر به النبي ﷺ: (فَرُبَّمَا أَدْرَكَ الشِّهَابُ قَبْلَ أَنْ يُلْقِيَهَا، وَرُبَّمَا أَلْقَاهَا قَبْلَ أَنْ يُدْرِكَهُ فَيَكْذِبُ مَعَهَا مِئَةَ كَذْبَةٍ) البخاري. فدل ذلك على أنه كان هذا في الجاهلية ولم يكن ذلك امتناع خبر السماء، ولكن امتنع خبر السماء إذاً وقع في الأمر حدث وهو أنه منعت بالكلية، وحيل بينهم وبين خبر السماء تماماً.) (وقد أخبر الله بذلك فقال: (رجوماً للشياطين) فخلق الشهب أصلاً رجوماً للشياطين، فهي مخلوقة ابتداءً لذلك.) (فإنهم كانوا لا يدرون لماذا كثر الرمي؟ أمن أجل عذاب يوشك أن ينزل، فتحرس السماء من أجل ألا يستمع الناس وقت نزول العذاب فيستعدوا له مثلاً أو لأجل خير أراده الله ﷻ بهم من بعثة النبي ﷺ وهذا هو الذي وقع، فإن الله أراد الخير لأهل الأرض ببعثة النبي ﷺ.)`,
        f: [] },
      { q: `رمي الشهب: هل كانت قبل النبوة؟ وإعراب «رجومًا» (مصدر أم اسم)، والشهب من الكواكب`, p: `211`,
        n: `وقيل: كانت الشهب قبل مرئية ومعلومة، لكن رجم الشياطين وإحراقهم لم يكن إلا بعد نبوة نبينا ﷺ، واختلفوا في إعراب قوله تعالى: {رجومًا} وفي معناه فقيل: هو مصدر فتكون الكواكب هي الرّاجمة المحرقة بشُهبها لا بأنفسها، وقيل: هو اسم فتكون هي بأنفسها التي يُرجم بها، ويكون رجوم جمع رجم بفتح الراء والله أعلم.`,
        o: `قيل: رجم الشياطين وإحراقهم لم يكن إلا بعد النبوة. في «رجومًا»: مصدر (الكواكب هي الراجمة بشهبها)، أو اسم (الكواكب نفسها يُرجم بها).`,
        s: `(الظاهر الأول، أنه كان هناك رمي للشياطين بالشهب وأنها كانت رجوماً لهم ولكن لم تكن كثيرة تمنع خبر السماء، فكانت قلة الشهب تغريهم بأن يجلسوا للسمع رغم تعرضهم للرمي ولكن بعد بعثته ﷺ أصبحوا لا يسمعون أصلاً، فحيل بينهم تماماً حراسةً للقرآن العظيم، وحماية له أن يقع حرف منه للكهنة أو يعرفوا شيء منه.) (المعروف الثاني وهو الصحيح علمياً بأن الشهب هي أجزاء من الكواكب. أو أن بعض الكواكب تكون رجوماً وليس أن كل الكواكب تكون رجوماً.)`,
        f: [`(ص211) «فاضربوا مشارق الأرض ومغاربها»: قول النووي: ومنه قوله ﷺ: «لا يخرج الرجلان يضربان الغائط كاشفين عن عورتهما يتحدثان فإن الله تعالى يمقت على ذلك» — (هذا الحديث ضعيف.)`] },
      { q: `فوائد حديث ابن عباس: الجهر بالقراءة في الصبح، ومشروعية صلاة الجماعة في السفر ومن أول النبوة، وحكم الجماعة في السفر، وإيمان الجن`, p: `212`,
        n: `قوله: (وهو يصلي بأصحابه صلاة الصبح فلما سمعوا القرآن قالوا هذا الذي حال بيننا وبين السماء) – فيه الجهر بالقراءة في الصبح، – وفيه إثبات صلاة الجماعة، وأنها مشروعة في السفر، وأنها كانت مشروعة من أول النبوة. قال الإمام أبو عبد الله المازري: ظاهر الحديث أنهم آمنوا عند سماع القرآن، ولا بد لمن آمن عند سماعه أن يعلم حقيقة الإعجاز وشروط المعجزة، وبعد ذلك يقع له العلم بصدق الرسول فيكون الجن علموا ذلك من كتب الرسل المتقدمين قبلهم على أنه هو النبي الصادق المبشر به، واتفق العلماء على أن الجن يعذبون في الآخرة على المعاصي قال الله تعالى: {لأملأن جهنم من الجنة والناس أجمعين}، واختلفوا في أن مؤمنهم ومطيعهم هل يدخل الجنة وينعم بها ثوابًا ومجازاة له على طاعته أم لا يدخلون بل يكون ثوابهم أن ينجوا من النار ثم يقال: كونوا ترابًا كالبهائم؟ وهذا مذهب ابن أبي سليم وجماعة، والصحيح أنهم يدخلونها وينعمون فيها بالأكل والشرب وغيرهما، وهذا قول الحسن البصري والضحاك ومالك بن أنس وابن أبي ليلى وغيرهم.`,
        o: `ابن أبي سليم وجماعة: مؤمنو الجن لا يدخلون الجنة بل ثوابهم النجاة من النار ثم يُقال لهم كونوا ترابًا كالبهائم. الحسن البصري والضحاك ومالك وابن أبي ليلى (الصحيح عند النووي): يدخلون الجنة وينعمون فيها.`,
        s: `(الصحيح أنها واجبة في السفر، ما لم يُخش فوات الرفقة أو كان هناك خوف أو مرض.) (هذا الأمر وهو معرفة حقيقة الإعجاز وشروط المعجزة على طريقة المتكلمين – وهو أن يعجز البشر بأن يأتوا بمثله؛ وغيرها من التعريفات الكلامية التي لا تلزم بلا شك – ليس بشرط بلا شك بل يكفي ما يقع في قلبه من تصديق النبي ﷺ وأن يعلم أن هذا الكلام لا يشبه كلام البشر وأنه كلام الله فإذا صدق بذلك لم يلزمه شيء آخر.) (والصحيح أنهم يدخلونها وينعمون فيها، وهذا هو الصحيح الذي لا نشك فيه، لأن الله ﷻ قال: (ولمن خاف مقام ربه جنتان فبأي آلاء ربكما تكذبان)، فللجن الذين يخافون مقام ربهم جنتان، وعموم الأدلة تدل على دخول ذكور وإناث الجن في الوعد بدخول الجنة إن أطاعوا ودخولهم النار إن عصوا ومنه قوله تعالى: (من عمل صالحاً من ذكر أو أنثى فلنحيينه حياة طيبة ولنجزينهم أجرهم بأحسن ما كانوا يعملون)؛ وأما قول من قال: (أنهم يقال لهم كونوا ترابا) فلم يثبت من طريق مرفوع في البهائم وورد في البهائم من طريق موقوف في تفسير قوله تعالى: (ويقول الكافر يا ليتني كنت ترابا) ومن نقل عنه ذلك ممن يأخذ من الإسرائيليات فهذا مما يتوقف فيه؛ فالصحيح الوقف وعدم الجزم بأن البهائم تكون ترابا وقياس الجن على البهائم في ذلك مما لم يثبت لا في كتاب ولا سنة، وهذا مما لا ينبغي ترك عموم القرآن من أجله، والصحيح أن مؤمني الجن ينعمون في الجنة كما أن عصاتهم يعذبون في النار.)`,
        f: [] },
      { q: `الوضوء بالنبيذ: حكمه (ونقد حديث ابن مسعود في ليلة الجن)، وأن ابن مسعود لم يحضر ليلة الجن`, p: `213–214`,
        n: `قوله: (سألت ابن مسعود هل شهد أحد منكم مع رسول الله ﷺ ليلة الجن؟ قال لا) هذا صريح في إبطال الحديث المروي في سنن أبي داود وغيره المذكور فيه الوضوء بالنبيذ وحضور ابن مسعود معه ﷺ ليلة الجن، فإن هذا الحديث صحيح، وحديث النبيذ ضعيف باتفاق المحدثين، ومداره على زيد مولى عمرو بن حريث وهو مجهول. قال الدارقطني: انتهى حديث ابن مسعود عند قوله (فآرانا آثارهم وآثار نيرانهم)، وما بعده من قول الشعبي كذا رواه داود الراوي عن الشعبي وابن علية وابن زريع وابن أبي زائدة وابن إدريس وغيرهم. ومعنى قوله (إنه من كلام الشعبي) أنه ليس مرويًا عن ابن مسعود بهذا الحديث وإلا فالشعبي لا يقول هذا الكلام إلا بتوقيف عن النبي ﷺ والله أعلم.`,
        o: `الحنفية: يجوز الوضوء بالنبيذ (بحديث ابن مسعود). الجمهور: لا يجوز، وحديث النبيذ ضعيف باتفاق المحدثين.`,
        s: `(احتج به الحنفية على جواز الوضوء بالنبيذ وهو (الماء الذي انتبذ فيه فصار حلواً بإلقاء بعض التمر أو الفاكهة فيه) وليس النبذ هنا هو الخمر ولكن مذهب الحنفية ضعيف والجمهور يمنعون من الوضوء بالنبيذ لأنه لم يعد ماءً مطلقاً بل صار ماء له اسم آخر وهو النبيذ وهو ماء حلو تغير طعمه وهو لا يصح الوضوء به عند جمهور العلماء.) (لكن كما ذكرنا يكون له حكم الإرسال على قول الدارقطني، وظاهر صنيع مسلم رحمه الله تصحيحه مرفوعاً ولكن أشار إلى هذا الاحتمال بهذه الرواية.)`,
        f: [`(ص213) (يعني أنه ليس تصريحًا من ابن مسعود ولكن ما بعده من كلام الشعبي — فتعليق الشيخ بأن «ما بعد ذلك له حكم الإرسال».)`] },
      { q: `معنى «لكم كل عظم ذُكر اسم الله عليه» وطعام الجن وعلف دوابهم، ومعنى «آذنت بهم شجرة»، والاستنجاء بالعظم والبعر`, p: `214–215`,
        n: `قوله: (لكم كل عظم ذُكر اسم الله عليه) قال بعض العلماء هذا لمؤمنيهم، وأما غيرهم فجاء في حديث آخر أن طعامهم ما لم يُذكر اسم الله عليه. قوله: (وددت أني كنت معه) فيه الحرص على مصاحبة أهل الفضل في أسفارهم ومهماتهم ومشاهدهم ومجالسهم مطلقًا والتأسف على فوات ذلك. قوله: (آذنت بهم شجرة) هذا دليل على أن الله تعالى يجعل فيها ما يشاء من الجماد تمييزًا ونظيره قوله تعالى: {وإن منها لما يهبط من خشية الله} وقوله تعالى: {وإن من شيء إلا يسبح بحمده ولكن لا تفقهون تسبيحهم} وقوله ﷺ: «إني لأعرف حجرًا بمكة كان يسلم علي» وحديث الشجرتين اللتين أتتاه ﷺ، وقد ذكره مسلم في آخر الكتاب، وحديث حنين الجذع، وتسبيح الطعام، وفرار حجر موسى بثوبه، ورجفان حراء وأحد. والله أعلم.`,
        o: NO_O,
        s: `(أي أعلمته شجرة: بوحي من الله، فتخبر النبي ﷺ أن الجن قد حضروا فيقرأ عليهم عند ذلك.) (وفيه فوائد: ١- وفيه فضيلة الدعوة إلى الله ﷻ لأجل أن الجن انطلقوا إلى قومهم داعين إلى الله فدعوهم إلى الإيمان بالقرآن؛ فالقرآن شأنه عجيب لعدم مشابهته بكلام الخلق وأنه يحيي الله به قلوب من شاء من عباده، فالقرآن يهدي إلى الرشد فلن تجد هداية أفضل من هداية القرآن. ٢- وفيه حب الصحابة للنبي ﷺ وتفقدهم له لما فقدوه وبحثهم عنه. والظاهر أن هذه الواقعة كانت بمكة وهو الصواب لقوله: (فإذا هو قد جاء من قبل حراء). ٣- الحديث رواه مسلم في باب الصلاة من أجل قوله ﷺ: (فَلاَ تَسْتَنْجُوا بِهَا) أي بالعظم والبعر. حتى لو كان بعر ما لا يؤكل لحمه فإنه ليس بنجس ومع ذلك لا يجوز أن نستنجي به وقد ثبت في حديث آخر: عَنْ أَبِي هُرَيْرَةَ أَنَّ النَّبِيَّ ﷺ نَهَى أَنْ يُسْتَنْجَى بِرَوْثٍ أَوْ بِعَظْمٍ وَقَالَ إِنَّهُمَا لاَ يُطَهِّرَانِ. إِسْنَادُهُ صَحِيحٌ، سنن الدارقطني؛ فلو استنجى ببعرة شاة لم يجزئ عنه في الاستنجاء لأن النبي ﷺ قد نهى والنهي يقتضي الفساد خصوصاً مع التصريح وذلك إذا كان النهي عنه لذاته أو لوصف لازم وهنا النبي ﷺ أخبر بأنهما لا يطهران. ٤- وفيه مراعاة مصلحة الإخوان عموماً، فإنه إن راعى مصلحة إخواننا من الجن فإخواننا من الإنس أولى وألا نفسد عليهم طعامهم وطعام دوابهم بالأولى. ٥- وفيه النهي عن الفساد: (جن الجزيرة): مكان في العراق. ٦- وفيه سرعة حركة الجن لأنهم ضربوا المشارق والمغارب وكان هذا بأمر من إبليس، كما ذكر ابن كثير في تفسيره لسورة الأحقاف ولقد هدى الله الطائفة التي استمعت القرآن من النبي ﷺ.)`,
        f: [] },
    ],
  },
  {
    title: `باب القراءة في الظهر والعصر (ص215–224)`,
    items: [
      { q: `تطويل القراءة وتخفيفها في الصلاة: الجمع بين أحاديث التطويل والتخفيف (السنة التخفيف؟)`, p: `218–219`,
        n: `قال العلماء: كانت صلاة رسول الله ﷺ تختلف في الإطالة والتخفيف باختلاف الأحوال، فإذا كان المأمومون يؤثرون التطويل، ولا شغل هناك له ولا لهم طول، وإذا لم يكن كذلك خفف، وقد يريد الإطالة ثم يعرض ما يقتضي التخفيف كبكاء الصبي ونحوه، وينضم إلى هذا أنه قد يدخل في أثناء الوقت فيخفف. وقيل: إنما طول في بعض الأوقات وهو الأقل، وخفف في معظمها فالإطالة لبيان جوازها والتخفيف لأنه الأفضل، وقد أمر ﷺ بالتخفيف وقال: «إن منكم منفرين فأيكم صلى بالناس فليخفف فإن فيهم السقيم والضعيف وذا الحاجة». وقيل: طوّل في وقت، وخفف في وقت ليبين أن القراءة فيما زاد على الفاتحة لا تقدير فيها من حيث الاشتراط، بل يجوز قليلها وكثيرها، وإنما المشترط الفاتحة ولهذا اتفقت الروايات عليها، واختلف فيما زاد. وعلى الجملة السنة التخفيف كما أمر به النبي ﷺ للعلة التي بينها، وإنما طول في بعض الأوقات لتحققه انتفاء العلة فإن تحقق أحد انتفاء العلة طول.`,
        o: `أقوال في الجمع: يختلف باختلاف الأحوال؛ أو التطويل في الأقل والتخفيف في الأغلب؛ أو لبيان أنه لا تقدير فيما زاد على الفاتحة.`,
        s: `الصحيح أن يقال أن التطويل والتخفيف أمر نسبي والسنة مراعاة ما فعله النبي ﷺ، فإنه ما كان ليأمرهم بشيء ثم يتركه وإنما كان ﷺ يأمر بالتخفيف الذي يقصده ﷺ. ولا ينبغي التطويل أكثر من تطويله ﷺ في الفرائض حتى تستغرق الوقت كله فإن هذا خلاف السنة. وإنما التطويل الذي كان يفعله هو ما ورد فيه الحديث: أن يقرأ في الظهر بنحو من ثلاثين آية وفي العصر بنحو الخمسة عشرة آية ونحو ذلك.`,
        f: [] },
      { q: `قراءة سورة قصيرة بكمالها أفضل أم قدرها من طويلة؟ (علة استحباب إكمال السورة)`, p: `219`,
        n: `قوله: (وكان يقرأ بفاتحة الكتاب وسورتين) فيه دليل لما قاله أصحابنا وغيرهم أن قراءة سورة قصيرة بكمالها أفضل من قراءة قدرها من طويلة، لأن المستحب للقارئ أن يبتدئ من أول الكلام المرتبط ويقف عند انتهاء المرتبط، وقد يخفى الارتباط على أكثر الناس أو كثير فنُدب منهم إلى إكمال السورة ليحترز عن الوقوف دون الارتباط.`,
        o: NO_O,
        s: `وإن كان قد ثبت أن النبي ﷺ قد قرأ بعض السورة في سُنة الصبح فقرأ آية: (قل يا أهل الكتاب تعالوا..) وفي الثانية قرأ: (قولوا آمنا بالله وما أنزل علينا...). فعن ابن عباس قال كان رسول الله ﷺ يقرأ في ركعتي الفجر (قُولُوا آمَنَّا بِاللَّهِ وَمَا أُنْزِلَ إِلَيْنَا) والتي في آل عمران (تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ) مسلم. وعن عبد الله بن عباس أن كثيراً ما كان يقرأ رسول الله ﷺ في ركعتي الفجر: بـ{آمَنَّا بِاللَّهِ وَمَا أُنْزِلَ إِلَيْنَا} [البقرة] هذه الآية، قال: هذه في الركعة الأولى، وفي الركعة الآخرة بـ{آمَنَّا بِاللَّهِ وَاشْهَدْ بِأَنَّا مُسْلِمُونَ} [آل عمران]، (د) ١٢٥٩ [قال الألباني]: صحيح دون [إن كثيراً مما].`,
        f: [] },
      { q: `القراءة بالسورة في الأخريين: مذاهب العلماء (وحكم من أدرك المسبوق)، والترجيح`, p: `219–220`,
        n: `وأما اختلاف الرواية في السورة في الأخريين فلعل سببه ما ذكرناه من اختلاف إطالة الصلاة وتخفيفها بحسب الأحوال، وقد اختلف العلماء في استحباب قراءة السورة في الأخريين من الرباعية والثالثة من المغرب فقيل بالاستحباب وبعدمه، وهما قولان للشافعي رحمه الله تعالى. قال الشافعي: ولو أدرك المسبوق الأخريين أتى بالسورة في الباقيتين عليه لئلا تخلو صلاته من سورة.`,
        o: `قولان للشافعي في استحباب السورة في الأخريين.`,
        s: `(والصحيح في ذلك أنه طالما ثبت الحديثان ولا تعارض بين الأفعال أصلاً، فيحمل هذا على حال وهذا على حال، فنقول يستحب أن يقرأ أحياناً بالسورة في الثالثة والرابعة من الظهر والعصر، والثالثة من المغرب ولا يداوم على ذلك، فإنه طالما ثبت أن النبي ﷺ قرأ في الأخريين بفاتحة الكتاب ومفهوم المخالفة أنه لم يقرأ غيرها دل ذلك على أن هذا فعله، ولعل كان هذا هو الأكثر، وأحياناً كان يقرأ بالسورة، فهذا الجمع أولى من تعطيل أحد الحديثين؛ وهناك وجه آخر في الجمع: في أن حديث أبا قتادة صريح في عدم الزيادة – مع أنه ليس صريح نص ولكن هو وجه نذكره – وحديث أبي سعيد الذي فيه القراءة تخمين لقوله: (وحذرنا قيامه) وهذا ليس بظاهر ولذلك مذهب من رجح حديث أبا قتادة جداً وأنه قد طول الفاتحة جداً ولكن هذا خلاف الظاهر لأن الظاهر أنه كان يتكلم عن القراءة بخلاف الفاتحة وقدر قراءة خمسة عشر آية قدر كبير ليس بالقدر اليسير الذي يتسع الأمر فيه لتطويل الفاتحة لهذا القدر، والأقرب حمله على حالات مختلفة، فأحياناً كان يقرأ وأحياناً كان لا يقرأ ﷺ. فنقول يستحب أن يقرأ أحياناً بالسورة في الأخريين من الرباعية والثالثة من المغرب ولا يداوم على ذلك.)`,
        f: [`(ص219) والصحيح في ذلك أنه طالما ثبت الحديثان ولا تعارض بين الأفعال أصلاً، فيحمل هذا على حال وهذا على حال...`, `(ص220) (قال الشافعي: «ولو أدرك المسبوق الأخريين أتى بالسورة في الباقيتين» — لئلا تخلو صلاته من سورة.)`] },
      { q: `القراءة المستحبة في كل صلاة: الصبح والظهر (طوال المفصل)، والعشاء والعصر (أوساطه)، والمغرب (قصاره)، وحكمة ذلك، وبيان المفصل`, p: `220–222`,
        n: `وأما اختلاف قدر القراءة في الصلوات فهو عند العلماء على ظاهره. قالوا: فالسنة أن يقرأ في الصبح والظهر بطوال المفصل، وتكون الصبح أطول، وفي العشاء والعصر بأوساطه، وفي المغرب بقصاره. قالوا: والحكمة في إطالة الصبح والظهر أنهما في وقت غفلة بالنوم آخر الليل، وفي القائلة وطولهما ليدركهما المتأخر بغفلة ونحوها، والعصر ليست كذلك بل تفعل في وقت تعب أهل الأعمال فخففت عن ذلك، والمغرب ضيقة الوقت فاحتيج إلى زيادة تخفيفها لذلك ولحاجة الناس إلى عشاء صائمهم وضيفهم، والعشاء في وقت غلبة النوم والنعاس ولكن وقتها واسع فأشبهت العصر. والله أعلم.`,
        o: NO_O,
        s: `(أي في الغالب فقد ثبت أنه ﷺ قرأ بالليل إذا يغشى في صلاة الظهر وهي من أواسط المفصل، فعن جابر بن سمرة قال كان النبي ﷺ يقرأ في الظهر بـ(الليل إذا يغشى) وفي العصر نحو ذلك وفي الصبح أطول من ذلك مسلم. وقرأ في المغرب بالمرسلات وهي من طوال المفصل وقرأ فيها بالأعراف وبالطور وهي من طوال المفصل فدل ذلك على اختلاف الأحوال.) (فدل ذلك على اختلاف الأحوال، فهذا الحديث الذي قال الصحابي الذي فيه ذكر عمر بن عبد العزيز أنه كان يصلي بصلاة رسول الله ﷺ يحمل على أكثر الأحيان، فيقرأ بقصار المفصل في المغرب أحياناً، وفي العصر يقرأ بالأوساط هي والعشاء وفي الظهر يقرأ بالطوال وبالأوساط والأكثر بالطوال وفي الفجر بالطوال لأن ذلك كله قد ثبت.) (فنقله هنا عن العلماء من أن الصبح والظهر من طوال المفصل، كما ذكرنا أن الصبح ورد أن الصبح ورد فيه الطوال دائماً أو قدر الطوال (من ستين إلى مائة آية) والظهر كما سيأتي من أواسط المفصل.) (المفصل من سورة (ق أو [الحجرات من القول الآخر]) إلى آخر المصحف) وذلك لكثرة الفصل بين سوره (ببسم الله الرحمن الرحيم): فطوال المفصل من [ق أو الحجرات إلى المرسلات] وأواسط المفصل من [النبأ إلى الضحى] وقصار المفصل من [الشرح للناس]. (وليس هذا في جميع الأوقات بل كان أحياناً يطولها، وهو دليل على اتساع وقت المغرب وهو من أقوى الأدلة للرد على وجه عند الشافعية القائلين بأنه ليس للمغرب إلا وقت واحد وهو أول الوقت فقط قدر ما يتسع لصلاة ثلاث ركعات، وأظن أن ترك الناس للسنة القبلية للمغرب بين الأذان والإقامة، من أجل هذا المذهب، فإنهم يقولون أن وقت المغرب وقت واحد وقت صلاة ثلاث ركعات بعد الغروب وهذا وجه للشافعية؛ فمن أقوى الأدلة للرد على هذا حديث: عَنْ مَرْوَانَ بْنِ الْحَكَمِ قَالَ: قَالَ لِي زَيْدُ بْنُ ثَابِتٍ مَا لَكَ تَقْرَأُ فِي الْمَغْرِبِ بِقِصَارٍ وَقَدْ سَمِعْتُ النَّبِيَّ ﷺ يَقْرَأُ بِطُولِ الطُّولَيَيْنِ. (البخاري). فقراءته لسورة الأعراف مع قراءة النبي ﷺ المتمهلة التي فيها ترتيل، فيتسع لوقت صلاة المغرب كله من المغرب للعشاء، فسورة الأعراف تحتاج إلى قرب الساعة لقراءة متمهلة.) (وأن العشاء في وقت غلبة النوم والنعاس ولكنّ وقتها واسع فأشبهت العصر.)`,
        f: [] },
      { q: `تطويل الركعة الأولى وتقصير الثانية، وتطويل الثالثة على الرابعة: الأقوال (وهل التطويل في الدعاء أم في القراءة؟)`, p: `222`,
        n: `وقوله: (وكان يُطوّل الركعة الأولى ويقصّر الثانية) هذا مما اختلف العلماء في العمل بظاهره وهما وجهان لأصحابنا: – أشهرهما عندهم لا يُطوّل، والحديث مُتأوَّل على أنه طوّل بدعاء الافتتاح والتعوذ، أو لسماع دخول داخل في الصلاة ونحوه لا في القراءة، – والثاني أنه يستحب تطويل القراءة في الأولى قصدًا هذا وهو الصحيح المختار الموافق لظاهر السنة، ومن قال بقراءة السورة في الأخريين اتفقوا على أنها أخف منها في الأوليين، واختلف أصحابنا في تطويل الثالثة على الرابعة إذا قلنا بتطويل الأولى على الثانية. وفي هذه الأحاديث كلها دليل على أنه لا بد من قراءة الفاتحة في جميع الركعات.`,
        o: `أشهر الوجهين عند الشافعية: لا يُطوّل (والحديث مُتأوَّل: التطويل بدعاء الافتتاح أو لانتظار داخل). الثاني (الصحيح المختار عند النووي): يُستحب تطويل القراءة في الأولى. واختلفوا في تطويل الثالثة على الرابعة.`,
        s: `(بل ينبغي أن يُجهر ظاهر الحديث عن الأولى والثانية.) (وهذا خلاف الظاهر، نعم من ضمن التطويل أنه يدعو دعاء الاستفتاح فصار حلواً ولكن الصحيح أنه كان يتكلم عن القراءة في الصلاة، فالصحيح حمل الحديث على ظاهره والعمل به، ورد هذا القول.) (وهذا من إنصاف الإمام النووي رحمه الله رغم أن الأشهر عندهم في المذهب عدم الإطالة، ولكنه قال (هَذَا وَهُوَ الصَّحِيحِ الْمُخْتَارِ) موافقةً للسنة.) (وهذا لم يرد فيه شيء، فالسورة ينبغي أن تكون قصيرة إذا قرءها في الثالثة والرابعة.)`,
        f: [`(ص222) عن عدي قال سمعت البراء يحدث عن النبي ﷺ أنه كان في سفر فصلى العشاء الآخرة فقرأ في إحدى الركعتين (والتين والزيتون) مسلم. أي بشيء من قصار المفصل والله أعلم.`] },
      { q: `القراءة في الأخريين: مذهب أبي حنيفة (التخيير بين القراءة والتسبيح والسكوت) والجمهور، وحكم الجهر ببعض الآية في السرية (هل هو سنة أم لا؟ وهل يسجد للسهو؟)`, p: `223`,
        n: `ولم يوجب أبو حنيفة ﵁ في الأخريين القراءة، بل خيّره بين القراءة والتسبيح والسكوت، والجمهور على وجوب القراءة، وهو الصواب الموافق للسنن الصحيحة. وقوله: (وكان يُسمعنا الآية أحيانًا) هذا محمول على أنه أراد به بيان جواز الجهر في القراءة السرية، وأن الإسرار ليس بشرط لصحة الصلاة بل هو سنة، ويحتمل أن الجهر بالآية كان يحصل بسبق اللسان للاستغراق في التدبر. والله أعلم.`,
        o: `أبو حنيفة: لا يوجب القراءة في الأخريين بل يخيّر بين القراءة والتسبيح والسكوت. الجمهور: تجب القراءة.`,
        s: `(بل إن أبا حنيفة لا يرى بوجوب قراءة الفاتحة في أي ركعة من الركعات ولكن يوجب القراءة في الأولى والثانية بشيء من القرآن ولو بقدر الفاتحة وفي الثالثة والرابعة يجوز السكوت مطلقاً وليس على قدر الفاتحة.) (قوله «الصواب»: معناه أن النووي يرى أن المسألة خلاف غير سائغ، وهي أولى بذلك. وانظر إلى طريقة الإمام النووي في ذكر الخلاف: فقد ذكر في الأولى (وهو الصحيح المختار) وهنا قال (وهو الصواب) فيكون ضد الصواب (الباطل) والخلاف فيه غير سائغ وأما (الصحيح) يكون في المسألة خلاف سائغ عند الإمام النووي.) (وظاهر الحديث أولى بالعمل به (فيسمعهم الآية أحياناً) [أحياناً] فلا يواظب على ذلك، ولكن الذي ذكره صحيح فإنه إن تعمد الجهر أحياناً دل ذلك على أن الإسرار والجهر كلٌ في موضعه سُنة وليس بواجب فقد كان لا يسجد للسهو إذا تركه، وعلى هذا فلو سهى الإمام – فإنه لو ثبت الحديث في التعمد يكون السو من باب أولى – فجهر في بعض الصلاة لم يسجد للسهو؛ وإذا قرأ سراً في صلاة جهرية صحت صلاته أيضاً ولا يلزم سجود السهو.) (هذا خلاف الظاهر ولهذا ذكره كاحتمال لقوله: (يسمعنا) أي تعمداً؛ والأصل في أفعال النبي ﷺ التشريع وليس أنه سهى، حيث لا دليل على أنه بسبق اللسان دون قصد والأصل في أفعال النبي ﷺ القصد.)`,
        f: [] },
      { q: `بيان أسماء رواة وعبارات لغوية (سعد بن أبي وقاص، الكوفة)، والإمام إذا شُكي نائبه، وعزل الوالي إذا خيفت فتنة`, p: `224–225`,
        n: `قوله: (إن أهل الكوفة شكوا سعدًا) هو سعد بن أبي وقاص ﵁، والكوفة هي البلدة المعروفة ودار الفضل ومحلّ الفضلاء بناها عمر بن الخطاب ﵁... قوله: (فأرسل إليه عمر ﵁) – فيه أن الإمام إذا شكا إليه نائبه بعث إليه واستفسره عن ذلك، – وأنه إذا خاف مفسدة باستمراره في ولايته ووقوع فتنة عزله، فلهذا عزله عمر ﵁ مع أنه لم يكن فيه خلل، ولم يثبت ما يقدح في ولايته وأهليّته، وقد ثبت في صحيح البخاري في حديث مقتل عمر والشورى أن عمر ﵁ قال: إن أصابت الإمارة سعدًا فذاك وإلا فليستعن به أيكم ما أُمّر فإني لم أعزله من عجز ولا خيانة.`,
        o: NO_O,
        s: `(لأن قضية الإمارة والولاية لا يلزم منها أن يستمر فيها من لا يصلح لهؤلاء الناس، ولو كان صالحاً في نفسه ويصلح لغيرهم فقد لا يصلح لقوم ويصلح لآخرين ولذلك قال عمر ﵁: (ما أعزله عن خيانة) فعمر ﵁ لما وجد كثرة الفتن وكراهية الناس لإمارته علم عمر ﵁ أن غيره أصلح للناس منه وأن طاعتهم لأميرهم سوف تكون أكمل مع غير سعد ﵁.) (فذاك: أي كان أحق بالإمارة وأهلٌ لها؛ فهو قوي أمين: فالقوة في نفي العجز والأمين في نفي الخيانة.) (وهذا من كذبهم على أميرهم، وهو دليل على صعوبة طبع أهل الكوفة من قديم.) (وخصوصاً في هذا الموقف، فسعد ﵁ كان في هذا الموقف متهم وعمر ﵁ نوى عزله فإذا لم يبين له حسن ظنه به ومنزلته عنده فسيكون كلامه فيه شيء في نفس سعد ﵁؛ فعمر ﵁ قد نوى عزله وإن لم يكن مقصراً، فهم الذين لا يصلحون لسعد ﵁.) (وهذا الذي ينبغي أن يعمل به فإن هؤلاء الصحابة مشهود لهم بالجنة، فسعد ﵁ فداه النبي ﷺ بأبويه وأمه وشهد له بالجنة وهو حي فمثل هؤلاء لا ينبغي أن يغتر أحد بتزكيتهم فيجعل غيرهم مثلهم ولذا مما ينبغي العمل به عدم مدح الرجل في وجهه لأنه يخشى عليه الفتنة إلا في أحوال الضرورة.)`,
        f: [`(ص224) «فذكروا من صلاته»: أي أنه لا يُحسن الصلاة — وهذا من كذبهم على أميرهم. (ص224) «قوله: (كنا نحزر قيامه) هو بضم الزاي وكسرها لغتان. (الأوليين والأخريين) هو بياءين مثناتين تحت.»`] },
      { q: `مدح الرجل الجليل في وجهه، والنهي عنه، وخطابه بكنيته دون اسمه، ومعنى «لا آلو»`, p: `226`,
        n: `فيه مدح الرجل الجليل في وجهه إذا لم يخف عليه فتنة بإعجاب ونحوه، والنهي عن ذلك إنما هو لمن خيف عليه الفتنة، وقد جاءت أحاديث كثيرة في الصحيح بالأمرين، وجمع العلماء بينهما بما ذكرته وقد أوضحتها في كتاب الأذكار. وفيه خطاب الرجل الجليل بكنيته دون اسمه. قوله: (وما ألو ما اقتديت به من صلاة رسول الله ﷺ) (ألو) بالمد في أوله وضم اللام أي لا أقصر في ذلك. ومنه قوله تعالى: {لا يألونكم خبالا} أي لا يقصرون في إفسادكم. قوله: (وهو مكثور عليه) أي عنده ناس كثيرون للاستفادة منه.`,
        o: NO_O,
        s: `(وهذا الذي ينبغي أن يعمل به... ولذا مما ينبغي العمل به عدم مدح الرجل في وجهه لأنه يخشى عليه الفتنة إلا في أحوال الضرورة.) (أي مزدحمون عليه.) (مالك في ذلك من خير: أي ستجد أمراً قد هجره الناس؛ فلما رآى حرصه بلغه، وكان هذا من الخير إذ وصلت إلينا هذه السنة حتى ولو لم نعمل بها فقد علمنا مدى تقصيرنا وعدم إطالة الصلاة والخشوع فيها كما كان يفعل النبي ﷺ.)`,
        f: [`(ص226) «أَسَأَلْتُكَ عَنْ صَلاَةِ رَسُولِ اللهِ ﷺ؟ فَقَالَ: مَا لَكَ فِي ذَلِكَ مِنْ خَيْرٍ» معناه إنك لا تستطيع الإتيان بمثلها لطولها وكمال خشوعها وإن تكلفت ذلك شُقّ عليك ولم تحصِّله فتكون قد علمت السنة وتركتها.`] },
    ],
  },
  {
    title: `باب القراءة في الصبح (ص227–231)`,
    items: [
      { q: `تخفيف صلاة الفجر وتطويلها: القراءة بـ«ق والقرآن المجيد»، وهل نُسخ التطويل؟ وتطويل الصبح عند الصحابة`, p: `227–228`,
        n: `(أحاديث: «كان النبي ﷺ يقرأ في الفجر والليل إذا عسعس»؛ و«قرأ ق والقرآن المجيد حتى قرأ والنخل باسقات، قال فجعلتُ أرددها ولا أدري ما قال»؛ و«كان يقرأ في الفجر بـ ق والقرآن المجيد وكان صلاته بعدُ تخفيفًا»؛ و«كان يخفف الصلاة ولا يصلي صلاة هؤلاء»...)`,
        o: NO_O,
        s: `(أي لا يدري تفسيرها.) (أي أن الصلوات الأخرى كان يخفف فيها (الظهر والعصر والمغرب والعشاء) فأطول صلاة كانت صلاة الفجر؛ وقيل: بعد ذلك الزمان في آخر عمره كان يخفف؛ والأول هو الصحيح لأن بعد صلاة الفجر كانت الصلوات أخف، لأنه ﷺ كان يقرأ ما بين الستين إلى المائة آية في الركعة أو الركعتين، وهنا دليل على أنها في الركعتين لأن سورة (ق) أقل من ستين آية وكان يقرؤها في الركعة الواحدة فدل ذلك على أن الستين إلى مائة في الركعتين، وأحياناً يقرأ في الركعة الواحدة من الستين إلى المائة.) (فالتطويل والتخفيف أمر نسبي، وهو دليل على أن بعض الناس في ذلك الزمن تطول جداً في قراءة الفجر، فبين له أن النبي ﷺ كان يصلي صلاةً خفيفة فيقرأ بـ ق، وهذا هو التخفيف المقصود.)`,
        f: [] },
      { q: `قراءة سورة الأعلى في الظهر، وقراءة «والمرسلات» و«الطور» في المغرب (وسبب إسلام جبير بن مطعم)`, p: `229`,
        n: `(أحاديث: «كان يقرأ في الظهر بـ سبح اسم ربك الأعلى وفي الصبح بأطول من ذلك»؛ و«كان يقرأ في صلاة الغداة من الستين إلى المائة»؛ وحديث أم الفضل في المرسلات في المغرب؛ وحديث جبير بن مطعم «سمعت رسول الله ﷺ يقرأ بالطور في المغرب».)`,
        o: NO_O,
        s: `(لهذا الحديث وللذي قبله: [كَانَ النَّبِيُّ ﷺ يَقْرَأُ فِي الظُّهْرِ بـ(اللَّيْلِ إِذَا يَغْشَى)] قلنا أنه كان أحياناً يقرأ في الظهر بأوساط المفصل.) (هذا دليل على قراءة النبي ﷺ بطوال المفصل أحياناً في صلاة المغرب وعدم الاقتصار على قصار المفصل.) (وهذه السورة (الطور) كانت سبب في إسلام جبير ابن مطعم ﷺ، (خ م حم) عَنْ جُبَيْرِ بْنِ مُطْعِمٍ قَالَ: (قَدِمْتُ عَلَى رَسُولِ اللَّهِ ﷺ (فِي فِدَاءِ الْمُشْرِكِينَ) (يَوْمَ بَدْرٍ)(- وَمَا أَسْلَمْتُ يَوْمَئِذٍ – فَدَخَلْتُ الْمَسْجِدَ ' وَرَسُولُ اللَّهِ ﷺ يُصَلِّي الْمَغْرِبَ ، فَقَرَأَ بِالطُّورِ) (فَلَمَّا بَلَغَ هَذِهِ الْآيَةَ: {أَمْ خُلِقُوا مِنْ غَيْرِ شَيْءٍ أَمْ هُمُ الْخَالِقُونَ، أَمْ خَلَقُوا السَّمَاوَاتِ وَالْأَرْضَ بَلْ لَا يُوقِنُونَ، أَمْ عِنْدَهُمْ خَزَائِنُ رَبِّكَ أَمْ هُمُ الْمُسَيْطِرُونَ} " ، قَالَ: كَادَ قَلْبِي أَنْ يَطِيرَ) (وَذَلِكَ أَوَّلَ مَا وَقَرَ الْإِيمَانُ فِي قَلْبِي). وقراءة النبي ﷺ دليل على القراءة في المغرب بطوال المفصل.)`,
        f: [] },
      { q: `قطع القراءة والقراءة ببعض السورة: هل يُكره؟ (أخذت النبي ﷺ سعلة)`, p: `230`,
        n: `قوله: (أخذ النبي ﷺ سعلة) هي بفتح السين، وفي هذا الحديث جواز قطع القراءة، والقراءة ببعض السورة، وهذا جائز بلا خلاف ولا كراهة فيه إن كان قطع لعذر، وإن كان لم يكن له عذر فلا كراهة فيه أيضًا ولكنه خلاف الأولى، هذا مذهبنا ومذهب الجمهور، وبه قال مالك رحمه الله تعالى في رواية عنه، والمشهور عنه كراهته.`,
        o: `مالك (المشهور عنه): يكره قطع السورة. الجمهور: لا كراهة، لكنه خلاف الأولى.`,
        s: `(هذا في قطع السورة، فيستحب عنده أن يكملها في الصلاة، أما قطع الآية فهي أولى بالكراهة؛ والأفضل قراءة السورة كاملة ويجوز قراءة بعض السورة أولها أو آخرها وهذا ثابت عن النبي ﷺ كما ذكرنا.)`,
        f: [] },
      { q: `معنى «عسعس» و«والنخل باسقات لها طلع نضيد»`, p: `231`,
        n: `قوله: (سمع النبي ﷺ يقرأ في الفجر والليل إذا عسعس) أي يقرأ بالسورة التي فيها: (والليل إذا عسعس) قال جمهور أهل اللغة: معنى عسعس: الليل أدبر، كذا نقله صاحب المحكم عن الأكثرين. ونقل الفراء إجماع المفسرين عليه، قال: قال آخرون: معناه أقبل، وقال آخرون: هو من الأضداد يقال: إذا أقبل، وإذا أدبر. وقوله ﷺ: {والنخل باسقات} أي طويلات. قوله تعالى: {لها طلع نضيد} قال أهل اللغة والمفسرون معناه منضود متراكب بعضه فوق بعض، قال ابن قتيبة: هذا قبل أن ينشق فإذا انشق كِمامه وتفرق فليس هو بعد ذلك بنضيد.`,
        o: `في «عسعس»: جمهور اللغة: أدبر. آخرون: أقبل. آخرون: من الأضداد.`,
        s: `(أي أن كلمة عسعس تستعمل استعمالين، فهي كلمة مشتركة بين (أقبل وأدبر) والصحيح أنها في هذا الموضع قول الجمهور أنه (والليل إذا عسعس) أي أدبر؛ لأن هذا فيه التبشير بظهور القرآن ونور الإسلام وزوال ظلام الشرك لأنه أقسم بالقرآن ومنزلته بعد ذلك.) (وهو دليل على أن النبي ﷺ كان يقرأ أحياناً في صلاة الصبح بالأواسط.) (وهذا ينافي الإجماع.) (فالنضيد: أي قبل أن تنشق الأكمام.)`,
        f: [] },
    ],
  },
  {
    title: `باب القراءة في العشاء (ص232–)`,
    items: [
      { q: `صلاة المفترض خلف المتنفّل (حديث معاذ) والاختلاف في ذلك`, p: `233–234`,
        n: `فيه حديث جابر: (إن معاذًا ﵁ كان يصلي مع النبي ﷺ، ثم يأتي فيؤم قومه، فصلى ليلة مع النبي ﷺ العشاء، ثم أتى قومه فأمّهم فافتتح بسورة البقرة، فانحرف رجل فسلّم ثم صلى وحده وانصرف، فقالوا أنافقت؟ ... إلى آخره) في هذا الحديث جواز صلاة المفترض خلف المتنفّل، لأن معاذًا كان يصلي الفريضة مع رسول الله ﷺ فيسقط فرضه، ثم يصلي مرة ثانية بقومه هي له تطوع ولهم فريضة، وقد جاء هكذا مصرحًا به في غير مسلم، وهذا جائز عند الشافعي رحمه الله تعالى وآخرين، ولم يُجزه ربيعة ومالك، وأبو حنيفة ﵁، والكوفيون، وتأولوا حديث معاذ ﵁ على أنه كان يصلي مع النبي ﷺ تنفلًا، ومنهم من تأوله على أنه لم يعلم به النبي ﷺ، ومنهم من قال: حديث معاذ كان في أول الأمر ثم نسخ، وكل هذه التأويلات دعاوى لا أصل لها فلا يُترك ظاهر الحديث بها.`,
        o: `الشافعي وآخرون: يجوز صلاة المفترض خلف المتنفل. ربيعة ومالك وأبو حنيفة والكوفيون: لا يجوز، وتأولوا الحديث (أنه كان يصلي مع النبي نفلًا، أو لم يعلم به النبي، أو نُسخ).`,
        s: `(أخرجه الدارقطني في سننه (١/ ٢٧٥) بلفظ: [أَنَّ مُعَاذاً كَانَ يُصَلِّي مَعَ النَّبِيِّ ﷺ الْعِشَاءَ ثُمَّ يَنْصَرِفُ إِلَى قَوْمِهِ فَيُصَلِّي بِهِمْ هِيَ لَهُ تَطَوُّعٌ وَلَهُمْ فَرِيضَةٌ].) (هذا التأويل ضعيف جداً لأن الرواية قالت (كان يصلي العشاء) وقد قال ﷺ: «إِذَا أُقِيمَتِ الصَّلاَةُ فَلاَ صَلاَةَ إِلاَّ الْمَكْتُوبَةَ» مسلم.) (دليل على القراءة بقصار المفصل أحياناً في العشاء؛ وابن القيم يقول قد قرأ هذا في السفر، ولكن لا يمنع من ذلك الاحتجاج بقراءة قصار المفصل أحياناً في العشاء في غيره.) (وهو دليل على القراءة في المغرب بطوال المفصل؛ وقراءة النبي ﷺ...)`,
        f: [`(ص233) وقال ﷺ لمعاذ: «أَفَتَّانٌ أَنْتَ يَا مُعَاذُ» — وهذا دليل على أن التطويل المنهي عنه هو ما يشق على المأمومين.`] },
      { q: `قطع المأموم الصلاة والخروج منها (أو الإتمام منفردًا) لعذر أو لغير عذر: الأوجه الثلاثة`, p: `234`,
        n: `واستدل أصحابنا وغيرهم بهذا الحديث على أنه يجوز للمأموم أن يقطع القدوة ويتم صلاته منفردًا وإن لم يخرج منها، وفي هذه المسألة ثلاثة أوجه لأصحابنا: أصحها أنه يجوز لعذر ولغير عذر، والثاني لا يجوز مطلقًا، والثالث يجوز لعذر ولا يجوز لغيره.`,
        o: `ثلاثة أوجه عند الشافعية: يجوز لعذر ولغيره (الأصح)؛ لا يجوز مطلقًا؛ يجوز لعذر لا لغيره.`,
        s: `(ولذا فالمأموم إذا عرض له عارض لقطع الصلاة فإنه يسلم، فنية قطع الصلاة سابقة على قطعها فإنها انقطعت بنية القطع ولكن يسلم منها. هذا هو الصحيح والاستدلال لهذه المسألة فيه نظر لأن الروايات التي ليس فيها ذكر التسليم هي قصة واحدة فلا يمكن تكرارها.) (والوجه الثالث هو الصحيح، فلا ينصرف من غير عذر لقوله ﷺ: (إنما جعل الإمام ليأتم به)، هذا رجل سلم قبل سلام الإمام فإن لم يكن بعذر فهذا منهي عنه، وهو مأمور بألا يقطع صلاة الفريضة، فلا يجوز الخروج من الفريضة إلا بسبب، وأما أنه لا يُسلم ويتم صلاته منفرداً فهذا ترك لصلاة الجماعة الواجب شهودها؛ ولأجل أنهم يقولون بعدم فرضية صلاة الجماعة فمن أجل ذلك بنوا أنه يجوز لغير عذر وإن كان مكروهاً، يقولون: (مكروه أن ينوي المفارقة من غير عذر) والصحيح أن ذلك ليس بجائز بل إذا تعينت الجماعة بالدخول فيها لم يجز له أن يقطعها إلا لعذر كعذر تطويل الإمام أو خوف فوات رفقة أو أصابه إسهال فله أن يكمل الصلاة منفرداً.)`,
        f: [] },
      { q: `العذر المسقط للجماعة، وهل تطويل القراءة وقصة معاذ عذر في التخلف (وتهمة معاذ ﵁ بالنفاق)، وحكم قطع الصلاة لمن بنى على صلاته`, p: `235–236`,
        n: `وعلى هذا: العذر هو ما يسقط به عنه الجماعة ابتداءً، ويعذر في التخلف عنها وتطويل القراءة عذر على الأصح لقصة معاذ ﵁، وهذا الاستدلال ضعيف، لأنه ليس في الحديث أنه فارقه وبنى على صلاته، بل في الرواية الأولى أنه سلّم وقطع الصلاة من أصلها، ثم استأنفها، وهذا لا دليل فيه للمسألة المذكورة، وإنما يدل على جواز قطع الصلاة وإبطالها لعذر. والله أعلم.`,
        o: NO_O,
        s: `(فوجه جواز الخروج منها لغير عذر عند الذين قالوا يجوز بغير عذر هو عدم وجوب صلاة الجماعة عندهم.) (العذر الذي يُجوز ذلك ما يسقط عنه الجماعة والذي هو خوف أو مطر.) (وهذا هو الصحيح، فالنبي ﷺ لم يلوم الرجل بل أنكر على معاذ ﵁ إنكاراً شديداً وجعل فعله فتنة لو استمر عليه، وإن كان قد عذره في اتهامه له بالنفاق متأولاً، فمن قال لأخيه يا كافر متأولاً ينكر عليه ولا يكون كافراً ولا منافقاً؛ فالحديث محمول على التغليظ أو أنه يأخذ أثم التكفير (حار عليه) أي رجع عليه أثم التكفير والحديث ليس على ظاهره في أنه يصبح كافراً، وحديث معاذ ﷺ حجة للجمهور على ذلك، فالتهمة بالنفاق تهمة بالكفر وقد يحمل على النفاق الأصغر.) (وهو الاستدلال على إكمال الصلاة بدون تسليم.) (وهذا هو الصحيح، فالفريضة يجب أن يستمر فيها ولا يجوز له أن يقطع الفريضة لأن النبي ﷺ قال (أفعل كذا ثم كذا ثم افعل ذلك في صلاتك كلها) فالفريضة إذاً لابد أن تؤدى كاملة بهذا الترتيب، فلا يجوز أن يجعل التسليم قبل الركوع قبل السجود ونحو ذلك، ولكن إن كان هناك عذر فعل، ولكن قد يُقال: إذا كان هذا عذر في قطع الصلاة برمتها وإبطالها فهو يدل بالأولى على جواز قطع الاقتداء فقط والذي هو متابعة الإمام للعذر، فإذا جاز قطع الصلاة ذاتها، فيجوز قطع نية الاقتداء والله أعلم وهذا هو الصحيح أنه يجوز هذا الأمر لعذر. فإذا طول الإمام فلا يخرج أو يخرج كلاهما جائز، فعلى سبيل المثال: رجل أدرك مع الإمام وعزم على الإتمام، فوجد الإمام قد طول جداً وقد نوى أن يصبر ولكن قد أصبح الأمر فوق طاقته، فبدل من أن نقول له أبطل الركعة الأولى، نقول له ينوي المفارقة، وكرجل في جماعة ويخاف فوات القطار وقد حضر القطار، فعليه أن يفارق ويبني على صلاته إن شاء أن يفعل ذلك. لأن خوف فوات الرفقة خوف وقد قال النبي ﷺ في إسقاط صلاة الجماعة خوف أو مرض، فعَنِ ابْنِ عَبَّاسٍ ﷺ، عَنِ النَّبِيِّ ﷺ، قَالَ: مَنْ سَمِعَ النِّدَاءَ فَلَمْ يَأْتِهِ ، فَلاَ صَلاَةَ لَهُ ، إِلاَّ مِنْ عُذْرٍ. (قال الألباني صحيح) (قَالُوا: وَمَا الْعُذْرُ؟ ، قَالَ: " خَوْفٌ ، أَوْ مَرَضٌ ") (هذه الزيادة من السؤال والجواب ضعيفة)، مثلها لو أن هناك مطر مما يؤذي الناس وهو يصلي مع الإمام وأهله بالخارج فيمكنه أن ينوي مفارقة الإمام، فيجوز أن يسلم كما فعل الصحابي وينصرف ويبدأ الصلاة بدون جديد منفرداً، فالحديث: (فَسَلَّمَ ثُمَّ صَلَّى وَحْدَهُ) ويجوز أن يكمل الصلاة على ما بدأ مع الإمام ويجوز أن يسلم ويبدأ الصلاة من جديد. أما إذا أبطل صلاته ورجع لم يبني على صلاته الأولى بلا شك لأن هذه الصلاة قد أبطلت بالسلام ونية قطعها.)`,
        f: [`(ص236) تغيير نية الفرض إلى النفل والنفل إلى الفرض لا يجوز لأن الفرض فريضة لا بد أن يؤديها من أول تكبيرة الإحرام، فتغيير نية النفل إلى الفرض لا يجوز لأن التكبير وقع نافلة ولم يقع فريضة فالواجب أن يأتي بالفريضة من أول قوله: (الله أكبر). — الترددفي نية الصلاة غير نية القطع فلابد أن ينوي القطع وإلا فالأصل استصحاب النية التي بدأت بها.`] },
      { q: `الابتداء بسورة البقرة وحكم تسمية السورة «سورة البقرة» ونحوها، ومعنى «أفتّان أنت يا معاذ»، وإنكار المنكر على من ارتكب مكروهًا`, p: `236–237`,
        n: `قوله: (فافتتح بسورة البقرة) فيه جواز قول سورة البقرة وسورة النساء وسورة المائدة ونحوها ومنعها بعض السلف وزعم أنه لا يقال إلا السورة التي يذكر فيها البقرة ونحو هذا، وهذا خطأ صريح، والصواب جوازه، فقد ثبت ذلك في الصحيح في أحاديث كثيرة من كلام رسول الله ﷺ وكلام الصحابة والتابعين وغيرهم. ويقال: سورة بلا همزة وبالهمزة لغتان ذكرهما ابن قتيبة وغيره، وترك الهمزة هنا هو المشهور الذي جاء به القرآن العزيز. قوله: (إنا أصحاب نواضح) هي الإبل التي يُستقى عليها جمع ناضح، وأراد إنا أصحاب عمل ونَعَب، فلا نستطيع تطويل الصلاة. قوله ﷺ: (أفتّان أنت يا معاذ) أي مُنفّر عن الدين وصادّ عنه. ففيه الإنكار على من ارتكب ما ينهى عنه وإن كان مكروهًا غير محرم. وفيه جواز الاكتفاء في التعزير بالكلام. وفيه الأمر بتخفيف الصلاة والتعزير على إطالتها إذا لم يرض المأمومون.`,
        o: NO_O,
        s: `(بل الظاهر أن هذا الأمر إذا كان يشق على الناس ربما وصل إلى ما هو أشد من ذلك لأن النبي ﷺ إنما يغضب ليس على من ترك المحرم، فالإمام يجب عليه ألا يطول.) (ورضى المأمومون يكون واحداً واحداً، فلا يأتي واحداً من الخارج لا يدري فيجد أن الصلاة قد طولت هذا التطويل الشديد، فلو شك فليخفف كما أمر النبي ﷺ.)`,
        f: [`(ص236) الأخرى: «ولا حرج في الأمر بالتخفيف...»`] },
    ],
  },
  {
    title: `باب أمر الأئمة بتخفيف الصلاة في تمام (ص237–240)`,
    items: [
      { q: `جواز التأخر عن صلاة الجماعة إذا عُلم من عادة الإمام التطويل الكثير، وذكر الإنسان ذلك في معرض الشكوى والاستفتاء`, p: `240`,
        n: `قوله: (إني لأتأخر عن صلاة الصبح من أجل فلان مما يطيل بنا) فيه جواز التأخر عن صلاة الجماعة إذا علم من عادة الإمام التطويل الكثير، وفيه جواز ذكر الإنسان بهذا ونحوه في معرض الشكوى والاستفتاء.`,
        o: NO_O,
        s: `(ولكن في زماننا عليه أن يبحث عن مسجد آخر.)`,
        f: [] },
      { q: `معنى أحاديث تخفيف الصلاة: الأمر للإمام بالتخفيف بحيث لا يخل بسننها ومقاصدها، وماذا يطوّل إذا صلى لنفسه (القيام والركوع والسجود والتشهد دون الاعتدال والجلوس بين السجدتين؟)`, p: `240`,
        n: `معنى أحاديث الباب ظاهر، وهو الأمر للإمام بتخفيف الصلاة بحيث لا يخل بسنتها ومقاصدها، وأنه إذا صلى لنفسه طوّل ما شاء في الأركان التي تحتمل التطويل وهي القيام والركوع والسجود والتشهد دون الاعتدال والجلوس بين السجدتين. والله أعلم.`,
        o: `الشافعية: لا يطوّل الاعتدال والجلوس بين السجدتين (لأنهما ركنان قصيران).`,
        s: `(التخفيف أمر نسبي يقاس بتخفيف النبي ﷺ فما صلى به النبي ﷺ فهو التخفيف.) (هذا غير صحيح من الإمام النووي فقوله (دون الاعتدال والجلوس بين السجدتين) هذا مذهب الشافعية، ولكن الصحيح أنه يطول هذين الركنين كذلك لأن أنس ﷺ قال: (كان يطول ذلك حتى نقول قد أوهم) وكان كما في حديث حذيفة ﷺ، فعَنْ حُذَيْفَةَ ، أَنَّ النَّبِيَّ ﷺ [قَرَأَ الْبَقَرَةَ وَآلَ عِمْرَانَ وَالنِّسَاءَ فِي رَكْعَةٍ ، لاَ يَمُرُّ بِآيَةِ رَحْمَةٍ إِلاَّ سَأَلَ وَلاَ بِآيَةِ عَذَابٍ إِلاَّ اسْتَجَارَ] قال الشيخ الألباني : صحيح. وذلك في النافلة وكان ركوعه قريباً من قراءته وكان اعتداله قريباً من ركوعه وهذا دليل على تطويل هذا الركن أيضاً، ولا عبرة بقول بعض الشافعية ببطلان الصلاة إذا طول هذه الأركان وأن هذا في النافلة.) (ظاهر الحديث وجوب التخفيف (فليخفف) ولكن التخفيف نسبي، وهذا دليل على أن صلاة الفجر داخلة في ذلك وأن التطويل زيادة عن الستين إلى مائة آية لا يجوز إلا بإذن المأمومين.)`,
        f: [] },
      { q: `الغضب في الموعظة (غضب النبي ﷺ لما يُنكر من أمور الدين)`, p: `240`,
        n: `قوله: (فما رأيت النبي ﷺ غضب في موعظة قط أشد مما غضب يومئذ فقال: يا أيها الناس إن منكم منفرين) الحديث فيه الغضب لما يُنكر من أمور الدين والغضب في الموعظة.`,
        o: NO_O,
        s: `الغضب في الموعظة يكون لأنه أشد في البيان والتحذير من الخطر والمخالفة لشرع الله ﷻ.`,
        f: [] },
      { q: `حديث عثمان بن أبي العاص «أمّ قومك»: الوسوسة في الصلاة، والتعوذ والتفل، والرقية ودعاء الرجل الصالح`, p: `241`,
        n: `قوله: (عن عثمان بن أبي العاص ﵁ أن النبي ﷺ قال له: أمّ قومك. قال: قلت يا رسول الله إني أجد في نفسي شيئًا فقال: ادنه فجلّسني بين يديه، ثم وضع كفه في صدري بين ثديي، ثم قال: تحوّل فوضعها في ظهري بين كتفيّ ثم قال: أمّ قومك) – قوله (ثديي وكتفيّ) بتشديد الياء على التثنية. وفيه إطلاق اسم الثدي على حلمة الرجل، وهذا هو الصحيح، ومنهم من منعه وقد سبق بيانه في كتاب الإيمان. قوله: (أجد في نفسي شيئًا) قيل: يحتمل أنه أراد الخوف من حصول شيء من الكبر والإعجاب له بتقدمه على الناس فأذهبه الله تعالى ببركة كف رسول الله ﷺ ودعائه، ويحتمل أنه أراد الوسوسة في الصلاة فإنه كان موسوسًا ولا يصلح للإمامة الموسوس، فقد ذكر مسلم في الصحيح بعد هذا عن عثمان بن أبي العاص قال: قلت: يا رسول الله إن الشيطان قد حال بيني وبين صلاتي وقراءتي يلبّسها علي فقال رسول الله ﷺ: «ذاك شيطان يقال له: خنزب فإذا أحسسته فتعوذ بالله واتفل عن يسارك ثلاثًا» ففعلت ذلك فأذهبه الله تعالى عني.`,
        o: NO_O,
        s: `(وهذا هو الاحتمال الأرجح مع دعاء النبي ﷺ له.) (وفيه: مشروعية الرقية ومشروعية دعاء الرجل الصالح لأتباعه إذا شكوا له أمراً.)`,
        f: [] },
      { q: `إدخال الصبي المسجد وبكاء الصبي في الصلاة، وصلاة النساء مع الرجال في المسجد، ومراعاة الرفق بالمأمومين`, p: `242`,
        n: `قوله (أن النبي ﷺ قال: إني لأدخل في الصلاة أريد إطالتها فأسمع بكاء الصبي فأخفف من شدة وجد أمه به) (الوجد) يُطلق على الحزن وعلى الحب أيضًا وكلاهما سائغ هنا، والحزن أظهر أي من حزنها واشتغال قلبها به. وفيه دليل على الرفق بالمأمومين وسائر الأتباع ومراعاة مصلحتهم، وألّا يدخل عليهم ما يشق عليهم، وإن كان يسيرًا من غير ضرورة. وفيه جواز صلاة النساء مع الرجال في المسجد، وأن الصبي يجوز إدخاله المسجد، وإن كان الأولى تنزيه المسجد عمن لا يؤمن منه حدث.`,
        o: NO_O,
        s: `(فالتطويل يمكن أن يكون يسيراً؛ فالنبي ﷺ لا يريد أن يُدخل الحزن على قلب امرأة تصلي معه في المسجد وليس بلازم لها صلاة الجماعة من أجل أنها تسمع بكاء ابنها.) (فالصبي الذي كان يبكي هو دون سن التمييز وهذا هو ظاهر القصة، ولذلك الأحاديث الواردة في أنّ النبي ﷺ قال: "جَنِّبُوا مَسَاجِدَكُمْ صِبْيَانَكُمْ، وَمَجَانِينَكُمْ، وَشِرَاءَكُمْ، وَبَيْعَكُمْ، وَخُصُومَاتِكُمْ، وَرَفْعَ أَصْوَاتِكُمْ، وَإِقَامَةَ حُدُودِكُمْ، وَسَلَّ سُيُوفِكُمْ..." (جة) ٧٥٠ [قال الألباني]: ضعيف، لا يستحب الإتيان بالأطفال إلى المسجد إلا بعد سن السابعة ولكن يباح ذلك لحاجة الأب والأم للإتيان إلى المسجد دون أن يترك الصبي وحده في المنزل، إذا كانت تريد أن تأتي إلى المسجد ولها صبيان، ولكن ينبغي تعليمهم آداب المسجد ما أمكن بل يجب ذلك.) (الحدث: ريح أو نجاسة، وهذا ليس بظاهر في هذا الحديث فلم يمنع النبي ﷺ النساء من الإتيان بصبيانهم أو منعهن من الإتيان إلى المساجد طالما معها صبي فالذي يظهر والله أعلم امتناع ذلك في حالة النجاسة فالأولى تجنب ما يتوقع منه حصول نجاسة، هذا إذا لم يمكن الاحتراز من ذلك ولكن لا يمنع من معه صبيان من الإتيان إلى المسجد.)`,
        f: [] },
      { q: `هل يجوز تغيير نية الفرض إلى النفل إذا صلى الفريضة قبل الوقت؟ وهل يسقط وجوب الجماعة عمن ينوي المفارقة؟ (فتوى)`, p: `242`,
        n: NO_N,
        o: NO_O,
        s: `هل يجوز تغيير النية من الفريضة إلى النافلة إذا صلى الفريضة قبل الوقت؟ لا، بل يخرج من الصلاة فهذه الصلاة وقعت باطلة، فإنه كبر قبل دخول الوقت ثم شعر بذلك يغير النية لا، بل يخرج وصلاته وقعت باطلة. هل الذي ينوي المفارقة يسقط عنه وجوب الجماعة؟ نعم إذا كان له عذر في المفارقة. (فتوى)`,
        f: [] },
    ],
  },
  {
    title: `باب اعتدال أركان الصلاة وتخفيفها في تمام (ص243–247)`,
    items: [
      { q: `إذا سلّم الإمام وقطع المأموم الصلاة خلف الإمام: هل يلزمه التشهد؟ ومن أي جزء يسلم؟ وصلاة الليل مثنى مثنى (فتوى)`, p: `243`,
        n: NO_N,
        o: NO_O,
        s: `هل إذا سلم المأموم وقطع الصلاة خلف الإمام، هل يلزم التشهد؟ لا يلزمه، يسلم من أي جزء من الأجزاء. صلاة الليل مثنى مثنى هذا في الأولوية ولكن يجوز أن يصليها أربعاً أربعاً إلا لحاجة كأن صلى معه آخر. (فتوى)`,
        f: [] },
      { q: `قول البراء «كانت صلاة رسول الله ﷺ وركوعه وسجوده وما بين السجدتين قريبًا من السواء»: تطويل الاعتدال والجلوس بين السجدتين (وخلاف الشافعية)`, p: `244–245`,
        n: `قوله: (رمقت الصلاة مع محمد ﷺ فوجدت قيامه فركعته فاعتداله بعد ركوعه فسجدته فجلسته ما بين التسليم والانصراف قريبًا من السواء) فيه دليل على تخفيف القراءة والتشهد وإطالة الطمأنينة في الركوع والسجود وفي الاعتدال عن الركوع وعن السجود، ونحو هذا قول أنس في الحديث الثاني بعده: (ما صليت خلف أحد أوجز صلاة من صلاة رسول الله ﷺ في تمام) وقوله: (قريبًا من السواء) يدل على أن بعضها كان فيه طول يسير على بعض، وذلك في القيام، ولعله أيضًا في التشهد، واعلم أن هذا الحديث محمول على بعض الأحوال وإلا فقد ثبتت الأحاديث السابقة بتطويل القيام وأنه ﷺ كان يقرأ في الصبح بالستين إلى المائة، وفي الظهر بـ (ألم تنزيل السجدة)، وأنه كان تقام الصلاة فيذهب الذاهب إلى البقيع فيقضي حاجته ثم يرجع فيتوضأ ثم يأتي المسجد فيدرك الركعة الأولى، وأنه قرأ سورة المؤمنين حتى بلغ ذكر موسى وهارون ﷺ، وأنه قرأ في المغرب بالطور وبالمرسلات، وفي البخاري بالأعراف وأشباه هذا، وكله يدل على أنه ﷺ كانت له في إطالة القيام أحوال بحسب الأوقات وهذا الحديث الذي نحن فيه جرى في بعض الأوقات.`,
        o: `الشافعية: لا تطال إطالة الاعتدال والجلوس بين السجدتين (وتبطل الصلاة بإطالتهما عند بعضهم).`,
        s: `(أوهم أو نسي: دليل على مشروعية الإطالة في هذا الركن خلافاً للشافعية القائلين بأن إطالة هذا الركن يبطل الصلاة وهذا من الزلات بلا شك؛ فإن الصحابة ظنوا أن النبي ﷺ قد نسي من تطويل الاعتدال بعد الركوع.) (التخفيف هنا تخفيف نسبي، لأن الأغلب الأعم إطالة القراءة عن هذه الأركان، ولذلك ذكر تخفيف القراءة والتشهد لأن الناس تعودت تطويلهما، وإطالة الطمأنينة في الركوع والسجود حتى يقترب الركوع والسجود وما بين السجدتين والاعتدال من القراءة والتشهد.) (وهذا هو الصحيح، لأن القراءة من الستين إلى مائة آية وأن يأمهم بالصافات يقتضي أن يكون القيام كان أطول بلا شك.) (وهذا دليل بالتأكيد عندما قرأ في المغرب بالأعراف، لا يمكن أن يكون الركوع والسجود قريب من القيام، فالأعراف تحتاج لأكثر من ساعة للقراءة المترسلة، فلو كان هناك ركوعين وأربع سجدات واعتدال وطمأنينة، فيستحيل أن يكون قبل العشاء، وهذا يدل على ما ذكره النووي رحمه الله.)`,
        f: [] },
      { q: `إطالة القيام بحسب الأوقات («كان» تدل على التكرار)، ومعنى «القعود»، وانصراف الإمام إلى جهة المأمومين، ومعنى «فجلسته ما بين التسليم والانصراف»`, p: `246`,
        n: `وقد ذكره مسلم في الرواية الأخرى، ولم يذكر فيه القيام، وكذا ذكره البخاري، وفي رواية للبخاري ما خلا القيام والقعود، وهذا تفسير الرواية الأخرى. وقوله: (فجلسته ما بين التسليم والانصراف) دليل على أنه ﷺ كان يجلس بعد التسليم شيئًا يسيرًا في مصلاه.`,
        o: NO_O,
        s: `(ولكن كلمة (كان) تدل على أنه كثيراً كان يفعل ذلك، ولذلك قال في أول شرح الباب: بالتخفيف في القراءة ويطيل في الركوع والسجود والطمأنينة في الاعتدال وبين السجدتين لكي تقترب منها.) (أي أنهم أطول من غيرهم؛ والقعود أي القعود للتشهد. ومقصود النووي أن الإطالة في الركوع والاعتدال حتى يكون قريباً من القراءة، والتخفيف فيها نسبي.) (قبل أن ينصرف إلى الصحابة أي قبل أن يلتفت إليهم بوجهه، وذلك أن عادتهم أنهم لم يكن أحد يقوم من مقامه حتى يلتفت إليهم النبي ﷺ فكان ذلك من أجل أن تنصرف النساء فيها ظنوا، فتنصرف النساء والناس جلوس على هيئتهم، فالمستحب ألا يتحرك المأمومون من أماكنهم ولا ينصرفوا من المسجد إلا بعد أن ينصرف إليهم الإمام فيستقبلهم بوجهه. وكان ينصرف أحياناً عن يمينه وأحياناً عن شماله إلى المأمومين وهذا هو الاستقبال بالوجه.)`,
        f: [] },
    ],
  },
  {
    title: `باب متابعة الإمام والعمل بعده (ص247–251)`,
    items: [
      { q: `ألا ينحني المأموم للسجود حتى يضع الإمام جبهته على الأرض: متابعة الإمام في السجود (ومتى يكبّر الإمام)، والقول بأن الإمام يكبر قبل الشروع`, p: `247, 249`,
        n: `(أحاديث البراء: «كانوا يصلون خلف رسول الله ﷺ فإذا رفع رأسه من الركوع لم أر أحدًا يحني ظهره حتى يضع رسول الله ﷺ جبهته على الأرض ثم يخر من وراءه سجدًا» وفي رواية «لم يحن أحد منا ظهره حتى يقع رسول الله ﷺ ساجدًا ثم نقع سجودًا بعده»). وفي هذا الحديث الأدب من آداب الصلاة وهو أن السنة ألا ينحني المأموم للسجود حتى يضع الإمام جبهته على الأرض، إلا أن يعلم من حاله أنه لو أخر إلى هذا الحد لرفع الإمام من السجود قبل سجوده. قال أصحابنا رحمهم الله تعالى: في هذا الحديث وغير ما يقتضي مجموعه أن السنة للمأموم التأخر عن الإمام قليلًا بحيث يشرع في الركن بعد شروعه وقبل فراغه منه. والله أعلم.`,
        o: `خلاف في وقت تكبير الإمام: هل يكبر وهو يهوي ساجدًا أم قبل الشروع؟ (قول الألباني: يكبر قبل الشروع في الحركة؛ وقول: يكبر حين يسجد؛ والجمهور: أثناء الانتقال).`,
        s: `(الانتقال ليس تبع لسماع التكبير وإنما تبع لرؤية حركة الإمام، ولذلك ينبغي أن يكبر أثناء النزول ليصل إلى وضعية السجود مباشرةً عقب التكبير لأن كثيراً من المأمومين لا يراه فهم يعتمدون على الصوت فقد كان النبي ﷺ يكبر حين يهوي ساجداً ويتم التكبير في السجود، فعلى أحد وجوه التفسير في أنه يتم التكبير في السجود بمعنى أنه يجعل آخر تمام لفظة (الله أكبر) عند إتمام السجود فالراء تقع وهو قد سجد. والتفسير الآخر: أنه يكبر حين يسجد ولا يهمل التكبير كما كان يهمله كثير من الأمراء في عهد التابعين فكانوا لا يكبرون في كل خفض ورفع، فكان مقصودهم التكبير في السجود أي حين يسجد. فيستحب له أن يكبر حين يهوي ساجداً أما إذا لم يفعل ذلك وأخذ بقول الألباني وهو قول ضعيف وهو أن يكبر قبل الشروع؛ فماذا يصنع المأموم؟ على المأموم ألا ينحني مع الإمام بل لا ينحني حتى يضع الإمام جبهته على الأرض؛ فإذا كان المأموم خلف الصف الأول فينظر إلى الصف الأول فإذا تحركوا تحرك وكل صف ينظر إلى من أمامه. وكون الإمام يكبر أولاً فهذا غير مستحب بل مخالفته للسنة وقد أوقع الناس في المحرم. السنة أن يكبر وهو يهوي وليس قبل أن ينزل فالمذهب الذي يقول يكبر عند الشروع مذهب ضعيف ويؤدي مع ضعفه إلى وقوع الناس في المحرم وهو المساواة والظاهر تحريمه لأنه يؤدي أحياناً إلى السبق والسبق متفق على تحريمه.) (وهو كما ذكر: أي أنه بعد أن يبدأ هو في الشروع في الركن بعد أن يكون الإمام قد وصل إليه فعلاً فالمأموم دائماً يركع إذا انحنى الإمام راكعاً ويرفع إذا رفع الإمام، وأما الرفع من جلسة الاستراحة فيرفع المأموم بعد أن يشرع الإمام في القيام من جلسة الاستراحة بحيث ألا ينتظر إلى أن يتم قيامه، لأن الإمام إنما يكبر وهو يرفع رأسه من السجود، ويشرع المأموم في السجود إذا وصلت جبهة الإمام إلى الأرض بنص الحديث.)`,
        f: [`(ص247) (قوله «فالأمر متعلق بالرؤية»: أي أن المتابعة تتعلق برؤية حركة الإمام.)`] },
      { q: `الرواية «وهو غير كذوب» في حديث البراء: من القائل (ابن معين: أبو إسحاق، وتخطئة النووي)، وإنكار تزكية الصحابي`, p: `248`,
        n: `قوله: (حدّثني البراء وهو غير كذوب أنهم كانوا يصلّون خلف النبي ﷺ ...) قال يحيى بن معين: القائل: (وهو غير كذوب) هو أبو إسحاق. قال: ومراده أن [عبد الله بن يزيد] غير كذوب وليس المراد [البراء] غير كذوب، لأن [البراء] صحابي لا يحتاج إلى تزكية، ولا يحسُن فيه هذا القول. وهذا الذي قاله ابن معين خطأ عند العلماء، بل الصواب أن القائل (وهو غير كذوب) هو [عبد الله بن يزيد]، ومراده أن [البراء] غير كذوب، ومعناه تقوية الحديث وتفخيمه والمبالغة في تمكينه من النفس لا التزكية التي تكون في مشكوك فيه، ونظيره قول ابن عباس ﵄: حدثنا رسول الله ﷺ وهو الصادق المصدوق، وعن أبي هريرة مثله، وفي صحيح مسلم عن أبي مسلم الخولاني حدّثني الحبيب الأمين عوف بن مالك الأشجعي، ونظائره كثيرة، فمعنى الكلام حدّثني البراء وهو غير متّهم كما علمتم فثقوا بها أخبركم عنه. قالوا: وقول ابن معين أن البراء صحابي فينزَّه عن هذا الكلام لا وجه له لأن عبد الله بن يزيد صحابي أيضًا معدود في الصحابة.`,
        o: `ابن معين: القائل «وهو غير كذوب» هو أبو إسحاق ويقصد عبد الله بن يزيد (وأن البراء صحابي لا يحتاج إلى تزكية). الصواب عند العلماء: القائل هو عبد الله بن يزيد، ومراده تقوية الحديث لا التزكية.`,
        s: `(هذا الحديث يدل على القراءة بأواسط المفصل أحياناً في صلاة الفجر لأن سورة التكوير من أواسط المفصل فيقرأ أحياناً بطواله وأحياناً بأوساطه.)`,
        f: [`(ص248) (فلا أقسم بالخنس الجوار الكنس) — هذا الحديث يدل على القراءة بأواسط المفصل أحيانًا في صلاة الفجر لأن سورة التكوير من أواسط المفصل فيقرأ أحيانًا بطواله وأحيانًا بأوساطه.`] },
      { q: `رواية «لا يحنو أحد منا ظهره حتى نراه قد سجد» والفرق بين «يحنو» و«يحني»، وتفسير الخنّس الجواري الكنّس`, p: `250–251`,
        n: `قوله: (لا يحنو أحد منّا ظهره حتى يراه قد سجد) هكذا هو في هذه الرواية الأخيرة من روايات البراء (يحنو) بالواو وباقي رواياته ورواية عمرو بن حريث بعدها كلها بالياء وكلاهما صحيح، فهما لغتان حكاهما الجوهري وغيره (حنيت وحنوت) لكن الياء أكثر، ومعناه عطفته، ومثله حنيت العود وحنوته عطفته. قوله تعالى: {فلا أقسم بالخنس} قال المفسرون وأهل اللغة: هي النجوم الخمسة: وهي المشترى وعطارد والزهرة والمريخ وزُحل هكذا قال أكثر المفسرين، وهو مروي عن علي بن أبي طالب ﵁، وفي رواية عنه أن هذه الخمسة والشمس والقمر، وعن الحسن هي كل النجوم، وقيل: غير ذلك. و(الخنّس) التي تخنس أي ترجع في مجراها، و(الكنّس) التي تكنس أي تدخل كناسها أي تغيب في المواضع التي تغيب فيها، والكنّس جمع كانس. والله تعالى أعلم بالصواب.`,
        o: `الخنس: الكواكب الخمسة (أكثر المفسرين وعلي)، أو الخمسة والشمس والقمر (رواية عن علي)، أو كل النجوم (الحسن)، وقيل غير ذلك.`,
        s: `(قول الحسن هو الأقرب فلا دليل على التخصيص.) (فهذا تفسير السلف، وليس النجوم التي تكنس تلك التفسيرات العلمية العجيبة؛ فالكنس أي التي تختفي والجواري أي الجارية، والخنس التي تخنس وترجع في مجراها وتختفي، وإنما تختفي النجوم مع آخر الليل والله أعلى وأعلم، وكما ذكرنا من قبل أن هذا الوقت كثر القسم به في القرآن خصوصاً القرآن المكي، تبشيراً بقرب ظهور نور الإسلام والله أعلم.)`,
        f: [] },
    ],
  },
  {
    title: `باب ما يقول إذا رفع رأسه من الركوع (ص251–257)`,
    items: [
      { q: `رواية «اللهم ربنا لك الحمد» بإسقاط «ربنا» أو بالجمع (اختصار الرواة وتعدد الروايات)`, p: `251`,
        n: `(أحاديث الباب (٤٠): باب ما يقول إذا رفع رأسه من الركوع) «كان رسول الله ﷺ إذا رفع ظهره من الركوع قال: سمع الله لمن حمده اللهم ربنا لك الحمد ملء السموات وملء الأرض وملء ما شئت من شيء بعد» ... وفي رواية «اللهم لك الحمد ملء السماء وملء الأرض...».`,
        o: NO_O,
        s: `(هنا من غير لفظ (ربنا)، ولكن لأن الظاهر أن المخرج واحد، فيكون هذا من اختصار بعض الرواة، ويمكن أن يحمل على التعدد فأحياناً كان يقولها (اللَّهم ربنا لك الحمد) وأحياناً يقول (اللَّهم لك الحمد).)`,
        f: [] },
      { q: `الذكر بعد الرفع من الركوع («ربنا لك الحمد ملء السماوات...»): معنى «حمدًا لو كان أجسامًا»، استحباب الذكر، وجوب الاعتدال والطمأنينة، والجمع بين «سمع الله لمن حمده» و«ربنا لك الحمد» لكل مصلٍّ، وبين «اللهم» و«الواو»`, p: `253`,
        n: `قال العلماء: معناه حمدًا لو كان أجسامًا لملأ السماوات والأرض. وفي هذا الحديث فوائد منها: – استحباب هذا الذكر، – ومنها وجوب الاعتدال ووجوب الطمأنينة فيه، – وأنه يستحب لكل مصلٍّ من إمام ومأموم ومنفرد أن يقول: سمع الله لمن حمده ربنا لك الحمد، ويجمع بينهما، فيكون قوله سمع الله لمن حمده في حال ارتفاعه، وقوله ربنا لك الحمد في اعتداله لقوله ﷺ: صلّوا كما رأيتموني أصلّي رواه البخاري.`,
        o: `الحنفية: لا يجب الاعتدال بعد الركوع (يجوز النزول مباشرة إلى السجود). أبو حنيفة وأحمد وغيرهما: المأموم يقول «ربنا لك الحمد» فقط. الحنابلة وبعض الشافعية: كل مصلٍّ يجمع بينهما.`,
        s: `(ولأن كل مخلوق في السماوات والأرض وكل مكان في السماوات وفي الأرض وما بينهما فهو دال على قدرة الله ووحدانيته وفيه من نعمه وإثبات صفات كماله ما يستحق الحمد عليه ﷻ.) (فجمع بين (اللهم)، (ربنا) وهناك نُسخ صحيحة جمعت بينها وبين (الواو) رداً على ابن القيم الذي نفى ثبوت الجمع بينها وبين الواو؛ فيجوز أن يقول: اللهم ربنا لك الحمد، ويجوز (ربنا لك الحمد)، ويجوز (اللهم ربنا ولك الحمد) فعَنِ ابْنِ عُمَرَ أَنَّهُ سَمِعَ النَّبِيَّ ﷺ يَقُولُ فِي صَلاَةِ الْفَجْرِ وَرَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ قَالَ [اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ] فِي الأَخِيرَةِ ثُمَّ قَالَ: اللَّهُمَّ الْعَنْ فُلاَنًا وَفُلاَنًا فَأَنْزَلَ اللَّهُ ﷻ: {لَيْسَ لَكَ مِنَ الأَمْرِ شَيْءٌ، أَوْ يَتُوبَ عَلَيْهِمْ، أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ} البخاري.) (خلافاً للحنفية القائلين بعدم وجوب الاعتدال بعد الركوع وجواز النزول من الركوع إلى السجود مباشرة والصحيح أن من فعل هذا بطلت صلاته لأن هذا ركن من الأركان علمه النبي ﷺ للمسيء صلاته.) (هذا الكلام فيه نظر؛ وهو قول الشافعية وبعض الحنابلة؛ فقد فعله النبي ﷺ إماماً ولم يثبت أنه فعله مأموماً، بل الظاهر أنه رغب في موافقة قول المأموم قول الإمام في (ربنا ولك الحمد) ولا يحصل ذلك لو قال المأموم (سمع الله لمن حمده) وإنما يوافقه ويوافق قول الملائكة إذا قال مباشرة (ربنا ولك الحمد) لظاهر قوله ﷺ: (فإذا قال (سمع الله لمن حمده) فقولوا: (ربنا ولك الحمد))، وأما قولهم: يقول المأموم (سمع الله لمن حمده) حال ارتفاعه ويقول: (ربنا ولك الحمد) حال اعتداله فإنه قال ﷺ: (صلوا كما رأيتموني أصلي)، نقول: هذا الحديث يطبق في الهيئة العامة وما لم يخصصه الدليل، وهذا قد خصصه الدليل وهو قوله ﷺ: (فإذا قال (سمع الله لمن حمده) فقولوا: (ربنا ولك الحمد)) وليس يحتاج إلى تقدير كلام آخر، فهم يقدرون فقولوا ربنا ولك الحمد بعد أن تقولوا أو مع قولكم سمع الله لمن حمده، وهذا خلاف الظاهر.)`,
        f: [] },
      { q: `معنى «سمع الله لمن حمده» (سمع بمعنى أجاب)، وضبط «مجزأة بن زاهر»، وإضافة «ماء البارد»، ومعنى «اللهم طهرني من الذنوب والخطايا»`, p: `254–255`,
        n: `قوله ﷺ: (سمع الله لمن حمده ربنا لك الحمد) قال العلماء معنى (سمع) هنا أجاب، ومعناه أن من حمد الله تعالى متعرضًا لثوابه استجاب الله تعالى له وأعطاه ما تعرض له فإنا نقول ربنا لك الحمد لتحصيل ذلك. قوله ﷺ: (حدثنا شعبة عن مجزأة بن زاهر) هو بميم مفتوحة ثم جيم ساكنة ثم زاي ثم همزة تُكتب ألفًا ثم هاء، وحكى صاحب المطالع فيه كسر الميم أيضًا ورجح الفتح، وحكي أيضًا ترك الهمز فيه قال: وقاله الحيّاني بالهمز. قوله ﷺ: (اللهم طهرني بالثلج والبرد وماء البارد) استعارة للمبالغة في الطهارة من الذنوب وغيرها، وقوله: (ماء البارد) هو إضافة الموصوف إلى صفته كقوله تعالى: {بجانب الغربي}، وقولهم مسجد الجامع، وفيه المذهبان السابقان مذهب الكوفيين أنه جائز على ظاهره، ومذهب البصريين أن تقديره ماء الطهور البارد، وجانب المكان الغربي، ومسجد الموضع الجامع. قوله ﷺ: (اللهم طهرني من الذنوب والخطايا) يحتمل أن يكون الجمع بينهما كما قال بعض المفسرين في قوله تعالى: {ومن يكسب خطيئة أو إثمًا} قال: الخطيئة المعصية بين العبد وبين الله تعالى، والإثم بينه وبين الآدمي. قوله: (كما ينقّى الثوب الأبيض من الوسخ) وفي رواية من [الدرن] وفي رواية من [الدنس] كلّه بمعنى واحد، ومعناه اللهم طهارة كاملة معتنى بها كما يعتنى بتنقية الثوب الأبيض من الوسخ.`,
        o: `الكوفيون: إضافة الموصوف إلى صفته جائزة على ظاهرها. البصريون: التقدير «ماء الطهور البارد».`,
        s: `(ويحتمل أن يكون من باب التأكيد المعنوي.)`,
        f: [] },
      { q: `إعراب «أهل الثناء والمجد» (النداء أم الرفع)، والاعتراض في الكلام (وكلنا لك عبد)، وأن «أحق ما قال العبد» هو الحمد، ومعنى «الجد» (الحظ أم الاجتهاد)`, p: `255–257`,
        n: `قوله: (أهل الثناء والمجد أحق ما قال العبد، وكلنا لك عبد، لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد) أما قوله: (أهل) فمنصوب على النداء هذا هو المشهور، وجوّز بعضهم رفعه على تقدير أنت أهل الثناء، والمختار النصب، والثناء والوصف الجميل والمدح، والمجد العظمة ونهاية الشرف، هذا هو المشهور في الرواية في مسلم وغيره، قال القاضي عياض: ووقع في رواية ابن ماهان (أهل الثناء والحمد) وله وجه، ولكن الصحيح المشهور الأول. وقوله (أحق ما قال العبد وكلنا لك عبد) هكذا هو في مسلم وغيره (أحق) بالألف، (وكلنا) بالواو، وأما ما وقع في كتب الفقه (حق ما قال العبد كلنا) بحذف الألف والواو فغير معروف من حيث الرواية وإن كان كلامًا صحيحًا، وعلى الرواية المعروفة تقديره [أحق قول العبد لا مانع لما أعطيت ولا معطي لما منعت.. إلى آخره]، واعترض بينهما (وكلنا لك عبد) ومثل هذا الاعتراض في القرآن كما قال الله تعالى: {فسبحان الله حين تمسون وحين تصبحون وله الحمد في السماوات والأرض وعشيًّا وحين تظهرون} اعترض قوله تعالى {وله الحمد في السماوات والأرض} ومثله قوله تعالى: {قالت رب إني وضعتها أنثى والله أعلم بما وضعت} على قراءة من قرأ وضعت بفتح العين وإسكان التاء ونظائره كثيرة ومنه قول الشاعر: [ألم يأتيك – والأنباء تنمي – بما لاقت لبون بني زياد] وقول الآخر: [ألا هل أتاها – والحوادث جمة – بأن امرأ القيس بن تملك يبقرا] ونظائره كثيرة. وإنما يعترض ما يعترض من هذا الباب للاهتمام به وارتباطه بالكلام السابق. وتقديره هنا [أحق قول العبد لا مانع لما أعطيت وكلنا لك عبد فينبغي لنا أن نقوله]. وقد أوضحت هذه المسألة بشواهدها في آخر صفة الوضوء من شرح المهذب. وفي هذا الكلام دليل ظاهر على فضيلة هذا اللفظ فقد أخبر النبي ﷺ الذي لا ينطق عن الهوى أن هذا أحق ما قاله العبد فينبغي أن يحافظ عليه لأن كلنا عبد ولا نهمله وإنما كان أحق ما قاله العبد لما فيه من التفويض إلى الله تعالى والإذعان له والاعتراف بوحدانيته، والتصريح بأنه لا حول ولا قوة إلا به، وأن الخير والشر منه، والحث على الزهادة في الدنيا والإقبال على الأعمال الصالحة. وقوله: (ذا الجد) المشهور فيه فتح الجيم هكذا ضبطه العلماء المتقدمون والمتأخرون. قال ابن عبد البر: ومنهم من رواه بالكسر، وقال أبو جعفر محمد بن جرير الطبري: هو بالفتح، قال: وقاله الشيباني بالكسر، قال: وهذا خلاف ما عرفه أهل النقل، قال: ولا يعلم من قال غيره وضعّف الطبري ومن بعده الكسر، قالوا: ومعناه على ضعفه الاجتهاد أي لا ينفع ذا الاجتهاد منك اجتهاده، إنما ينفعه وينجيه رحمتك، وقيل المراد ذا الجد والسعي التام في الحرص على الدنيا، وقيل معناه الإسراع في الهرب أي لا ينفع ذا الإسراع في الهرب منك هربه فإنه في قبضتك وسلطانك، والصحيح المشهور الجد بالفتح وهو الحظ والغنى والعظمة والسلطان، أي لا ينفع ذا الحظ في الدنيا بالمال والولد والعظمة والسلطان منك حظه أي لا ينجيه حظه منك، وإنما ينفعه وينجيه العمل الصالح، كقوله تعالى: {المال والبنون زينة الحياة الدنيا والباقيات الصالحات خير عند ربك} والله تعالى أعلم.`,
        o: `«أهل»: النصب على النداء (المشهور والمختار)، أو الرفع على تقدير «أنت أهل». «الجد»: بالفتح (الحظ والغنى والعظمة والسلطان — المشهور الصحيح)، بالكسر (الاجتهاد أو الإسراع في الهرب أو الجد في الدنيا — ضعيف).`,
        s: `(فجعل أحق ما قال العبد [لا مانع لما أعطيت ولا معطي لما منعت.. إلى آخره] والأظهر أن أحق ما قال العبد هو (الحمد) لقوله ﷺ: "أَفْضَلُ الذِّكْرِ لا إِلَهَ إِلاَّ اللَّهُ، وَأَفْضَلُ الدُّعَاءِ الْحَمْدُ لِلَّهِ"، (جة) ٣٨٠٠ [قال الألباني]: حسن.) (أي أن أصل الكلام { فَسُبْحَانَ اللَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ ﴿وَعَشِيًّا وَحِينَ تُظْهِرُونَ } واعترض بينها قوله تعالى { وَلَهُ الْحَمْدُ فِي السَّمَاوَاتِ وَالأَرْضِ }.) (وعلى القراءة الأخرى (والله أعلم بها وضعتُ) فهو جزء من كلامها.) (خلقاً وإيجاداً.) (أي لا ينجيه حظه منك أي من عقابك أي لا ينجيه إلا العمل الصالح كما قال تعالى: (الْمَالُ وَالْبَنُونَ زِينَةُ الْحَيَاةِ الدُّنْيَا وَالْبَاقِيَاتُ الصَّالِحَاتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًا وَخَيْرٌ أَمَلاً) فلا ينفع الجد صاحبه عند الله فلا ينفعه إلا العمل الصالح، فلا ينجيه من عقاب الله إلا رحمة الله ويطلبها بالعمل الصالح فلا ينفعه ماله وولده وسلطانه.)`,
        f: [] },
    ],
  },
  {
    title: `باب النهي عن قراءة القرآن في الركوع والسجود (ص258–)`,
    items: [
      { q: `المبشرات (الرؤيا الصالحة) والاستدلال بها، ومسائل حديث «ألا وإني نُهيت أن أقرأ القرآن راكعًا أو ساجدًا»: التسبيح والتعوذ في الفريضة والنافلة والدعاء في السجود، وفضيلة أبي بكر ﵁`, p: `258`,
        n: `(حديث ابن عباس: كشف رسول الله ﷺ الستارة والناس صفوف خلف أبي بكر فقال: «أيها الناس إنه لم يبق من مبشرات النبوة إلا الرؤيا الصالحة يراها المسلم أو ترى له، ألا وإني نُهيت أن أقرأ القرآن راكعًا أو ساجدًا فأما الركوع فعظّموا فيه الرب ﷻ وأما السجود فاجتهدوا في الدعاء فقمِنٌ أن يستجاب لكم».) [قمِن: خليق وجدير].`,
        o: NO_O,
        s: `(فيه مسائل: * لم ينقل عنه ﷺ أنه كان يسبح في آية التسبيح ويسأل في آية السؤال ويتعوذ في آية التعوذ إلا في النافلة، ولم يرد أن النبي ﷺ وقف يدعوا في الفريضة. * المبشرات هي التي كانت تأتي للأنبياء وهي من الوحي في حقهم وكانت قبل نزول الوحي عليهم، وبعد نزول الوحي كانت الرؤيا من أنواع الوحي لهم، ولذا فالرؤيا الصالحة من الأنواع التي تحصل للناس من مبشرات النبوة، وإذا كان الأمر كذلك صح الاستئناس بها مع بقاء الاستدلال بالأصل وهو الكتاب والسنة والإجماع وما تفرع عنها من مصادر التشريع، فالرؤيا الصالحة مما يراه المسلم أو ترى له فهذه من مبشرات النبوة مما يبشر الله به عباده المؤمنين كما قال تعالى: (لهم البشرى في الحياة الدنيا وفي الآخرة) فهذا مما يهون على أهل الإيمان أمور الفتن التي تكثر في آخر الزمان ولذا إذا اقتربت الساعة لم تكد تخطئ رؤيا المؤمن، ولكن كما قلنا يستأنس بها ولا يستدل بها لأن الوحي القاطع المقطوع به بالصدق هو الوحي الموحى للأنبياء له لا إلى الأولياء، فأما مبشرات الأولياء والوحي لهم كالإلهام فإنه لا يكون قاطعاً فلا يقدم على القواطع بل يكون محتملاً لأن أفضل الصديقين أبو بكر الصديق ﷺ قال له النبي ﷺ في الرؤيا التي أولها: (أصبت بعضاً وأخطأت بعضاً)، فإذا كان أفضل الصديقين بعد الأنبياء قد أخطأ بعضاً في تأويل الرؤيا فغيره أولى بالخطأ، وتركه النبي ﷺ له دون أن يبين له الخطأ ليبقى أمر الرؤيا كما ذكرنا على التبشير يستأنس بها ولا يستدل بها والله أعلم. * وفيه فضيلة أبو بكر الصديق ﷺ لأنه الذي كان يصلي الناس خلفه في مرض رسول الله ﷺ.)`,
        f: [] },
      { q: `قراءة القرآن في الركوع والسجود: حكمها، وقراءة الفاتحة فيهما (كراهة أم تحريم؟ وبطلان الصلاة؟)، وسجود السهو`, p: `260–261`,
        n: `قوله ﷺ: (نُهيت أن أقرأ القرآن راكعًا أو ساجدًا، فأما الركوع فعظّموا فيه الرب وأما السجود فاجتهدوا في الدعاء فقمِن أن يُستجاب لكم) وفي حديث علي ﵁: (نهاني رسول الله ﷺ أن أقرأ راكعًا أو ساجدًا) فيه النهي عن قراءة القرآن في الركوع والسجود، وإنما وظيفة الركوع التسبيح، ووظيفة السجود التسبيح والدعاء، – فلو قرأ في ركوع أو سجود غير الفاتحة كره ولم تبطل صلاته، – وإن قرأ الفاتحة ففيه وجهان لأصحابنا: أصحهما أنها كغير الفاتحة فيُكره ولا تبطل صلاته، والثاني يحرُم وتبطل صلاته، هذا إذا كان عمدًا، – فإن قرأ سهوًا لم يُكره، وسواء عمدًا أو سهوًا يسجد للسهو عند الشافعي رحمه الله تعالى.`,
        o: `وجهان عند الشافعية في قراءة الفاتحة في الركوع والسجود: كغير الفاتحة (يُكره ولا تبطل) أو يحرم وتبطل. الشافعي: يسجد للسهو سواء كان عمدًا أو سهوًا.`,
        s: `(الأظهر أنه يحرم ولا تبطل صلاته لأن النهي لا صارف له وبطلان الصلاة يحتاج إلى دليل مستقل.) (لأنه معفي عنه قال ﷺ: «وضع عن أمتي الخطأ والنسيان».) (أما أن يقرأ عمداً ويسجد للسهو ففيه نظر فإنما شرع سجود السهو لمن سها، أما من تعمد فقد أثم أو على الأقل نقص ثوابه أو بطلت صلاته على وجه من يبطلها.)`,
        f: [] },
      { q: `معنى «فعظّموا فيه الرب»: حكم الذكر في الركوع والسجود (وجوب تسبيحة واحدة، ومذهب أحمد وأهل الحديث والجمهور)، وسبب الاستحباب للجمع بين التسبيح والدعاء`, p: `261–262`,
        n: `وقوله ﷺ: (فأما الركوع فعظّموا فيه الرب) أي سبّحوه ونزّهوه وجّدوه، وقد ذكر مسلم بعد هذا الأذكار التي تقال في الركوع والسجود، واستحب الشافعي رحمه الله تعالى وغيره من العلماء أن يقول في ركوعه: [سبحان ربي العظيم]، وفي سجوده: [سبحان ربي الأعلى]، ويكرّر كل واحدة منهما ثلاث مرات، ويضم إليه ما جاء في حديث علي ﵁ ذكره مسلم بعد هذا: [اللهم لك ركعتُ اللهم لك سجدتُ.. إلى آخره]. وإنما يُستحب الجمع بينهما لغير الإمام، وللإمام الذي يعلم أن المأمومين يؤثرون التطويل، فإن شك لم يزد على التسبيح، ولو اقتصر الإمام والمنفرد على تسبيحة واحدة فقال: [سبحان الله] حصّل أصل سنة التسبيح، لكن ترك كمالها وأفضلها. واعلم أن التسبيح في الركوع والسجود: – سنة غير واجب هذا مذهب مالك وأبي حنيفة والشافعي رحمهم الله تعالى والجمهور. – وأوجبه أحمد رحمه الله تعالى وطائفة من أئمة الحديث لظاهر الحديث في الأمر به، ولقوله ﷺ: «صلوا كما رأيتموني أصلي» وهو في صحيح البخاري، وأجاب الجمهور بأنه محمول على الاستحباب، واحتجوا بحديث المسيء صلاته فإن النبي ﷺ لم يأمره به، ولو وجب لأمره له.`,
        o: `الجمهور (مالك وأبو حنيفة والشافعي): التسبيح سنة غير واجب. أحمد وطائفة من أئمة الحديث: واجب. الشافعية: يقتصر الإمام على التسبيح إن خاف التطويل.`,
        s: `(بل الظاهر وجوب الذكر في الركوع والسجود ولو مرة بالأذكار الواردة وذلك للأمر: (عظموا فيه الرب) فأقل ذلك أن يقول (سبحان ربي العظيم) مرة أو في معنى ذلك مما ورد مثل أن يقول (سبحانك اللهم ربنا وبحمدك اللهم اغفر لي) فلو عظم الرب بأي أمر صح ذلك، وظاهر قوله تبارك وتعالى: (فسبح باسم ربك العظيم) وظاهر الأمر الوجوب ولا وجوب خارج الصلاة، فتعين أن ذلك في الصلاة، وهو مذهب الإمام أحمد. – فعن الإمام أحمد أن ذكر الركوع والسجود واجب ولو مرة ويستحب الزيادة من ثلاث إلى عشر، وأكثر العلماء على أنه يستحب الثلاثة؛ فإن تركه عمداً بطلت الصلاة وإن تركه سهواً جبر بسجود السهو وهو من أصح المذاهب في هذه المسألة وعن أهل الحديث وأهل الظاهر مثل ذلك من وجوب أن يذكر شيئاً من الأذكار ولو مرة واحدة؛ أما الجمهور فقالوا إن ركع دون أن يذكر شيئاً صح وكره له ذلك.) (الأقرب أنه لا يكره طالما لم يزد على قدر عشر تسبيحات قدر سجود وركوع النبي ﷺ، فإذا قرأ شيئاً من الأذكار الواردة في الركوع والسجود بعد تسبيح الركوع وتسبيح السجود والدعاء إلى أن يكون قدر المجموع يُحذر بقدر عشر تسبيحات فلا حرج عليه في ذلك ولا يكره بل يستحب لأن تخفيف النبي ﷺ كما ذكرنا مرات هو المأمور به فالأمر بالتخفيف نسبي وهذا في الفريضة، أما النفل فإنه لو صلى بالناس صلاة مشروعة جماعة كالتراويح كان كذلك كالفريضة أما غير ذلك فليطول ما شاء لنفسه ولمن أراد أن يصلي معه. – حديث عشر تسبيحات فيه مقال ولكن إسناده مقارب إن شاء الله، عن وهب بن مانوس، قال: سمعت سعيد بن جبير، يقول: سمعت أنس بن مالك، يقول: ما صليت وراء أحد بعد رسول الله ﷺ أشبه صلاة برسول الله ﷺ من هذا الفتى – يعني عمر بن عبد العزيز – قال: "فحزرنا في ركوعه عشر تسبيحات، وفي سجوده عشر تسبيحات"، قال الأرنؤوط: حديث حسن دون قوله: "فحزرنا في ركوعه ..."، وهذا إسناد ضعيف وقال الألباني كذلك.) (وهذه حجة ظاهرة عليهم في أنهم أوجبوا أشياء ليست في حديث المسيء صلاته، وقلنا لا تتم هذه الحجة حتى يثبت أن حديث المسيء صلاته ليس فيه شيء من الواجبات خلاف الأركان، فالصحيح أن حديث المسيء صلاته في الأركان، وأما الواجبات فتؤخذ من أحاديث النبي ﷺ الأخرى، فعلمه ما لا تصح صلاته إلا به لأنه كان جاهلاً ولم يعلمه كل ما يلزمه إنما تلزمه الواجبات الأخرى إذا علمها فلم يكثر عليه حتى يستطيع أن يتعلمها.)`,
        f: [] },
      { q: `الأسئلة المتعلقة بحديث المسيء صلاته: لماذا لم يأمر النبي ﷺ المسيء بالنية والتشهد والسلام؟ (الرد: كانت معلومة عنده؟)، وتقسيم الصلاة إلى أركان وواجبات وسنن`, p: `263`,
        n: `فإن قيل: فلم يأمره بالنية والتشهد والسلام فقد سبق جوابه عن شرحه.`,
        o: `جواب النووي: أنها كانت معلومة عنده.`,
        s: `(أي أنها محمولة – عندهم – على أنها معلومة عنده وهو تأويل ضعيف جداً لأن استقبال القبلة على الأقل كان معلوماً عنده ومع ذلك قال له: (إذا قمت إلى الصلاة فأسبغ الوضوء واستقبل القبلة وكبر..)، وقلنا أننا لا نسلم على أنه لم يأمره بالنية بل أمره بقوله: (إذا قمت إلى الصلاة) وأمره بالقيام وقال له: (فأسبغ الوضوء واستقبل القبلة وكبر) وأقل هذه الأمور أنها كانت معلومة عنده وإلا فما الذي فعله؟ فإذا لم يفعل هذه الأشياء لا يقال عليه صلى ثم أتى، فإنه قد فعل شيئاً فقد قام على الأقل ومع ذلك أمره بالقيام، وبالتالي فهذه الحجة ساقطة ولكن بالفعل حديث المسيء صلاته حجة ظاهرة في عدم وجوب التشهد والسلام والصلاة على النبي ﷺ، وبالتالي من البعيد جداً أن يكون هذا الرجل يعرف وجوب الصلاة على النبي ﷺ ولا يعرف وجوب الفاتحة، فهذا أمر عجيب ولذلك الحجة ثابتة عليهم في ذلك وأما عدم الوجوب فلا وإنما نقول هو واجب وليس بركن.) (ففي الصلاة الأفعال والأقوال على ثلاثة أقسام: ١– الأركان: والعمدة فيها أحاديث المسيء صلاته بطرقه، ولا تصح الصلاة إلا بها سواء تركها جهلاً أو عمداً أو نسياناً فلابد أن يأتي بها ونقول لمن لم يأتِ بها (ارجع فصلِ فإنك لم تصل). ٢– الواجبات: وتؤخذ من أوامر النبي ﷺ وأفعاله في الصلاة مع قوله ﷺ: (صلوا كما رأيتموني أصلي) ومما لا صارف له عن الوجوب إلى الاستحباب سواء الصارف قول أو فعل فيكون الأصل الوجوب. ٣– السنن المستحبة مؤكدة أو غيرها: فتؤخذ من أقوال النبي ﷺ وأفعاله التي صرفت عن الوجوب إلى الاستحباب بنص أو إجماع.) (ولذلك نقول بوجوب تسبيح الركوع والسجود ولكن ليس بركن من الأركان.)`,
        f: [] },
      { q: `الدعاء في السجود: الجمع بين الدعاء والتسبيح، والدعاء بما شاء من القرآن (على جهة الدعاء لا التلاوة)`, p: `263`,
        n: `قوله ﷺ: (فقمِن) هو بفتح القاف وفتح الميم وكسرها لغتان مشهورتان، فمن فتح فهو عنده مصدر لا يُثنى ولا يُجمع، ومن كسر فهو وصف يُثنى ويُجمع وفيه لغة ثالثة (قمين) بزيادة ياء وفتح القاف وكسر الميم، ومعناه حقيق وجدير. وفيه الحثّ على الدعاء في السجود فيُستحب أن يجمع في سجوده بين الدعاء والتسبيح وسيأتي الأحاديث فيه.`,
        o: NO_O,
        s: `(فيدعو بها شاء والدعاء بها في القرآن من أدعية على جهة الدعاء لا على جهة التلاوة وقراءة القرآن فصحيح، على جهة تأويل القرآن فصحيح، والمنهي عنه أن يتلوها على جهة التلاوة.)`,
        f: [] },
      { q: `معنى «معصوب الرأس» وشدة مرض النبي ﷺ، وقول «نهاني ولا أقول نهاكم»: هل النهي خاص؟ واختلاف الرواة في ذكر ابن عباس بين إبراهيم بن حنين وعلي`, p: `264`,
        n: `قوله: (ورأسه معصوب) فيه عصب الرأس عند وجعه. قوله: (نهاني ولا أقول نهاكم) ليس معناه أن النهي مختص به، وإنما معناه أن اللفظ الذي سمعته بصيغة الخطاب لي فأنا أنقله كما سمعته وإن كان الحكم يتناول الناس كلهم. ذكر الاختلاف على إبراهيم بن حنين في ذكر ابن عباس بين علي وعبد الله بن حنين. قال الدارقطني: من أسقط ابن عباس أكثر وأحفظ. قلت: وهذا اختلاف لا يؤثر في صحة الحديث، فقد يكون عبد الله بن حنين سمعه من ابن عباس عن علي، ثم سمعه من علي نفسه، وقد تقدمت هذه المسألة في أوائل هذا الشرح مبسوطة. قوله: (نهاني حِبّي ﷺ) هو بكسر الحاء والباء أي محبوبي.`,
        o: NO_O,
        s: `(وشدة ما كان عليه النبي ﷺ من مرض الذي توفي فيه.) (لأن الأصل عدم التخصيص واستواء الأحكام لعموم المكلفين سواء النبي ﷺ فمن دونه ما لم يأتِ دليل على الخصوصية. وهذا من دقته في نقل الرواية فلم يكن أحد معه عند سماع النهي فلم يقل النبي ﷺ لمجموع فينقلها كما سمعها.) (وهذا هو الصحيح والظاهر، لأنه كان قد سمعه من ابن عباس ثم شافه علياً به فرواه عن علي ﷺ مباشرةً.)`,
        f: [] },
    ],
  },
  {
    title: `باب ما يقال في الركوع والسجود (ص265–271)`,
    items: [
      { q: `معنى «أقرب ما يكون العبد من ربه وهو ساجد»: القرب من الله بالروح والبدن، وتأويل المخالفين وطريقة السلف`, p: `267`,
        n: `معناه أقرب ما يكون من رحمة ربه وفضله. وفيه الحث على الدعاء في السجود. وفيه دليل لمن يقول إن السجود أفضل من القيام وسائر أركان الصلاة، وفي هذه المسألة ثلاثة مذاهب.`,
        o: NO_O,
        s: `(هذا من التأويل المخالف لطريقة السلف، فالسلف يمرون هذه الأحاديث على ظاهرها؛ والعبد يقرب من ربه بنص الكتاب والسنة (واسجد واقترب)، وقال النبي ﷺ: (أقرب ما يكون العبد من ربه وهو ساجد) فنحن لا يجوز لنا أن نرى نقصاً أو فهماً غير صحيح يظهر من هذا الحديث، فما تكلم النبي ﷺ إلا بها يظهر منه الحق وكلامه يصان عن الظنون الكاذبة، مثل الظن أن هذا القرب كقرب الأجسام من الأجسام ولكن يقال يقترب العبد بروحه من ربه ﷻ وهذا القرب فيما يتعلق بصفة الرب ﷻ بأنه يُقرب منه بها يليق بجلاله وعظمته، وإذا كنا لا ندري كيفية قرب الأرواح من الأرواح المخلوقة مع كون الأمر محسوس يدرك بالحس، فالإنسان يشعر مع قرب بدنه من آخر بالبعد عنه والوحشة والكراهية وغير ذلك من لوازم قرب الأرواح، ويشعر بحب وألفة وهي من لوازم قرب الأرواح رغم بعد المسافات، فإذا كان هذا الأمر محسوساً فها المانع أن يشعر بذلك بتقربه إلى الله بالطاعات الفرائض والنوافل فكيف ننكر القرب من الله بالروح، وكيف وقد أثبت الرب ﷻ قربه من عبده الذي يتقرب إليه فقال سبحانه: (من تقرب إليّ شبراً تقربت إليه ذراعاً) فهذا قربه ﷻ قرب يليق بجلاله فهو يقرب ويُتقرب إليه فقرب الأرواح لا ندري كيف تكون فكيف بالقرب من الله فلا ندري الكيفية وإن كان أمراً معلوماً. – فالعباد المؤمنون يشعرون بقربهم من الله ﷻ ومن لوازم ذلك القرب من الفضل ولكن لا يقال أن معنى القرب من الله القرب من رحمته وفضله فهذا الكلام غير صحيح ولكنه من لوازمه ولكنه يقرب من ربه فعلاً بروحه فليس كل قرب في الوجود يكون قرب أجسام من أجسام حتى نقول يلزم من ذلك التشبيه فكما قلنا هناك قرب أرواح غير معروف الكيفية فكيف بها هو أولى في عدم معرفة الكيفية، فنثبت ما أثبته النبي ﷺ بعد إثبات الكتاب والأحاديث القدسية بذلك، ولا نؤول هذا التأويل المخالف لطريقة السلف. – فالقرب قرب أرواح لا أبدان لأن البدن في الأرض وهو ساجد في الأرض وهذا مما لا يختلف فيه عاقلان، أما النبي ﷺ اختص بالمعراج بأن عرج بروحه وجسده. – ودليل القرب بالروح دليل عقلي فليس هناك في المسألة دليل شرعي والدليل العقلي دليل ليس بملغي أو مهمل كقوله تعالى: (تُدَمِّرُ كُلَّ شَيْءٍ بِأَمْرِ رَبِّهَا) فخرج من (كل شيء) الأرض والسماء بدليل العقل فلم تدمر بالريح التي أرسلها الله على عاد فبقاء الأجساد في الأرض أثناء السجود فهذا مما دل عليه العقل وصعود الأرواح يؤكده العقل.)`,
        f: [] },
      { q: `أيهما أفضل: تطويل القيام أم تكثير الركوع والسجود؟ (مذاهب ثلاثة)، وتعقيب الشيخ في التوفيق`, p: `268`,
        n: `– أحدها أن تطويل السجود وتكثير الركوع والسجود أفضل، حكاه الترمذي والبغوي عن جماعة، وممن قال بتفضيل تطويل السجود ابن عمر رضي الله عنهما. – والمذهب الثاني مذهب الشافعي ﵁ وجماعة أن تطويل القيام أفضل لحديث جابر في صحيح مسلم أن النبي ﷺ قال: «أفضل الصلاة طول القنوت». والمراد بالقنوت القيام، ولأن ذكر القيام القراءة، وذكر السجود التسبيح، والقراءة أفضل، لأن المنقول عن النبي ﷺ أنه كان يطوّل القيام أكثر من تطويل السجود. – والمذهب الثالث أنهما سواء وتوقف أحمد بن حنبل ﵁ في المسألة ولم يقض فيها بشيء. وقال إسحاق بن راهويه: أما في النهار فتكثير الركوع والسجود أفضل، وأما في الليل فتطويل القيام إلا أن يكون للرجل جزء بالليل يأتي عليه فتكثير الركوع والسجود أفضل؛ لأنه يقرأ جزأه ويربح كثرة الركوع والسجود. وقال الترمذي: إنما قال إسحاق هذا لأنهم وصفوا صلاة النبي ﷺ بالليل بطول القيام ولم يوصف من تطويله بالنهار ما وصف بالليل والله أعلم.`,
        o: `ابن عمر وجماعة: تكثير الركوع والسجود وتطويل السجود أفضل. الشافعي وجماعة: تطويل القيام أفضل. وقيل: سواء، وتوقف أحمد. إسحاق: بالنهار تكثير الركوع والسجود وبالليل تطويل القيام (إلا لمن له جزء).`,
        s: `(الأفضل أن يكون السجود قريباً من القيام، بأن يطيل القيام ويكون الركوع والسجود قريباً من القيام، فيكون القيام أطول منها ولكن يقرب.)`,
        f: [] },
      { q: `معنى «اللهم اغفر لي ذنبي كله دقه وجله» (دِقّه): هل الأنبياء يذنبون؟ وكثرة ألفاظ الدعاء`, p: `268–269`,
        n: `قوله ﷺ: (اللهم اغفر لي ذنبي كله دقه وجله) هو بكسر أولها أي قليله وكثيره، وفيه توكيد الدعاء وتكثير ألفاظه، وإن أغنى بعضها عن بعض.`,
        o: `الخلاف في عصمة الأنبياء من الصغائر (مذكور في الهامش).`,
        s: `(في الحقيقة كل واحدة منهم مختلفة فلا أدري كيف قال أنه يعني بعضها عن بعض وقد اختلف المعنى في الدعاء، فكثرة أنواع الذنوب يوحي بالانكسار لله ﷻ والتضرع والفقر إليه ﷺ وضعف الذنب يجلب الجبر بإذن الله تبارك وتعالى فالمقصود هو الذنب القليل الدقيق الذي لم يتكرر كثيراً ويفعلها نادراً، والذنب الكثير الذي يتكرر كثيراً منه، فيطلب مغفرة هذا وذاك؛ وحتى لو قلنا أنه كبير وصغير فالكبائر غير الصغائر؛ فكلام النبي ﷺ لا يستغني عن شيء منه.) (أحتج بهذه الأحاديث من يقول بعدم عصمة الأنبياء من الصغائر والصحيح والله أعلم أن الأنبياء لهم ما يسمى ذنوب هذا مما يقطع به لأن القرآن والسنة سماها ذنوب ولكن هل هذه الذنوب مثل ذنوب البشر من جهة أنهم يتعمدون فعلها وأنها خالفت أمر الله أم هي من قبيل النسيان والخطأ في الاجتهاد والفتور عن الذكر وترك الأولى وهذا هو الصحيح وهذا يسمى ذنوباً في حقهم لعلو شأنهم من باب حسنات الأبرار سيئات المقربين فعُد السهو منهم ذنباً لعموم قوله تعالى: (أولئك الذين هدى الله فبهداهم اقتده)، فكل هديهم يقتدى به وكذا قوله: (فمن يطع الله إن عصيته) فلو وجد من الأنبياء من عصى الله لما وجد أحد يطيع الله ﷺ.)`,
        f: [`(ص268) لأن تأويل الأمر هو فعل المأمور به، وتأويل النهي هو ترك المنهي عنه، وتأويل الخبر وقوع المخبر به، ولذلك كل أدعية القرآن إذا قالها على جهة الدعاء فهو تأويل له. (تعليقًا على ص269.)`] },
      { q: `قول عائشة «كان يكثر أن يقول في ركوعه وسجوده: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي يتأول القرآن»: معنى «يتأول القرآن»، ومعنى التسبيح (التنزيه)`, p: `269`,
        n: `قولها: (كان رسول الله ﷺ يُكثر أن يقول في ركوعه وسجوده: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي يتأول القرآن) وفي الرواية الأخرى (أستغفرك وأتوب إليك). معنى يتأوّل القرآن: يعمل ما أُمر به في قول الله ﷻ: {فسبّح بحمد ربك واستغفره إنه كان توّابًا} وكان ﷺ يقول هذا الكلام البديع في الجزالة المستوفي ما أمر به في الآية، وكان يأتي به في الركوع والسجود لأن حالة الصلاة أفضل من غيرها، فكان يختارها لأداء هذا الواجب الذي أُمر به ليكون أكمل. قال أهل اللغة العربية وغيرهم: التسبيح التنزيه، وقولهم: سبحان الله منصوب على المصدر، يقال: سبّحت الله تسبيحًا وسبحانًا، فسبحان الله معناه براءة وتنزيهًا له من كل نقص وصفة للمحدِث.`,
        o: NO_O,
        s: `(أي يتصف بها المخلوق في الكيفية التي يتصف بها المخلوق وليس على الإطلاق؛ فالمحدث يسمع فهل ننفي عن الله صفة السمع؟ فالمقصود بها كيفية صفة المحدث المخلوق لأن صفات الرب ﷻ منزهه عن مشابهة كيفية صفات المخلوقين وإلا فالله ﷻ قد جعل لبعض خلقه بعض صفات الكمال التي يتصفوا بها ولكن بكيفية تليق بهم كمخلوقين بخلاف كيفية اتصافه سبحانه وعز وجل.)`,
        f: [] },
      { q: `معنى «وبحمدك سبحتك» و«الأفعال له»، وجواز «أستغفرك وأتوب إليك» وكراهة بعض السلف لها، وقوله «اغفر لي ذنبي كلّه» مع كونه مغفورًا له`, p: `270`,
        n: `قالوا: وقوله: وبحمدك أي وبحمدك سبّحتُك، ومعناه بتوفيقك لي وهدايتك وفضلك عليَّ سبّحتك لا بحولي وقوّتي. ففيه شكر الله تعالى على هذه النعمة والاعتراف بها والتفويض إلى الله تعالى، وأن كل الأفعال له. وفي قوله ﷺ: (أستغفرك وأتوب إليك) حُجّة أنه يجوز بل يُستحب أن يقول: أستغفرك وأتوب إليك، وحُكي عن بعض السلف كراهته لئلا يكون كاذبًا قال: بل يقول [اللهم اغفر لي وتب عليَّ]، وهذا الذي قاله من قوله [اللهم اغفر لي وتب عليَّ] حسن لا شك فيه، وأما كراهة قوله: [أستغفر الله وأتوب إليه] فلا يوافق عليها. وقد ذكرت المسألة بدلائلها في باب الاستغفار من كتاب الأذكار والله أعلم. وأما استغفاره ﷺ وقوله ﷺ: (اللهم اغفر لي ذنبي كلّه) مع أنه مغفور له فهو من باب العبودية والإذعان والافتقار إلى الله تعالى.`,
        o: `بعض السلف: يكره «أستغفر الله وأتوب إليه» لئلا يكون كاذبًا (ويقول: اللهم اغفر لي وتب عليّ).`,
        s: `(الصحيح أن يقال أن كل الأفعال هو الذي وفق لها وإلا فالعباد فاعلون حقيقة، وهذا الكلام من النووي من بقايا المتكلمين يقولون: لا فاعل إلا الله والعباد أفعالهم مجازية كلها وهذا كلام الأشاعرة، والصحيح أن الأفعال له أي بتوفيقه إذا قصد المؤلف ذلك فإن أفعال الرب غير أفعال المخلوقين فالعباد يفعلون بتوفيق الله لهم وهي أفعال حقيقية لهم، فالعباد فاعلون حقيقة لأن الله وصفهم بالأفعال.) (وذلك لأنه عازم على التوبة، وإنما ينهى ويكون كاذباً من نوى ألا يتوب.) (وأحسن من ذلك أن يقال أن الله قد غفر له بأسباب أعظمها تكميل عبوديته ومن ذلك استغفاره فقد غفر له باستغفاره ﷺ.)`,
        f: [] },
      { q: `لمس المرأة: هل ينقض الوضوء؟ (حديث عائشة «فوقعت يدي على بطن قدميه»)، والجواب عن الحديث`, p: `271`,
        n: `قولها: (فوقعت يدي على بطن قدميه وهو في المسجد وهما منصوبتان) استُدل به من يقول لمس المرأة: – لا ينقض الوضوء، وهو مذهب أبي حنيفة ﵁ وآخرين، – وقال مالك والشافعي وأحمد رحمهم الله تعالى والأكثرون: ينقض. واختلفوا في تفصيل ذلك، وأُجيب عن هذا الحديث: • بأن الملموس لا يُنتقض على قول الشافعي رحمه الله تعالى وغيره، • وعلى قول من قال يُنتقض وهو الراجح عند أصحابنا يُحمل هذا اللمس على أنه كان فوق حائل فلا يضرّ.`,
        o: `أبو حنيفة وآخرون: لا ينقض. مالك والشافعي وأحمد والأكثرون: ينقض (واختلفوا في التفصيل: بشهوة أو بغير شهوة). الشافعي: الملموس لا ينتقض.`,
        s: `(وهذا هو الصحيح سواء بشهوة أو بغير شهوة لأن النبي ﷺ قبّل بعض نسائه ثم لم يتوضأ؛ وهذا الحديث لا يصح الاحتجاج به لمن يقول لمس المرأة بشهوة ينقض الوضوء لأن هنا لمس من غير شهوة.) (مذهب مالك وأحمد أن اللمس بشهوة ينقض الوضوء ولا ينقض اللمس من غير شهوة؛ والصحيح أن القبلة صريح في المس بشهوة وآية (أو لامستم النساء) فسرها ابن عباس بالجماع.) (ففرق بين اللامس والملموس وهذا التفريق لا دليل عليه، لأن كل منها لامس للآخر ولا معنى ظاهر في تخصيص اللامس دون الملموس فلابد من وجود معنى للتفريق يدل عليه وهنا لا معنى له.) (يقول أنه لا فرق بين اللامس الملموس وهو الراجح عند الشافعية، لامسته امرأة أو لامس امرأة فكلاهما واحد في نقض الوضوء فيجيب عن هذا الحديث أنه كان فوق حائل كخف وجورب والصحيح أن هذا خلاف ظاهر الحديث لقولها: (تحسست فإذا هي وقعت على بطن قدمه) فلم تذكر خفاً.) (ويؤخذ من الحديث شرعية الاستغفار ودعاء الثناء في الركوع.)`,
        f: [] },
      { q: `نصب القدمين في السجود، ومعنى الاستعاذة بالله من الله («أعوذ برضاك من سخطك»)، وإضافة الشر إلى الله تعالى (عند أهل السنة والأشاعرة) وصفتا الرضى والسخط`, p: `272–273`,
        n: `وقولها: (وهما منصوبتان) فيه أن السنة نصبهما في السجود. وقولها: (وهو يقول: اللهم إني أعوذ برضاك من سخطك، وبمعافاتك من عقوبتك، وأعوذ بك منك لا أحصي ثناء عليك أنت كما أثنيت على نفسك) قال الإمام أبو سليمان الخطابي رحمه الله تعالى في هذا معنى لطيف؛ وذلك أنه استعاذ بالله تعالى وسأله أن يجيره برضاه من سخطه، وبمعافاته من عقوبته، والرضاء والسخط ضدان متقابلان وكذلك المعافاة والعقوبة فلما صار إلى ذكر ما لا ضد له وهو الله سبحانه وتعالى استعاذ به منه لا غير، ومعناه الاستغفار من التقصير في بلوغ الواجب من حق عبادته والثناء عليه. وقوله: (لا أحصي ثناء عليك) أي لا أطيقه ولا آتي عليه، وقيل: لا أحيط به، وقال مالك رحمه الله تعالى: معناه لا أحصي نعمتك وإحسانك والثناء بها عليك وإن اجتهدت في الثناء عليك. وقوله: (أنت كما أثنيت على نفسك) اعتراف بالعجز عن تفصيل الثناء، وأنه لا يقدر على بلوغ حقيقته، ورد للثناء إلى الجملة دون التفصيل والإحصار والتعيين، فكل ذلك إلى الله سبحانه وتعالى المحيط بكل شيء جملة وتفصيلًا، وكما أنه لا نهاية لصفاته لا نهاية للثناء عليه لأن الثناء تابع للمثنى عليه، وكل ثناء أثنى به عليه وإن كثر وطال وبولغ فيه فقدر الله أعظم، وسلطانه أعز، وصفاته أكبر وأكثر، وفضله وإحسانه أوسع وأسبغ. وفي هذا الحديث دليل لأهل السنة في جواز إضافة الشر إلى الله تعالى، كما يضاف إليه الخير لقوله: (أعوذ بك من سخطك ومن عقوبتك) والله أعلم.`,
        o: `الأشاعرة (من بقايا المتكلمين): لا يجيزون إثبات صفة السخط والغضب؛ أهل السنة: يثبتون صفتي الرضى والسخط على ما يليق بجلاله.`,
        s: `(وفيه أن السنة نصبهما في السجود.) (إضافة الشر إلى الله ﷻ عند أهل السنة إضافة الشر المخلوق الذي هو مخلوق من مخلوقات الله، وذلك أن غضب الله الذي هوسخطه وهو صفته يترتب عليه من أنواع العقوبات وأنواع السيئات والشرور المخلوقة ببعض الناس الذي نزل سخطه بهم ﷻ بحلول غضبه عليهم ﷻ؛ وأما على كلام الأشاعرة فهم لا يجيزون إثبات صفة السخط والغضب وهذا الحديث دليل على إثبات صفة الرضى وصفة السخط لله على ما يليق بجلاله ﷻ. – فلا يصح أن يقال أن السخط الذي هو فعل الله بالمعاقبة شر فإن الشر ليس من صفات الله قط وإنما هو من مخلوقاته. – فمعنى الكلام أن هذا الحديث يدل على جواز إضافة الشر المخلوق إلى الله وأن هذه الصفات يترتب عليها خلق أنواع من الشرور سواء الشر الذي استحق صاحبه العقاب أو العقاب الذي نزل به شرٌّ عليه – على ذلك المعاقب – لأنه ساءه وتألم به وعذب به.)`,
        f: [] },
      { q: `ضبط «سُبّوح قدّوس» (بالضم أو الفتح) ومعنى سُبّوح وقدّوس، ومعنى «رب الملائكة والروح» (من هو الروح؟)`, p: `273–274`,
        n: `قوله: (سُبّوح قدّوس) هما بضم السين والقاف وبفتحهما والضم أفصح وأكثر. قال الجوهري في فصل (ذرح): كان سيبويه يقولهما بالفتح، وقال الجوهري في فصل (سبح): سبّوح من صفات الله تعالى. قال ثعلب: كل اسم على فعّول فهو مفتوح الأول إلا السبّوح والقدّوس فإن الضم فيهما أكثر، وكذلك (الذُّرّوح) وهي دُوَيبّة حمراء منقّطة بسواد تطير، وهي من ذوات السموم. وقال ابن فارس والزبيدي وغيرهما: سبّوح هو الله ﷻ، فالمراد بالسبّوح القدّوس المسبَّح المقدَّس، فكأنه قال: مسبَّح مقدَّس رب الملائكة والروح. ومعنى (سبّوح) المبرّأ من النقائص والشريك وكل ما لا يليق بالإلهية، و(قدّوس) المطهّر من كل ما لا يليق بالخالق. وقال الهروي: قيل: القدّوس المبارك. قال القاضي عياض: وقيل فيه سبّوحًا قدّوسًا على تقدير أسبّح سبّوحًا أو أذكر أو أعظّم أو أعبد. وقوله (رب الملائكة والروح) قيل: الروح ملك عظيم، وقيل: يحتمل أن يكون جبريل عليه السلام، وقيل خلق لا تراهم الملائكة كما لا نرى نحن الملائكة. والله سبحانه وتعالى أعلم.`,
        o: `في «الروح»: ملك عظيم، أو جبريل عليه السلام، أو خلق لا تراهم الملائكة كما لا نرى نحن الملائكة.`,
        s: `(إما على رواية الحديث بالضم فيكون مبتدأً وخبر فيكون التقدير (هو سبوح هو قدوس)؛ ولو ثبت رواية الفتح فتقدر بـ(أذكر أو أعبد سبوحاً قدوساً).) (وهو عندي أقرب الأقوال فقد سمى الله جبريل بـ[الروح الأمين] معرف بالألف واللام في الكتاب فإذا أطلق الأظهر أنه جبريل عليه السلام.) (وهذا القول يحتاج إلى دليل فلم يثبت بذلك شيء من كتاب ولا سنة، والتفسير إنها يؤخذ من القرآن أو من السنة أو من كلام السلف الذي لا يقال من قبل الرأي ويكون صحيح الإسناد إلى الصحابة أو إلى من بعدهم ولا يحتمل أن يكون من الإسرائيليات ليكون له حكم الرفع فإذا لم يكن ذلك فلا وجه للقول به، بل هي أقوال غير ظاهرة، فالقرآن دل على أن الروح هو جبريل عليه السلام.)`,
        f: [] },
    ],
  },
  {
    title: `باب فضل السجود والحث عليه (ص274–276)`,
    items: [
      { q: `المراد بكثرة السجود: السجود في الصلاة (وحكم السجود المجرد بلا سبب للدعاء)، وأن تكثير السجود أفضل من إطالة القيام (والجمع)، وسبب الحث عليه`, p: `275–276`,
        n: `فيه الحثّ على كثرة السجود، والترغيب، والمراد به السجود في الصلاة، وفيه دليل لمن يقول تكثير السجود أفضل من إطالة القيام، وقد تقدمت المسألة والخلاف فيها في الباب الذي قبل هذا، وسبب الحث عليه ما سبق في الحديث الماضي «أقرب ما يكون العبد من ربه وهو ساجد» وهو موافق لقول الله تعالى: {واسجد واقترب}، ولأن السجود غاية التواضع والعبودية لله تعالى، وفيه تمكين أعزّ أعضاء الإنسان وأعلاها وهو وجهه من التراب الذي يُداس ويُمتهن. والله أعلم. وقوله: (أو غير ذلك؟) هو بفتح الواو.`,
        o: `الخلاف السابق: تكثير السجود أم تطويل القيام أفضل (ثلاثة مذاهب).`,
        s: `(وليس أنه يسجد هكذا كما يفعل كثير من الناس بدون سبب فتجده مثلاً يريد أن يدعوا فيسجد للدعاء فهذا غير مشروع وإنما يشرع سجود الشكر وسجود التلاوة ولم يشرع أن يسجد مجرداً بدون سبب ولهذا قال النووي: (في الصلاة).) (وقد تم ترجيح أن يكون السجود قريباً من القيام وأقل منه، والحديث ليس دليلاً صريحاً في أنه أفضل من القيام لأن ليس فيه مقارنة بينه وبين القيام ولكن فيه فضل السجود.) (فالسجود يقرب إلى الله ولما سأل الصحابي النبي ﷺ مرافقته وكونه ﷺ في أقرب المنازل من الله ناسب له السجود فأقرب ما يكون العبد من ربه وهو ساجد فيؤدي للقرب منه يوم القيامة.)`,
        f: [] },
    ],
  },
  {
    title: `باب أعضاء السجود والنهي عن كف الشعر والثوب وعقص الرأس في الصلاة (ص277–282)`,
    items: [
      { q: `أعضاء السجود السبعة: هل يجب السجود على كلها؟ وحكم السجود على الجبهة والأنف معًا (مذاهب العلماء)، ومعنى «سبعة أعظم»، وهل يُشترط أن تكون الجبهة مكشوفة؟`, p: `277, 279–280`,
        n: `هذه الأحاديث فيها فوائد: منها أن أعضاء السجود سبعة، وأنه ينبغي للساجد أن يسجد عليها كلّها، وأن يسجد على الجبهة والأنف جميعًا، فأما الجبهة فيجب وضعها مكشوفة على الأرض ويكفي بعضها، والأنف مستحب، فلو تركه جاز، ولو اقتصر عليه وترك الجبهة لم يجز، – هذا مذهب الشافعي ومالك رحمهما الله تعالى والأكثرين، – وقال أبو حنيفة ﵁ وابن القاسم من أصحاب مالك: له أن يقتصر على أيهما شاء، – وقال أحمد رحمه الله تعالى وابن حبيب من أصحاب مالك رضي الله عنهما: يجب أن يسجد على الجبهة والأنف جميعًا لظاهر الحديث. – قال الأكثرون: بل ظاهر الحديث أنهما في حكم عضو واحد لأنه قال في الحديث: سبعة فإن جعلا عضوين صارت ثمانية، وذكر الأنف استحبابًا.`,
        o: `الشافعي ومالك والأكثرون: الجبهة واجبة والأنف مستحب. أبو حنيفة وابن القاسم: يقتصر على أيهما شاء. أحمد وابن حبيب: يجب على الجبهة والأنف جميعًا.`,
        s: `(ليدل على أن الأنف جزء منها أو على لزوم أن يضع أنفه على الأرض لأن سجود الجبهة لا يحصل إلا إذا سجد على الأنف.) (هنا ذكر الأثنين وهو صريح في الوجوب.) (بمعنى أنه لو جزء من الجبهة مغطى صح السجود، والأظهر أنه حتى لو غطيت بملبوس مثل جزء من العمامة وتكون فيه الجبهة معه ممكنة وليس بالكور الكبيرة التي تمنع من وضع الجبهة على الأرض فالظاهر صحة السجود أما الشيء اليسير مثل ما يحصل من غطاء الرأس الذي قد يغطي جانباً من الجبهة فذلك لا يضر إن شاء الله. – بعض علماء الشافعية يفرقون بين الملبوس والمفروش فيجعلون الملبوس هو الذي لا يجوز والمفروش يجوز ولا دليل على ذلك والعبرة أنه هل يسمى أنه وضع جبهته على الأرض أم لا فيطلق عليه ذلك أم لا.) (هذا ليس بظاهر، وظاهر الأمر الوجوب، ولا يكون قد سجد على الجبهة إلا إذا مكن الأنف من الأرض فتمكين الجبهة لا يحصل إلا بتمكين الأنف، فلو سجد بطرف الجبهة فإنه لم يمكن الجبهة من الأرض وذلك لأنه لم يمكن الأنف من الأرض.) (وهذا هو الصحيح لقوله ﷺ: (أمرت) وأشار إلى أنفه وجبهته وقد أمر به وهو كالعضو الواحد لكن كون النبي ﷺ أشار إلى الأنف فدل على الوجوب مع قوله (أمرت).)`,
        f: [] },
      { q: `السجود على اليدين والركبتين والقدمين: هل يجب؟ ومذاهب الشافعي (قولان)، وكشف الركبتين والقدمين والكفين`, p: `280–281`,
        n: `وأما اليدان والركبتان والقدمان فهل يجب السجود عليها فيه قولان للشافعي رحمه الله تعالى: – أحدهما لا يجب لكن يُستحب استحبابًا متأكدًا، – والثاني يجب وهو الأصح الذي رجحه الشافعي رحمه الله تعالى، فلو أخل بعضو منها لم تصح صلاته. وإذا أوجبناه لم يجب كشف القدمين والركبتين، وفي الكفين قولان للشافعي رحمه الله تعالى: أحدهما يجب كشفها كالجبهة وأصحها لا يجب.`,
        o: `الشافعي (قولان): لا يجب السجود على اليدين والركبتين والقدمين بل يستحب، أو يجب (الأصح). وفي كشف الكفين قولان: يجب كالجبهة، أو لا يجب (الأصح).`,
        s: `(وهذا الكلام قد نظر إلى معنى السجود في اللغة دون الالتفات إلى المعنى الشرعي، فحتى لو سلمنا أن السجود هو وضع الجبهة على الأرض لكن قد أتى الشرع بزيادة على هذا المعنى اللغوي والحقيقة الشريعة مقدمة على الحقيقة اللغوية إذا ثبتت، والحقيقة الشرعية في السجود سبعة أعظم.) (لأن السجود لم يصح والسجود ركن من الأركان والسجدة هذه قد بطلت، وقد تجد أُناس رافعة لقدميها في السجود في الهواء وهذا يقع فيه كثير من الناس ويرفع رأسه قبل أن تنزل قدمه على الأرض وبهذا لا تتم السجدة والصلاة باطلة، فالمهم أن تكون السبعة أعظم موجودون مع بعضهم على الأرض قدر الطمأنينة في السجود، فلو رفعها قليلاً لأي علة من العلل ثم وضعها بقدر الطمأنينة أجزئ ذلك.) (وهذا هو الصحيح كأن يصلي رجل أو المرأة بجوانتي أو أدخل يده في كم القميص صح ذلك ولا يلزمه نزع اليدين ولا دليل على الكراهة ولكن الاحتياط أن يكشفها خروجاً من الخلاف ولأن الأعم الأغلب أن النبي ﷺ لم يرد عنه أنه كان يصلي في قفازين.)`,
        f: [] },
      { q: `معنى «ولا نكفت الثياب ولا الشعر»، وحكم الصلاة بثوب مشمّر أو كمّ مشمّر أو رأس معقوص (كراهة تنزيه)، والتشمير خارج الصلاة، والإسبال`, p: `281`,
        n: `قوله ﷺ: (لا نكفت الثياب ولا الشعر) هو بفتح النون وكسر الفاء أي لا نضمها ولا نجمعها، والكفت الجمع والضم، ومنه قوله تعالى: {ألم نجعل الأرض كفاتًا} أي تجمع الناس في حياتهم وموتهم، وهو بمعنى الكف في الرواية الأخرى، وكلاهما بمعنى. وقوله في الرواية الأخرى: (ورأسه معقوص) اتفق العلماء على النهي عن الصلاة وثوبه مشمّر أو كمّه أو نحوه، أو رأسه معقوص أو مردود شعره تحت عمامته أو نحو ذلك فكل هذا منهي عنه باتفاق العلماء، وهو كراهة تنزيه فلو صلّى كذلك فقد أساء وصحت صلاته، – واحتج في ذلك أبو جعفر محمد بن جرير الطبري بإجماع العلماء.`,
        o: `الحسن البصري (حكاه ابن المنذر): إعادة الصلاة. الجمهور: النهي مطلق لمن صلى كذلك سواء تعمده للصلاة أم قبلها. الداودي: يختص النهي بمن فعل ذلك للصلاة. الإمام أحمد: التحريم.`,
        s: `(كالسروال، وأي شيء آخر لأن عموم قوله [ألا نكفت ثوباً] يشمل السروال، أو أي شيءيمكن كفته وهو يضم بعضه إلى بعض وأما السروال إذا كان قدمه متخيط فهذه تفصيلته فلا يدخل في الكفت، فالكلام على أنه هو يشمرها حال الصلاة سواء كان قبل ذلك مشمراً أو غير مشمر فساعة ما يأتي للصلاة عليه أن يفك كمه ولا يضم شيء، وبذلك هو لم يتخلص من الإسبال، بل عليه أن يخيطه أو يشبكه بإبرة أو ما شابه حتى يخيطه على وضع يستقر عليه ليس فيه إسبال. – في الصلاة: دليل أنه لا ينهى عنه في خارج الصلاة فيمكنه أن يربط شعره خارج الصلاة، يمكن أن يشمر كمه خارج الصلاة، فيجوز ذلك فهذا ليس بممتنع.) (على عدم التحريم.) (وهذا مذهب الإمام أحمد وهو التحريم لأنه ظاهر النهي.) (وهذا بناء على القول بالكراهة وصحة الصلاة لأنه لو كانت الصلاة باطلة لأمره أن يخرج منها، ولكن يمكن أن يقال يحرم مع صحة الصلاة فلا يلزم الإعادة.) (ثم مذهب الجمهور أن النهي مطلقاً لمن صلى كذلك سواء تعمده للصلاة أم كان قبلها كذلك لا لها بل لمعنى آخر، – وقال الداودي يختص النهي بمن فعل ذلك للصلاة، – والمختار الصحيح هو الأول، وهو ظاهر المنقول عن الصحابة وغيرهم، ويدل عليه فعل ابن عباس المذكور هنا.)`,
        f: [] },
      { q: `حكم الإعادة لمن صلى مكفوف الشعر أو الثوب (التحريم والكراهة)، والحكمة في النهي، وإنكار المنكر في الصلاة ولو كان مكروهًا، وخبر الواحد`, p: `282`,
        n: `وحكى ابن المنذر الإعادة فيه عن الحسن البصري، ثم مذهب الجمهور أن النهي مطلقًا لمن صلى كذلك سواء تعمده للصلاة أم كان قبلها كذلك لا لها بل لمعنى آخر، وقال الداودي يختص النهي بمن فعل ذلك للصلاة، والمختار الصحيح هو الأول، وهو ظاهر المنقول عن الصحابة وغيرهم، ويدل عليه فعل ابن عباس المذكور هنا. قال العلماء: والحكمة في النهي عنه أن الشعر يسجد معه، ولهذا مثّله بالذي يُصلي وهو مكتوف. قوله: (عن ابن عباس أنه رأى ابن الحارث يصلي ورأسه معقوص فقام فجعل يحلّه) فيه الأمر بالمعروف والنهي عن المنكر، وأن ذلك لا يؤخر، إذ لم يؤخره ابن عباس رضي الله عنهما حتى يفرغ من الصلاة، وأن المكروه يُنكر كما يُنكر المحرَّم، وأن من رأى منكرًا وأمكنه تغييره بيده غيّره بها لحديث أبي سعيد الخدري، وأن خبر الواحد مقبول. والله أعلم.`,
        o: `الحسن البصري: تجب الإعادة. الجمهور: النهي مطلق ولا إعادة، وهو كراهة تنزيه. الداودي: يختص النهي بمن فعل ذلك للصلاة. الإمام أحمد: التحريم.`,
        s: `(وهذا مذهب الإمام أحمد وهو التحريم لأنه ظاهر النهي.) (وهذا بناء على القول بالكراهة وصحة الصلاة لأنه لو كانت الصلاة باطلة لأمره أن يخرج منها، ولكن يمكن أن يقال يحرم مع صحة الصلاة فلا يلزم الإعادة.)`,
        f: [] },
    ],
  },
  {
    title: `باب الاعتدال في السجود ووضع الكفين على الأرض ورفع المرفقين عن الجنبين ورفع البطن عن الفخذين في السجود (ص283–287)`,
    items: [
      { q: `مقصود أحاديث الباب: وضع الكفين على الأرض ورفع المرفقين (انبساط الكلب)، وحكم من ترك ذلك (كراهة أم وجوب؟)، وكيفية وضع الكفين والأصابع والمرفق`, p: `284`,
        n: `مقصود أحاديث الباب: أنه ينبغي للساجد أن يضع كفّيه على الأرض، ويرفع مرفقيه عن الأرض، وعن جنبيه رفعًا بليغًا بحيث يظهر باطن إبطيه إذا لم يكن مستورًا، وهذا أدب متفق على استحبابه فلو تركه كان مسيئًا مرتكبًا للنهي، والنهي للتنزيه. وصلاته صحيحة. والله أعلم.`,
        o: NO_O,
        s: `(الكف كاملاً وليس كما يفعل بعض الناس بوضع أصابعه فقط.) (المرفق هو ما يسميه الناس خطأً الكوع والكوع في اللغة الرسغ، والمرفق هو الذي يجب غسله في الوضوء وهو آخر حد الوضوء.) (فإذا عجز عن ذلك للزحام فلا يُكلَّف (لا يكلف الله نفساً إلا وسعها)، (واتقوا الله ما استطعتم). – وتكون أصابعه مضمومة في اتجاه القبلة. – فلو وضع أصابعه فقط على الأرض فقد وجد جزء من العظم الذي وجب أن يسجد عليه وصلاته صحيحة إلا أنه قد خالف السنة وربها نقول قد خالف الواجب إن صح هذا الإجماع الذي ذكره النووي: [وهذا أدب متفق على استحباب].)`,
        f: [] },
      { q: `الحكمة في الاعتدال في السجود ووضع الكفين (التواضع وترك التشبه بالكلب)، وضبط «ولا يتبسط» (انبساط الكلب)، وضبط «ابن بحينة»`, p: `285`,
        n: `قال العلماء: والحكمة في هذا أنه أشبه بالتواضع وأبلغ في تمكين الجبهة والأنف من الأرض، وأبعد من هيئات الكسالى فإن المتبسط [المنبسط] كشبه الكلب، ويشعر حاله بالتهاون بالصلاة، وقلة الاعتناء بها والإقبال عليها. والله أعلم. وأما ألفاظ الباب: ففيه قوله ﷺ: (ولا يبسط أحدكم ذراعيه انبساط الكلب) وفي الرواية الأخرى (ولا يتبسّط) بزيادة التاء المثناة من فوق انبساط الكلب. هذان اللفظان صحيحان وتقديره ولا يبسط ذراعيه فينبسط انبساط الكلب، وكذا اللفظ الآخر (ولا يتبسّط ذراعيه) فينبسط انبساط الكلب، ومثله قول الله تعالى: {والله أنبتكم من الأرض نباتًا} وقوله: {فتقبلها ربها بقبول حسن وأنبتها نباتًا حسنًا} وفي هذه الآية الثانية شاهدان، ومعنى (يتبسط) بالتاء المثناة فوق أي يتخذهما بساطًا. والله أعلم. قوله: (عن عبد الله بن مالك ابن بحينة) الصواب فيه أن يُنوّن مالك ويكتب (ابن) بالألف؛ لأن ابن بحينة ليس صفة لمالك بل صفة لعبد الله لأن عبد الله اسم أبيه مالك واسم أمّ عبد الله (بحينة) فبحينة امرأة مالك وأمّ عبد الله بن مالك.`,
        o: NO_O,
        s: `(أي يضع مرفقه على الأرض.)`,
        f: [] },
      { q: `معنى «فرّج بين يديه» و«يُجنّح في سجوده» و«خوّى بيديه»، ومعنى «حتى نرى بياض إبطيه»: هل رؤية بياض الإبطين تكون في النافلة أم في الفريضة؟ ومتى يرى المأموم بياض إبطي الإمام؟`, p: `285–286`,
        n: `قوله: (فرّج بين يديه) يعني بين يديه وجنبيه. قوله: (يُجنّح في سجوده) هو بضمّ الياء وفتح الجيم وكسر النون المشدّدة، وهو معنى فرّج بين يديه، وهو معنى قوله في الرواية الأخرى (خوّى بيديه) بالخاء المعجمة وتشديد الواو وفرّج وجنّح وخوّى بمعنى واحد ومعناه كلّه باعد مرفقيه وعضديه عن جنبيه. قوله: (يُجنّح في سجوده حتى نرى بياض إبطيه) هو بالنون في (نرى)، ورُوي (بالياء) المثناة من تحت المضمومة، وكلاهما صحيح، ويؤيد الياء الرواية الأخرى عن ميمونة (إذا سجد خوّى بيديه حتى يُرى وضح إبطيه) ضبطناه وضبطوه هنا بضم الياء، ويؤيد النون رواية الليث في هذا الطريق (حتى إني لأرى بياض إبطيه).`,
        o: NO_O,
        s: `(فلا يرى بياض الإبط إلا إذا باعد بين مرفقيه عن جنبيه.) (هذه الرؤية ربما تكون في النافلة، أو في الفريضة في الصف المقدم فإنهم كانوا لا يحنى أحدهم ظهره حتى يضع النبي ﷺ جبهته على الأرض فقد وضعت قبل ذلك اليدان قبل أن توضع الجبهة وقد فرق بينها وأثناء ذلك نظر إليه، والنظر إلى الإمام أثناء الصلاة لحسن المتابعة مشروع.)`,
        f: [] },
      { q: `الجلوس بين السجدتين والتشهد الأول (الافتراش) والتشهد الأخير (التورك)`, p: `287`,
        n: `قوله: (وإذا قعد اطمأنّ على فخذه اليسرى) يعني إذا قعد بين السجدتين أو في التشهد الأول. وأما القعود في التشهد الأخير فالسنة فيه التورّك كما رواه البخاري في صحيحه من رواية أبي حُميد الساعدي وكذلك رواه أبو داود والترمذي وغيرهما.`,
        o: NO_O,
        s: `(لأنه في التشهد الأخير يجلس على وركه على الأرض، أما في الافتراش فإنه يضع فخذه على رجله اليسرى كما سيأتي.)`,
        f: [] },
    ],
  },
  {
    title: `باب ما يجمع صفة الصلاة وما يُفتتح به ويُختم به وصفة الركوع والاعتدال منه والسجود والاعتدال منه والتشهد بعد كل ركعتين من الرباعية وصفة الجلوس بين السجدتين وفي التشهد الأول (ص288–297)`,
    items: [
      { q: `ألفاظ حديث عائشة في صفة الصلاة: «والقراءة بالحمد لله» (حكاية)، و«لم يصوّبه» (الإشخاص والتصويب)، و«كان يفرش» (الافتراش)، و«عقبة الشيطان» وافتراش السبع وصحة جواز كلمة «عقب»`, p: `289`,
        n: `قولها: (والقراءة بالحمد لله) هو برفع الدال على الحكاية. قولها: (ولم يصوّبه) هو بضمّ الياء وفتح الصاد المهملة وكسر الواو المشدّدة. أي لم يخفضه خفضًا بليغًا بل يعدل فيه بين الإشخاص والتصويب. قولها: (وكان يفرش) هو بضمّ الراء وكسرها والضمّ أشهر. قولها: (عُقبة الشيطان) بضمّ العين، وفي الرواية الأخرى (عقِب الشيطان) بفتح العين وكسر القاف هذا هو الصحيح المشهور فيه، وحكى القاضي عياض عن بعضهم بضمّ العين، وضعّفه. وفسّره أبو عبيدة وغيره بالإقعاء المنهيّ عنه وهو أن يُلصق أليتيه بالأرض وينصب ساقيه ويضع يديه على الأرض كما يفرش الكلب وغيره من السباع.`,
        o: NO_O,
        s: `(فتكون الجملة (الحمد لله) في موضع جر (بالباء)، ولا نقول بالحمد لله لأن (الحمد لله) هي حكاية القول فيمكن أن تكون الجملة مجرور بحرف جر أو مفعول به.) (فالإشخاص أن يرفعه رفعاً مبالغ فيه والتصويب أن يخفضه خفضاً مبالغ فيه وكلاهما غير مشروع والمشروع في الركوع أن يكون الرأس في مستوى الظهر وهو السنة.) (أي أنه يجلس على رجله اليسرى.) (أي صحة جواز كلمة (عقب).) (السنة أن ينصب اليمنى كما سيأتي بيانه؛ وليس من السنة أن يفترش الاثنين ومن فعل ذلك فقد خالف السنة. – الإرفاق المنهي عنه أن يضع مرفقه على الأرض كالكلب.)`,
        f: [] },
      { q: `تعيين لفظ التكبير في افتتاح الصلاة («الله أكبر»)، ومذهب الحنفية («يقوم غيره من ألفاظ التعظيم مقامه») وخلاف الشافعية في «الله الأكبر»، وأقوى دليل في ذلك`, p: `290`,
        n: `أما أحكام الحديث: فقولها: (كان يفتتح الصلاة بالتكبير) – فيه إثبات التكبير في أول الصلاة، – وأنه يتعيّن لفظ التكبير، لأنه ثبت أن النبي ﷺ كان يفعله وأنه ﷺ قال: «صلّوا كما رأيتموني أصلّي»، • وهذا الذي ذكرناه من تعيين التكبير هو قول مالك والشافعي وأحمد رحمهم الله تعالى، وجمهور العلماء من السلف والخلف، • وقال أبو حنيفة ﵁: يقوم غيره من ألفاظ التعظيم مقامه.`,
        o: `مالك والشافعي وأحمد والجمهور: يتعين لفظ التكبير. أبو حنيفة: يقوم غيره من ألفاظ التعظيم مقامه. (الشافعية: خلاف في «الله الأكبر».)`,
        s: `(خلافاً للحنفية الذين قالوا بجواز لفظ (الله أعظم، الله أحلم)؛ والجمهور على تعيين التكبير (الله أكبر) والشافعية عندهم خلاف في لفظ (الله الأكبر) هل تجزئ أم لا؟ والصحيح وجوب قول (الله أكبر).) (وأقوى منه حديث المسيء صلاته حين قال له: (إذا قمت إلى الصلاة فكبر).)`,
        f: [] },
      { q: `قولها «والقراءة بالحمد لله رب العالمين»: هل يدل على أن البسملة ليست من الفاتحة؟ (جواب الشافعي والأكثرين) وأدلة أن البسملة من الفاتحة`, p: `290–291`,
        n: `وقولها: (والقراءة بالحمد لله رب العالمين) – استدلّ به مالك وغيره ممن يقول إن البسملة ليست من الفاتحة، • وجواب الشافعي رحمه الله تعالى والأكثرين القائلين بأنها من الفاتحة أن معنى الحديث أنه يبتدئ القرآن بسورة (الحمد لله رب العالمين) لا بسورة أخرى، فالمراد بيان السورة التي يُبتدأ بها، وقد قامت الأدلة على أن البسملة منها.`,
        o: `مالك وغيره: البسملة ليست من الفاتحة. الشافعي والأكثرون: البسملة منها، ومعنى الحديث أنه يبتدئ بسورة (الحمد لله رب العالمين).`,
        s: `(فالحمد لله رب العالمين) عنوان على السورة، كأن يقول أفتتح بسورة البقرة، فإنه لا يبدأ بـ[بقرةً صفراء] بل سيقرأ: (ألم. . . . )، إذاً فلا يقتضي هذا البدء بـ[الحمد لله]. – فأدلة أن البسملة من الفاتحة: ١– أنها مثبتة في المصحف. ٢– حديث أم سلمة: [حَدَّثَنَا عُمَرُ بْنُ هَارُونَ، عَنِ ابْنِ جُرَيْجٍ، عَنِ ابْنِ أَبِي مُلَيْكَةَ، عَنْ أُمِّ سَلَمَةَ، أَنَّ النَّبِيَّ ﷺ قَرَأَ فِي الصَّلاَةِ {بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ} فَعَدَّهَا آيَةً، وَ{الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ} آيَتَيْنِ، {وَإِيَّاكَ نَسْتَعِينُ} وَجَمَعَ خَمْسَ أَصَابِعِهِ.] صحيح ابن خزيمة. تعليق الذهبي في التلخيص: أجمعوا على ضعفه يعني عمر بن هارون وقال النسائي متروك، فهذا أصرح نص لكن الحديث فيه اختلاف. قال الألباني: صحيح بطرقه؛ وحديث أبي هريرة ﷺ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: " إِذَا قَرَأْتُمْ: {الْحَمْدُ لِلَّهِ}، فَاقْرَءُوا: {بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ} إِنَّهَا أُمُّ الْقُرْآنِ ، وَأُمُّ الْكِتَابِ ، وَالسَّبْعُ الْمَثَانِي وَ {بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ} إِحْدَى آيَاتِهَا ((قط) ج١ص٣١٢ح٣٦، انظر صحيح الجامع: ٧٢٩). – وهذا هو الصحيح فلو نسي البسملة في الفاتحة فعليه أن يبدأها من جديد، ولو ركعة كاملة صلاها بدون البسملة في الفاتحة يعيدها مرة أخرى إلا أن يكون مجتهداً متبعاً المذاهب الآخر فنأمره في المستقبل بأن يفعل ذلك ولا يعيد ولو ضعّف الحديث وضعّف الاستدلال وظل على تأويله فهذا متأولاً لا تبطل صلاته. – فالبسملة واجبة في الفاتحة سواء للإمام أو المأموم.)`,
        f: [] },
      { q: `الاعتدال بعد الركوع والجلوس بين السجدتين: وجوبه وركنيته (تسوية الظهر في الركوع)، ووجوب الطمأنينة في الاعتدال`, p: `291`,
        n: `– وفيه أن السنة للراكع أن يسوّي ظهره بحيث يستوي رأسه ومؤخّره، – وفيه وجوب الاعتدال إذا رفع من الركوع، أنه يجب أن يستوي قائمًا لقوله ﷺ: «صلّوا كما رأيتموني أصلّي»، – وفيه وجوب الجلوس بين السجدتين.`,
        o: NO_O,
        s: `(ووجوب الطمأنينة كذلك (حتى يستوي قائماً) فلابد أن يتم اعتداله ويطمئن فيه.) (ونحن نقول هذه من الأركان.)`,
        f: [] },
      { q: `قولها «وكان يقول في كل ركعتين التحية»: التشهد الأول والأخير واجبان أم سنتان؟ (مذهب أحمد ومالك والشافعي)، وهل يجب «رب اغفر لي»`, p: `291–292`,
        n: `قولها: (وكان يقول في كل ركعتين التحية) – فيه حجة لأحمد بن حنبل ومن وافقه من فقهاء أصحاب الحديث أن التشهد الأول والأخير واجبان، وقال مالك وأبو حنيفة رضي الله عنهما والأكثرون: هما سنتان ليسا واجبين، وقال الشافعي ﵁: الأول سنة والثاني واجب. واحتجّ أحمد رحمه الله تعالى بهذا الحديث مع قوله ﷺ: «صلّوا كما رأيتموني أصلّي» وبقوله: كان النبي ﷺ يعلّمنا التشهد كما يعلّمنا السورة من القرآن، وبقوله ﷺ: «إذا صلّى أحدكم فليقل التحيات» والأمر للوجوب، واحتجّ الأكثرون بأن النبي ﷺ ترك التشهد الأول وجبره بسجود السهو، ولو وجب لم يصحّ جبره كالركوع وغيره من الأركان. قالوا: وإذا ثبت هذا في الأول فالأخير بمعناه، ولأن النبي ﷺ لم يعلّمه الأعرابيّ حين علّمه فروض الصلاة. والله أعلم.`,
        o: `أحمد وفقهاء أهل الحديث: التشهدان واجبان. مالك وأبو حنيفة والأكثرون: سنتان. الشافعي: الأول سنة والثاني واجب (ركن).`,
        s: `(والشافعي لا يفرق بين الواجب والركن، فيكون عنده الثاني ركن، والإمام أحمد يقول واجبان على التقسيم وهذا القول هو الصحيح.) (لماذا نقول هو واجب وليس بركن؟ فالواجبات يمكن جبرها بسجود السهو؛ وقوله: (كالركوع) فنقول هناك فرق بين الواجبات والأركان فالأركان لا تجبر فمن ترك ركناً نقول له: (أذهب فصلي فإنك لم تصلي) وعليه إعادة الركعة وأما الواجب فيجبره بسجود السهو.) (والصحيح كما ذكرنا أن كلا التشهدين واجب ويجبر سجود السهو تركها. – والصحيح أن قول (رب اغفر لي) واجب. – وهذا دليل على أنه لو صلى أربع ركعات في النافلة قرأ التحية في كل ركعتين لعموم قولها: (وَكَانَ يَقُولُ فِي كُلِّ رَكْعَتَيْنِ التَّحِيَّةَ). – فإذا صلى أربعاً متصلة كالتي قبل الظهر لم يسلم فيها فذلك جائز، ولو صلى في قيام الليل أربعة متصلة يجلس في كل ركعتين.)`,
        f: [`(ص292–293) [الوتر] • أما إذا كان يوتر بخمس أو سبع أو تسع أو بثلاث: – فقد ورد أن الذي يوتر بخمس لا يجلس إلا في آخرهن، ففي صحيح مسلم عَنْ عَائِشَةَ قَالَتْ: [كَانَ رَسُولُ اللَّهِ ﷺ يُصَلِّي مِنَ اللَّيْلِ ثَلاَثَ عَشْرَةَ رَكْعَةً يُوتِرُ مِنْ ذَلِكَ بِخَمْسٍ لاَ يَجْلِسُ فِي شَيْءٍ إِلاَّ فِي آخِرِهَا]، – فإذا صلى بسبع جلس في السادسة والسابعة، وإذا أوتر بتسع فقد ثبت أنه ﷺ جلس في الثامنة والتاسعة فقد ثبت ذلك في سنن أبي داود: [قَالَ: قُلْتُ: حَدِّثِينِي عَنْ وِتْرِ النَّبِيِّ صلى الله عليه وسلم، قَالَتْ: كَانَ يُوتِرُ بِثَمَانِ رَكَعَاتٍ لاَ يَجْلِسُ إِلاَّ فِي الثَّامِنَةِ، ثُمَّ يَقُومُ، فَيُصَلِّي رَكْعَةً أُخْرَى، لاَ يَجْلِسُ إِلاَّ فِي الثَّامِنَةِ وَالتَّاسِعَةِ، وَلاَ يُسَلِّمُ إِلاَّ فِي التَّاسِعَةِ، ثُمَّ يُصَلِّي رَكْعَتَيْنِ، وَهُوَ جَالِسٌ، فَتِلْكَ إِحْدَى عَشْرَةَ رَكْعَةً يَا بُنَيَّ، فَلَمَّا أَسَنَّ، وَأَخَذَ اللَّحْمَ، أَوْتَرَ بِسَبْعِ رَكَعَاتٍ، لَمْ يَجْلِسْ إِلاَّ فِي السَّادِسَةِ وَالسَّابِعَةِ، وَلَمْ يُسَلِّمْ إِلاَّ فِي السَّابِعَةِ، ثُمَّ يُصَلِّي رَكْعَتَيْنِ، وَهُوَ جَالِسٌ، فَتِلْكَ هِيَ تِسْعُ رَكَعَاتٍ يَا بُنَيَّ] تحقيق الألباني: صحيح. • وإذا أوتر بثلاث فإنها مثل الخمس يجلس في الأخيرة ولا يشبهها بالمغرب لورود النهي عن تشبيه الوتر بالمغرب: فعَنْ عَبْدِ اللهِ بْنِ الْفَضْلِ، عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ، وَعَبْدِ الرَّحْمَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ قَالَ: "لاَ تُوتِرُوا بِثَلاَثٍ، أَوْتِرُوا بِخَمْسٍ، أَوْ بِسَبْعٍ، وَلاَ تَشَبَّهُوا بِصَلاَةِ الْمَغْرِبِ". (حب) ٢٤٢٩ [قال الألباني]: صحيح – "صلاة التراويح" (١٠٠)؛ أي لا توتر بثلاث بتشهد أوسط كالمغرب؛ فإذا صلى شفعاً فليجلس في كل ركعتين؛ وبهذا فلا تعارض بين النهي عن الوتر بثلاث وبين الأمر به؛ فعن أَيُّوبَ الأَنْصَارِيِّ أَنَّهُ قَالَ: "الْوِتْرُ حَقٌّ، فَمَنْ أَحَبَّ أَنْ يُوتِرَ بِخَمْسِ رَكَعَاتٍ فَلْيَفْعَلْ، وَمَنْ أَحَبَّ أَنْ يُوتِرَ بِثَلاَثٍ فَلْيَفْعَلْ، وَمَنْ أَحَبَّ أَنْ يُوتِرَ بِوَاحِدَةٍ فَلْيَفْعَلْ" (س) ١٧١٢ [قال الألباني]: صحيح.`] },
      { q: `الجلوس في الصلاة: الافتراش في كل الجلسات (أبو حنيفة) أم التورك (مالك) أم التفصيل (الشافعي والجلسات الأربع)، والجلوس في الوتر`, p: `293–294`,
        n: `وقولها: (وكان يفرش رجله اليسرى وينصب رجله اليمنى) معناه يجلس مفترشًا. – فيه حجة لأبي حنيفة ﵁ ومن وافقه أن الجلوس في الصلاة يكون مفترشًا سواء فيه جميع الجلسات، وعند مالك رحمه الله تعالى يُسنّ متورِّكًا بأن يُخرج رجله اليسرى من تحته ويُفضي بوركه إلى الأرض، وقال الشافعي رحمه الله تعالى: السنة أن يجلس كل الجلسات مفترشًا إلا التي يعقبها السلام، والجلسات عند الشافعي رحمه الله أربع: [الجلوس بين السجدتين، وجلسة الاستراحة عقب كل ركعة يعقبها قيام، والجلسة للتشهد الأول، والجلسة للتشهد الأخير]، فالجميع يُسنّ مفترشًا إلا الأخيرة، فلو كان مسبوقًا وجلس إمامه في آخر صلاته متورِّكًا جلس المسبوق مفترشًا لأن جلوسه لا يعقبه سلام، ولو كان على المصلّي سجود سهو فالأصح أنه يجلس مفترشًا في التشهد، فإذا سجد سجدتي السهو تورّك ثم سلّم. هذا تفصيل مذهب الشافعي رحمه الله تعالى.`,
        o: `أبو حنيفة: الافتراش في كل الجلسات. مالك: التورك. الشافعي: الافتراش في كل الجلسات إلا الأخيرة التي يعقبها السلام (والمسبوق يفترش)، وإذا كان عليه سجود سهو فالأصح أن يفترش في التشهد ثم يتورك بعد سجدتي السهو. (وبعض أهل الحديث: يخير بين التورك والافتراش في الركعتين؛ وطائفة تقول: يفترش في الركعتين.)`,
        s: `(حتى التشهد الأخير فيرى بجواز أو مشروعية الافتراش.) (الصحيح أن يقال: (عقب كل ركعة وتر) لأنه في صحيح البخاري: حَدَّثَنَا مُحَمَّدُ بْنُ الصَّبَّاحِ قَالَ: أَخْبَرَنَا هُشَيْمٌ قَالَ: أَخْبَرَنَا خَالِدٌ الْحَذَّاءُ، عَنْ أَبِي قِلاَبَةَ قَالَ: أَخْبَرَنَا مَالِكُ بْنُ الْحُوَيْرِثِ اللَّيْثِيُّ أَنَّهُ [رَأَى النَّبِيَّ ﷺ يُصَلِّي فَإِذَا كَانَ فِي وِتْرٍ مِنْ صَلاَتِهِ لَمْ يَنْهَضْ حَتَّى يَسْتَوِيَ قَاعِدًا]، فالسنة أن يجلس جلسة الاستراحة في الوتر من صلاته، فإذا سجد سجدة التلاوة وهو صاعد فلا يجلس جلسة الاستراحة لأن هذا ليس وتر من صلاته. – وإذا صلى خمسة ركعات فإذا كان في الركوع الثانية والرابعة لا يجلس؛ لأن الحديث جاء في جلسة الاستراحة إن كان من وتر من صلاته، ولها وجه الذي ذكره البخاري في حديث للمسيء صلاته أنه ﷺ أمره بالجلسة بعد السجدة الثانية وبهذا يجلس عقب كل ركعة يعقبها قيام.) (والقول الثاني: أنه يجلس متوركاً لأن هذه الجلسة هي التي فيها التسليم، ولو سجد بعدها وهذا هو الأقرب أنه يجلس متوركاً من عليه سجود السهو. – ويمكن أن يقال: من عليه ركعة ثانية يجلس متوركاً لأنه مأمور بأن يتابع إمامه بأن يجلس إلى أن ينصرف. – يلحظ من ذلك أن الجلوس للتشهد الأخير للتشهد في الركعتين عند الشافعي يتورك لأن العبرة عند الشافعي في الجلسة التي فيها التسليم (التشهد الأخير). – وطائفة من أهل الحديث يرون أنه يفترش إذا كان في الركعتين، وهذه محتملة لأن الحديث فيه: (يفترش في الركعتين) محتملة في الركعتين التي معها ثالثة أو رابعة ويحتمل أن يكون في الركعتين فقط والصحيح أنه إذا تعارض ا لعمومين: عموم (فإذا كان في الجلسة التي فيها التسليم) وعموم (يفترش في الركعتين) فيكون الصحيح العمل بالعمومين طالما أمكن العمل بها فلذلك قلنا بالتخيير في صلاة الركعتين. – فلو صلى ركعتين فقط (الفجر مثلاً) وكذلك لو صلى النافلة ركعتين أو الوتر فهو بالخيار يتورك أو يفترش.)`,
        f: [`(ص293) [الجلوس في الوتر عمومًا] الجلوس في الوتر عمومًا (واحدة أو ثلاث أو خمسة) في الركعة الأخيرة بالتورك لأن الذي ورد أنه يفترش في الركعتين وهذه ليست ركعتين فلم يبقى إلا عموم (ثُمَّ صَنَعَ مِثْلَ ذَلِكَ فِي بَقِيَّةِ صَلاَتِهِ حَتَّى إِذَا كَانَتْ قَعْدَةُ السَّجْدَةِ الَّتِي فِيهَا التَّسْلِيمُ أَخَّرَ رِجْلَهُ الْيُسْرَى وَقَعَدَ مُتَوَرِّكًا عَلَى شِقِّهِ الأَيْسَرِ) قَالُوا جَمِيعًا: هَكَذَا كَانَ رَسُولُ اللَّهِ ﷺ يصلي) التعليقات الحسان على صحيح ابن حبان. [تعليق الشيخ الألباني: صحيح. انظر (١٨٦٢)]؛ حتى لو ركعة واحدة؛ أما ركعتي الشفع فإنه يخير بين التورك والافتراش.`] },
      { q: `الجلوس بين السجدتين والتشهد الأول: الافتراش (حديث أبي حميد)، جلسة المرأة، التربع في النافلة، والإقعاء المنهي عنه والإقعاء السنة (الجلوس على العقبين)`, p: `295`,
        n: `واحتج أبو حنيفة ﵁ بإطلاق حديث عائشة رضي الله عنها هذا، واحتج الشافعي رحمه الله تعالى بحديث أبي حُميد الساعدي في صحيح البخاري وفيه تصريح بالافتراش في الجلوس الأول، والتورّك في آخر الصلاة، وحُمل حديث عائشة هذا على الجلوس في غير التشهد الأخير للجمع بين الأحاديث. • وجلوس المرأة كجلوس الرجل، وصلاة النفل كصلاة الفرض في الجلوس. – هذا مذهب الشافعي ومالك رحمهما الله تعالى والجمهور، – وحكى القاضي عياض عن بعض السلف أن سنة المرأة التربّع، – وعن بعضهم التربّع في النافلة، والصواب الأول. ثم هذه الهيئة مستوية فلو جلس في الجميع مفترشًا أو متورِّكًا أو متربِّعًا أو مقعيًا أو مادًّا رجليه صحّت صلاته وإن كان مخالفًا. قولها: (وكان ينهى عن عقبة الشيطان) هو الإقعاء الذي فسّرناه وهو مكروه باتفاق العلماء بهذا التفسير الذي ذكرناه، وأما الإقعاء الذي ذكره مسلم بعد هذا في حديث ابن عباس أنه سنة، فهو غير هذا كما سنفسّره في موضعه إن شاء الله تعالى. قولها: (وينهى أن يفترش الرجل ذراعيه افتراش السبع) سبق الكلام عليه في الباب قبله.`,
        o: `أبو حنيفة: يحتج بإطلاق حديث عائشة. الشافعي: الافتراش في الجلوس الأول والتورك في آخر الصلاة. بعض السلف: سنة المرأة التربع، وبعضهم التربع في النافلة.`,
        s: `(لأنه لم يرد التربع في الجلسات المعتادة، وورد التربع إذا صلى النافلة جالساً حال القيام.) (وهو أن يجلس على العقبين – نحن نسميهم الكعبين خطأً – وينصب القدمين (صوابع رجله واقفة تجاه القبلة على العقبين) فمشروع أن يجلس كذلك بين السجدتين.) (الركعتين، فهذا (الافتراش – وهو أن يفرش رجله اليسرى وينصب رجله اليمنى –) عام يخصص منه الأحاديث الآتية في التشهد الأخير.)`,
        f: [] },
      { q: `حكم التسليم من الصلاة: ركن أم واجب أم سنة؟ (مذاهب العلماء) وعدد التسليمات (تسليمة أم تسليمتان)`, p: `296–297`,
        n: `قولها: (وكان يختم الصلاة بالتسليم) فيه دليل على وجوب التسليم، فإنه ثبت هذا مع قوله ﷺ: «صلّوا كما رأيتموني أصلّي» واختلف العلماء فيه: – فقال مالك والشافعي وأحمد رحمهم الله تعالى وجمهور العلماء من السلف والخلف: السلام فرض ولا تصح الصلاة إلا به، – قال أبو حنيفة والثوري والأوزاعي ﵁: هو سنة لو تركه صحّت صلاته. قال أبو حنيفة رحمه الله تعالى: لو فعل منافيًا للصلاة من حدث أو غيره في آخرها صحّت صلاته، واحتجّ بأن النبي ﷺ لم يعلّمه الأعرابيّ في واجبات الصلاة حين علّمه واجبات الصلاة، واحتجّ الجمهور بما ذكرناه وبالحديث الآخر في سنن أبي داود والترمذي: «مفتاح الصلاة الطهور وتحليلها التسليم». ومذهب الشافعي وأبي حنيفة وأحمد ﵁ والجمهور أن المشروع تسليمتان. ومذهب مالك رحمه الله تعالى وطائفة المشروع تسليمة، وهو قول ضعيف عن الشافعي رحمه الله تعالى، ومن قال بالتسليمة الثانية فهي عنده سنة، وشذّ بعض الظاهرية والمالكية فأوجبها وهو ضعيف مخالف لإجماع من قبله. والله أعلم.`,
        o: `مالك والشافعي وأحمد والجمهور: السلام فرض. أبو حنيفة والثوري والأوزاعي: سنة. مالك وطائفة: تسليمة واحدة. الجمهور: تسليمتان (الثانية سنة). بعض الظاهرية والمالكية: تجب الثانية (ضعيف).`,
        s: `(الشافعية عندهم التسليم واجب أي ركن، فإنه لا يفرق بين الواجب والركن، وهذا عند أحمد أيضاً ولكن الصحيح أن التسليم غير وارد في حديث المسيء صلاته.) (أي أنه ينوي المفارقة فقط، والصحيح أنه واجب وليس بركن.) (والصحيح أن الحديث يدل على وجوب التسليم وليس الركنية (وتحليلها التسليم).) (الأولى فرض والثانية سنة وهذا هو الصحيح وهو السنة.) (ومخالف للسنة حيث قالت عائشة –رضي الله عنها-: (حيث يسلم تسليمة يسمعنا)، وتحليلها التسليم: ينطبق على تسليمه واحدة فإذا سلم تسليمة واحدة قد صحت صلاته عند عامة أهل العلم. – والصحيح كما ذكرنا أن التسليم واجب وتجزيء تسليمة واحدة والثانية مستحبة.)`,
        f: [] },
    ],
  },
  {
    title: `باب سترة المصلي (ص297–)`,
    items: [
      { q: `السترة بين يدي المصلي: حكمها (ندب)، أقل السترة (مؤخرة الرحل) وقدرها، وهل يكفي الخط بين يدي المصلي؟، ومعنى «مؤخرة الرحل» (أربع لغات)`, p: `300`,
        n: `قوله ﷺ: (إذا وضع أحدكم بين يديه مثل مؤخرة الرحل فليصلّ ولا يبالِ من مرّ وراء ذلك) (المُؤخِرة) بضمّ الميم وكسر الخاء وهمزة ساكنة، ويقال بفتح الخاء مع فتح الهمزة وتشديد الخاء، ومع إسكان الهمزة وتخفيف الخاء، ويقال (آخِرة الرحل) بهمزة ممدودة وكسر الخاء، فهذه أربع لغات وهي العود الذي في آخر الرحل. وفي هذا الحديث: – الندب إلى السترة بين يدي المصلّي – وبيان أن أقلّ السترة مؤخرة الرحل وهي قدر عظم الذراع، هو نحو ثلثي ذراع، – ويحصل بأي شيء أقامه بين يديه هكذا وشرط مالك رحمه الله تعالى أن يكون في غلظ الرمح. – قال العلماء: والحكمة في السترة كفّ البصر عما وراءه، ومنع من يجتاز بقربه، – واستدلّ القاضي عياض رحمه الله تعالى بهذا الحديث على أن الخطّ بين يدي المصلّي لا يكفي.`,
        o: `مالك: يشترط أن تكون في غلظ الرمح. القاضي عياض: الخط بين يدي المصلي لا يكفي. (وهناك خلاف في الخط بين يدي المصلي، وقيل يجزئ.)`,
        s: `(وهي عصى عريضة في آخر الرحل يستند عليها الراكب تكون بقدر شبر أو شبرين؛ فالذراع يساوي خمسين سنتيمتر، فالثلث يكون ٣٢ سم.) (وهذا هو الظاهر لأنه قال: (مثل مؤخرة الرحل) ويلزم منه أن يكون شيئاً مرتفعاً.)`,
        f: [] },
      { q: `الخط بين يدي المصلي بدل السترة: هل يجزئ؟ (حديث الخط)، وهل يضر المرور بين يديه إذا لم يضع سترة ولا خطًا؟`, p: `301`,
        n: `قال: (وإن كان قد جاء به حديث وأخذ به أحمد بن حنبل رحمه الله تعالى فهو ضعيف) واختُلف فيه: فقيل: يكون مقوّسًا كهيئة المحراب، وقيل قائمًا بين يدي المصلّي إلى القبلة، وقيل من جهة يمينه إلى شماله، قال: ولم ير مالك رحمه الله تعالى ولا عامة الفقهاء الخطّ. هذا كلام القاضي، وحديث الخطّ رواه أبو داود وفيه ضعف واضطراب، واختلف قول الشافعي رحمه الله تعالى فيه فاستحبّه في سنن حرملة وفي القديم، ونفاه في البويطي، وقال جمهور أصحابه باستحبابه، وليس في حديث مؤخرة الرحل دليل على بطلان الخطّ. والله أعلم. – قال أصحابنا: ينبغي له أن يدنو من السترة، ولا يزيد ما بينهما على ثلاث أذرع.`,
        o: `القاضي عياض ومالك وعامة الفقهاء: لا يكفي الخط. الشافعي: اختلف قوله (استحبه في سنن حرملة والقديم ونفاه في البويطي)، وجمهور أصحابه باستحبابه. أحمد: أخذ به.`,
        s: `(وبالفعل هو حديث ضعيف، ولكن قد يقال: أنه إن عجز عن ذلك فلا يكلف الله نفساً إلا وسعها فقد لا يجد إلا الخط أو شيئاً أقل ارتفاعاً من ذلك فلا يكلف ما لا يقدر عليه؛ ولكن إذا مر بين يديه ما يقطع الصلاة يكون فيه خلاف.) (أي أُختلف في الخط.) (ولكن مفهوم المخالفة في حديث [مثل مؤخرة الرحل] يدل على عدم الخط، وطالما الحديث ضعيف فلا يعمل به، ولكن كما ذكرنا أنه إذا كان عاجزاً فالمقدور عليه هو الواجب.) (أي ما بين وقوفه والسترة ثلاث أذرع أي [واحد ونصف متر] تقريباً لأن النبي ﷺ صلى إلى الكعبة وجعل بينه وبين الجدار ثلاثة أذرع. – أخبرنا محمد بن سلمة والحارث بن مسكين قراءة عليه وأنا أسمع عن ابن القاسم قال: حدثني مالك، عن نافع، عن عبد الله بن عمر، " أَنَّ رَسُولَ اللَّهِ ﷺ دَخَلَ الْكَعْبَةَ هُوَ وَأُسَامَةُ بْنُ زَيْدٍ وَبِلاَلٌ وَعُثْمَانُ بْنُ طَلْحَةَ الْحَجَبِيُّ فَأَغْلَقَهَا عَلَيْهِ، قَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ: فَسَأَلْتُ بِلاَلاً حِينَ خَرَجَ مَاذَا صَنَعَ رَسُولُ اللَّهِ ﷺ ؟ قَالَ: جَعَلَ عَمُودًا عَنْ يَسَارِهِ وَعَمُودَيْنِ عَنْ يَمِينِهِ وَثَلاَثَةَ أَعْمِدَةٍ وَرَاءَهُ، وَكَانَ الْبَيْتُ يَوْمَئِذٍ عَلَى سِتَّةِ أَعْمِدَةٍ، ثُمَّ صَلَّى وَجَعَلَ بَيْنَهُ وَبَيْنَ الْجِدَارِ نَحْوًا مِنْ ثَلاَثَةِ أَذْرُعٍ " (س) ٧٤٩ [قال الألباني]: صحيح. ويؤيده رواية البخاري: حَدَّثَنَا إِبْرَاهِيمُ بْنُ الْمُنْذِرِ قَالَ : حَدَّثَنَا أَبُو ضَمْرَةَ قَالَ : حَدَّثَنَا مُوسَى بْنُ عُقْبَةَ عَنْ نَافِعٍ أَنَّ عَبْدَ اللهِ كَانَ إِذَا دَخَلَ الْكَعْبَةَ مَشَى قِبَلَ وَجْهِهِ حِينَ يَدْخُلُ وَجَعَلَ الْبَابَ قِبَلَ ظَهْرِهِ فَمَشَى حَتَّى يَكُونَ بَيْنَهُ وَبَيْنَ الْجِدَارِ الَّذِي قِبَلَ وَجْهِهِ قَرِيبًا مِنْ ثَلاَثَةِ أَذْرُعٍ صَلَّى يَتَوَخَّى الْمَكَانَ الَّذِي أَخْبَرَهُ بِهِ بِلاَلٌ أَنَّ النَّبِيَّ ﷺ صَلَّى فِيهِ قَالَ وَلَيْسَ عَلَى أَحَدِنَا بَأْسٌ إِنْ صَلَّى فِي أَيِّ نَوَاحِي الْبَيْتِ شَاءَ.)`,
        f: [] },
      { q: `إذا لم يجد المصلي سترة: (عصًا ونحوها أو جمع أحجار أو تراب أو متاع، وإلا فليخط خطًا)، وهل يحرم المرور بينه وبين السترة؟ وبين المصلي وموضع سجوده؟ والمرور بين يدي الصف، وإلى أين تجعل السترة (عن يمينه أو شماله)`, p: `302–303`,
        n: `فإن لم يجد عصًا ونحوها جمع أحجارًا أو ترابًا أو متاعه، إلا فليبسط مصلّى، وإلا فليخطّ الخطّ، – وإذا صلّى إلى سترة منع غيره من المرور بينه وبينها، وكذا يمنع من المرور بينه وبين الخطّ، – ويحرُم المرور بينه وبينها، فلو لم يكن سترة أو تباعد عنها فقيل: له منعه، والأصح أنه ليس له لتقصيره، ولا يحرُم حينئذٍ المرور بين يديه، لكن يُكره، – ولو وجد الداخل فُرجة في الصف الأول فله أن يمرّ بين يدي الصف الثاني ويقف فيها لتقصير أهل الصف الثاني بتركها، – والمستحبّ أن يجعل السترة عن يمينه أو شماله ولا يصمد لها. والله أعلم.`,
        o: `قيل: للمصلي منع المار إن لم يكن له سترة أو تباعد عنها؛ والأصح: ليس له ذلك لتقصيره.`,
        s: `(أي آخر المصلي تكون هي السترة له.) (وهذا بناء على استحبابه.) (وهذا هو الصحيح إذا مر أبعد من أبعد من موضع سجوده، فمن صلى إلى غير سترة جاز أن يمر المار أبعد من موضع سجوده الذي سوف يمر منه لو اتخذ ستره لأنه إذا كان غير مقصر لم يلزمه أن يمر أبعد من ذلك فبالأولى مع تقصير المصلي، فينظر موضع السجود ويقدر ممر ممشاة بعدها ويمر، [ممر شاه بينه وبين موضع السجود].) (والصحيح أنه لو جاوز موضع السجود لم يكره.) (ولأن المرور بين يدي بعض الصف ليس مروراً بين يدي المصلي وسترته لأن سترة الإمام سترة للمأموم لحديث ابن عباس الآتي. – فالمرور أمام الصفوف لا يضر لكن لا يمر بدون حاجة لأن ذلك يشوش على المصلين ولا ينبغي ذلك بدون سبب. – وإذا لم يتخذ الإمام سترة فليتعد المار عن المرور بين الصفوف.)`,
        f: [`(ص302) (ويؤيده رواية البخاري في الكعبة...)`] },
      { q: `الحربة بين يدي المصلي، وركز العنزة، واتخاذ البعير والراحلة سترة، وأن الصلاة إلى الحيوان جائزة ومرور الدواب بين يديه، وهل تبطل الصلاة؟ (المرور والحمار والمرأة والكلب)`, p: `303`,
        n: `قوله: (حدثنا الطنافسي) هو بفتح الطاء وكسر الفاء. قوله: (يركز العنزة) هو بفتح الياء وضم الكاف وهو بمعنى يغرز المذكور في الرواية الأخرى. قوله: (كان يعرض راحلته وهو يصلي إليها) يعرض بفتح الياء وكسر الراء ورُوي بضم الياء وتشديد الراء ومعناه يجعلها معترضة بينه وبين القبلة. فيه دليل على جواز الصلاة إلى الحيوان، وجواز الصلاة بقرب البعير بخلاف الصلاة في عطان الإبل فإنها مكروهة للأحاديث الصحيحة في النهي عن ذلك، لأنه يُخاف هناك نفورها فيذهب الخشوع بخلاف هذا.`,
        o: NO_O,
        s: `(الحديث ضعيف والصحيح أنه يصلي إليها مباشرة.) (وفي قول طلحة ﷺ: (كنا نصلي والدواب تمر بين أيدينا) دليل ظاهر للجمهور في عدم بطلان الصلاة وبعض المعاصرين الذين يرون بطلان الصلاة إذا صلى بدون سترة خلافاً للظاهرية فإن النبي ﷺ كان يراهم كذلك ولم يأمرهم بإعادة الصلاة، ولكن بيّن لهم أن المرور إذا لم يتخذ المصلي سترة يضر بالصلاة فهل هذا الضرر هو البطلان أم النقصان؟ فطالما لم يأمرهم النبي ﷺ بإعادة الصلاة فهو نقصان وليس بطلان. – فأقصى قول يمكن القول به بالوجوب، والصحيح أنه سنة مؤكدة؛ ثم إن قوله ﷺ: (يقطع الصلاة المرأة والحمار والكلب الأسود) دليل على أن ما سواهم لا يقطعها ولا يبطلها، إذاً الضرر هنا ضرر نقصان وليس ضرر بطلان. – قوله ﷺ: (لا يضر ما مر بين يديه) أي بعد السترة، سواء العقل وغير العاقل.) (الحيوان: المقصود كل حي إنسان أو غيره فيجوز أن يصلي وإنسان جالس بين يديه أمامه كما كانت عائشة رضي الله عنها.) (ولأن أعطان الإبل مأوى الشياطين فيشوش عليه صلاته. – النبي ﷺ كان يأخذ معه الحربة ليتخذها سترة وكان يغرزها بين يديه والناس يمرون ورائها.)`,
        f: [] },
      { q: `قوله «فمن نائل وناضح»: التبرك بآثار الصالحين (وقوله «تبركًا بآثاره» وحكمه): الفرق بين آثار الأنبياء وآثار الصالحين، وحكم التبرك بالأشجار والأحجار`, p: `304–305`,
        n: `قوله: (فمن نائل وناضح) معناه فمنهم من ينال منه شيئًا، ومنهم من ينضح عليه غيره شيئًا مما ناله ويرُشّ عليه بللًا مما حصل له، وهو معنى ما جاء في الحديث الآخر فمن لم يصب أخذ من يد صاحبه. قوله: (فخرج بلال بوضوء فمن نائل وناضح فخرج النبي ﷺ فتوضأ) فيه تقديم وتأخير تقديره فتوضأ فمن نائل بعد ذلك وناضح، تبرّكًا بآثاره ﷺ وقد جاء مبيّنًا في الحديث الآخر: (فرأيت الناس يأخذون من فضل وضوئه). – ففيه التبرّك بآثار الصالحين واستعمال فضل طهورهم وطعامهم وشرابهم ولباسهم.`,
        o: `اختلفوا في التبرك بآثار الصالحين.`,
        s: `(من الوضوء وهذا من باب المواساة.) (فيتبرك بآثار النبي ﷺ وهذا مجمع على جوازه، واختلفوا في التبرك بآثار الصالحين والصحيح أنه لا يشرع التبرك إلا بآثار الأنبياء وهو طلب البركة من ملامسة أو مصاحبة أما الصالحون فرغم ثبوت صلاح العشرة المبشرون والسابقين الأولين بالقطع واليقين والنصوص القاطعة إلا أن الصحابة ﷺ لم يفعلوا شيء من ذلك فدل ذلك وهو كالإجماع منهم على عدم مشروعية التبرك بآثار الصالحين، أما الصحبة والعمل الصالح فيطلب بها الخير بلا شك، والكلام هنا عن التبرك المخصوص وهو الآثار والوضوء والعرق والثياب ونحو ذلك والصحابة لم يفعلوه مع من قُطِعَ بصلاحهم.) (أي فيما بقي من الوضوء وزعه بلال على الصحابة ﷺ.) (قلنا الخلاف في هذه المسألة ثابت، والنووي يذهب إلى جواز التبرك بآثار الصالحين، والقول الصحيح أن ذلك غير مشروع لكن المسألة فيها اجتهاد؛ فالتبرك الممنوع بالاتفاق هو التبرك بالأشجار والأحجار ونحو ذلك مما لا تعلق فيه بالصالحين أو تعلقهم به من باب ما يطلق عنه آثار كجلوسه تحت هذه الشجرة أو أن هذه الشجرة يظنون فيها حصول الخير لمن جلس تحتها مجرداً، وهذا ذريعة إلى الشرك الذي هو أن يعتقد أن الشيء الذي يتبرك به يضر وينفع مع الله أو بغير إذنه ﷺ أو من دونه فإذا اعتقد أن الشيء الذي يتبرك به ينفع مع الله أو من دونه فهو شرك أكبر وإذا اعتقد أنه سبب ولا دليل من كتاب أو سنة على ذلك فهذا شرك أصغر. – وأما آثار الصالحين فمختلف فيه والراجح منعه ولكن لا يغلظ فيه تغليظ التبرك بالأحجار والأشجار وقبور الصالحين ونحو ذلك مما لم يرد فيه دليل وليس فيه خلاف بين العلماء.) (وهذا خاص بالأنبياء قال تعالى: (وبقية مما ترك آل موسى وآل هارون) فهي تدل على آثار الأنبياء فقط.)`,
        f: [] },
      { q: `الحلة الحمراء (لباس الأحمر)، وأن الساق ليست بعورة (التشمير نوعان)، والأذان في السفر (وحكم الأذان حضرًا وسفرًا)`, p: `305–306`,
        n: `قوله: (عليه حلّة حمراء) قال أهل اللغة: الحلّة ثوبان لا يكون واحدًا، وهما إزار ورداء ونحوهما. – وفيه جواز لباس الأحمر. قوله (كأني أنظر إلى بياض ساقيه) – فيه أن الساق ليست بعورة وهذا مجمع عليه. قوله: (فأذّن بلال) – فيه الأذان في السفر. قال الشافعي ﵁: ولا أكره من تركه في السفر ما أكره من تركه في الحضر لأن أمر المسافر مبنيّ على التخفيف.`,
        o: NO_O,
        s: `(وهذا هو الصحيح خلافاً لابن القيم رحمه الله، والحديث صحيح وظاهر وطرقه كلها ثابتة من غير أن يثبت في واحد منها أنه كان مخططاً أو نحو ذلك كما قال ابن القيم والحديث مخرج في الصحيحين ولم يأتِ هو بدليل. ولهذا يجوز الرجل أن يلبس الأحمر إلا أن يكون ثوب شهرة كأحمر ناري؛ ونهى النبي ﷺ عن الثياب المعصفر وهو من صبغ الكفار وليس كل الأحمر مصبوغ بعصفر.) (فقد كان ثوب النبي ﷺ إلى نصف الساق وهذا معنى قوله (مشمراً): أي رافعاً إزاره إلى نصف الساق؛ والتشمير نوعان: ١– رفع الثوب مع عدم الكفت والضم بعضه إلى بعض. ٢– بالكفت وهو المنهي عنه وهذا قد سبق بيانه وهو ضم الثوب بعضه إلى بعض والتشمير ليس منهي عنه خارج الصلاة ولكن حين يصلي يفك التشمير، فإن عليه أن يُفصل ثياب قصيرة ولو طالت منه يشدها ولا يلزمه لأنه إذا كان يسترخي منه وهو لا يتعدى فهو مما لا يفعله خيلاء فلا يتعمد أن يكون الثوب دون الكعب.) (الصحيح أنه يجب الأذان حضراً وسفراً لأن النبي ﷺ أمر به في السفر فقال ﷺ: (إِذَا حَضَرَتِ الصَّلاَةُ فَأَذِّنَا وَأَقِيمَا ثُمَّ لِيَؤُمَّكُمَا أَكْبَرُكُمَا) البخاري؛ حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، عَنْ زَائِدَةَ بْنِ قُدَامَةَ، وَوَكِيعٍ، قَالَ: حَدَّثَنِي زَائِدَةُ بْنُ قُدَامَةَ، عَنِ السَّائِبِ، قَالَ وَكِيعٌ: ابْنِ حُبَيْشٍ الْكَلاَعِيِّ – عَنْ مَعْدَانَ بْنِ أَبِي طَلْحَةَ الْيَعْمُرِيِّ، قَالَ: قَالَ لِي أَبُو الدَّرْدَاءِ: أَيْنَ مَسْكَنُكَ؟ قَالَ: قُلْتُ: فِي قَرْيَةٍ دُونَ حِمْصَ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «مَا مِنْ ثَلاَثَةٍ فِي قَرْيَةٍ، وَلاَ يُؤَذَّنُ، وَلاَ تُقَامُ فِيهِمُ الصَّلَوَاتُ، إِلاَّ قَدِ اسْتَحْوَذَ عَلَيْهِمُ الشَّيْطَانُ، فَعَلَيْكَ بِالْجَمَاعَةِ، فَإِنَّمَا يَأْكُلُ الذِّئْبُ الْقَاصِيَةَ» (حم) ٢٧٥١٤ [إسناده حسن]. وكون الشيطان يستحوذ عليه دليل على أن فعله محرم؛ فالأذان واجب والإقامة واجبة؛ فالصحيح أنه فرض كفاية حضراً وسفراً.)`,
        f: [] },
      { q: `الالتفات في الأذان (عند «حي على الصلاة» و«حي على الفلاح»): كيفيته (ثلاثة أوجه عند الشافعية)`, p: `306–307`,
        n: `قوله: (فأذّن بلال فجعلت أتتبّع فاه هاهنا وهاهنا يقول يمينًا وشمالًا حيّ على الصلاة حيّ على الفلاح) – فيه أنه يُسَنّ للمؤذّن الالتفات في الحيعلتين يمينًا وشمالًا برأسه وعنقه. قال أصحابنا: ولا يحوّل قدميه وصدره عن القبلة، وإنما يلوي رأسه وعنقه. واختلفوا في كيفيّة التفاته على مذاهب، وهي ثلاثة أوجه لأصحابنا: – أصحّها وهو قول الجمهور أنه يقول: (حي على الصلاة) مرّتين عن يمينه، ثم يقول عن يساره مرّتين: (حي على الفلاح). – والثاني يقول عن يمينه حي على الصلاة مرة ثم مرة عن يساره، ثم يقول حي على الفلاح مرة عن يمينه ثم مرة عن يساره. – والثالث يقول عن يمينه حي على الصلاة ثم يعود إلى القبلة ثم يعود إلى الالتفات عن يمينه فيقول حي على الصلاة، ثم يلتفت عن يساره فيقول حي على الفلاح ثم يعود إلى القبلة، ويلتفت عن يساره فيقول حي على الفلاح.`,
        o: `ثلاثة أوجه عند الشافعية في كيفية الالتفات: (١) الحيعلة الأولى مرتين يمينًا والثانية مرتين يسارًا (الأصح وقول الجمهور)، (٢) حي على الصلاة مرة يمينًا ومرة يسارًا ثم حي على الفلاح كذلك، (٣) مع العودة إلى القبلة بين كل التفاتة.`,
        s: `(وهذا هو الأقرب.) (الأقرب هو القول الثاني والمسألة محتملة لأنه قد يكون من باب اللف والنشر، فيقول يميناً وشمالاً أي يقول يميناً حي على الصلاة وشمالاً حي على الصلاة، ويقول يميناً حي على الفلاح وشمالاً حي على الفلاح، ويمكن أن يحمل على ظاهره كل واحدة منهما يمين وشمال فيقول حي على الصلاة بجهة اليمين وبجهة اليسار وحي على الفلاح بجهة اليمين وبجهة اليسار؛ ولن يحصل ذلك إلا بأن يقول مرة عن يمينه حي على الصلاة ومرة عن شماله حي على الصلاة، وهذا أقرب من جهة المعنى فيبلغ الذين هم عن اليمين والذين عن الشمال فيبلغهم الفلاح في الصلاة يميناً وشمالاً.) (ويستفاد منه الوجوب على قول من يوجبه من أدلة أخرى.)`,
        f: [] },
      { q: `القصر في السفر: هل الأفضل القصر؟ ومتى يبدأ القصر (قرب البلد)؟ وكم مدة الإقامة التي تقطع حكم السفر (أربعة أيام)؟ (والإتمام لمن نوى الإقامة)، وقصر الصلاة والجمع`, p: `307–309`,
        n: `قوله: (فصلّى الظهر ركعتين) – فيه أن الأفضل قصر الصلاة في السفر، وإن كان بقُرب بلد ما لم ينوِ الإقامة أربعة أيام فصاعدًا. – ومن نوى الإقامة فإنه أول ما يصل يُتمّ لأنه أصبح مقيمًا ولا يأخذ برخص السفر.`,
        o: `الشافعي ومالك وأحمد والجمهور: من أقام أكثر من أربعة أيام (٢١ صلاة) فصاعدًا فهو مقيم لغة وشرعًا ويتم الصلاة.`,
        s: `(وذلك لأن النبي ﷺ جعل من أقام أكثر من ثلاثة أيام غير الدخول والخروج مقيماً، ففي صحيح مسلم عَنْ عَبْدِ الرَّحْمَنِ بْنِ حُمَيْدٍ قَالَ سَمِعْتُ عُمَرَ بْنَ عَبْدِ الْعَزِيزِ يَقُولُ لِجُلَسَائِهِ مَا سَمِعْتُمْ فِي سُكْنَى مَكَّةَ فَقَالَ السَّائِبُ بْنُ يَزِيدَ سَمِعْتُ الْعَلاَءَ – أَوْ قَالَ الْعَلاَءُ بْنُ الْحَضْرَمِيِّ – قَالَ رَسُولُ اللَّهِ ﷺ: «يُقِيمُ الْمُهَاجِرُ بِمَكَّةَ بَعْدَ قَضَاءِ نُسُكِهِ ثَلاَثًا» قَالَ: قَالَ الشَّافِعِيُّ فِي رِوَايَةِ أَبِي سَعِيدٍ: وَكَانَ هَذَا أَشْبَهَ أَنْ يَكُونَ أَقْصَى غَايَةِ مُقَامِ الْمُسَافِرِ، وَكَانَ مَا جَاوَزَهُ يُشْبِهُ أَنْ يَكُونَ مُقَامَ مُقِيمٍ، فَلَمْ يَكُنْ بَعْدُ يَوْمٌ كَامِلٌ إِلاَّ لأَرْبَعٍ، فَذَهَبْنَا إِلَى أَنَّ مَنْ أَجْمَعَ مُقَامَ أَرْبَعٍ فَقَدْ خَرَجَ مِنْ حَدِّ مُقَامِ الْمُسَافِرِ لَيْسَ فِي الأَرْبَعِ الْيَوْمُ الَّذِي دَخَلَ فِيهِ، وَلاَ الَّذِي يَخْرُجُ فِيهِ، وَذَلِكَ فِي كِلَيْهِمَا مُسَافِرٌ. قَالَ الشَّافِعِيُّ: وَأَجْلَى عُمَرُ بْنُ الْخَطَّابِ أَهْلَ الذِّمَّةِ مِنَ الْحِجَازِ، وَضَرَبَ لِمَنْ يَقْدَمُ مِنْهُمْ تَاجِرًا مُقَامَ ثَلاَثٍ، فَأَشْبَهَ مَا وَصَفْتُ مِنَ السُّنَّةِ] معرفة السنن والآثار للبيهقي؛ فسماه مقيماً لأن المهاجرين محرم عليهم الإقامة بمكة، فجعل الإقامة فوق ثلاث غير الدخول والخروج بمنزلة الإقامة الدائمة فهذا يدل على قول جمهور أهل العلم مالك وأحمد والشافعي أن من أقام أكثر من أربعة أيام(٢١ صلاة) فصاعداً فهذا مقيم لغةً وشرعاً وعليه أن يُتم الصلاة. – ومن نوى الإقامة: فإنه أول ما يصل يُتم لأنه أصبح مقيماً ولا يأخذ برخص السفر.)`,
        f: [] },
      { q: `الجمع بين الظهر والعصر في السفر: هل في حديث «صلى الظهر ركعتين والعصر ركعتين» دليل على الجمع؟ وتقديم الثانية إلى وقت الأولى وتأخير الأولى إلى الثانية`, p: `308–309`,
        n: `قوله: (خرج رسول الله ﷺ بالهاجرة إلى البطحاء فتوضأ فصلى الظهر ركعتين، والعصر ركعتين، وبين يديه عنزة) – فيه دليل على القصر والجمع في السفر، – وفيه أن الأفضل لمن أراد الجمع وهو نازل في وقت الأولى أن يقدّم الثانية إلى الأولى، وأما من كان في وقت الأولى سائرًا فالأفضل تأخير الأولى إلى وقت الثانية، كذا جاءت الأحاديث، ولأنه أرفق به.`,
        o: NO_O,
        s: `(بل ليس فيه دليل على الجمع لأنه لم يقل فصلى الظهر والعصر جمعاً وإنما قال: (صلى الظهر ركعتين والعصر ركعتين) أي كلٌّ في وقته فإن هذا كان في وقته في حجة الوداع والنبي ﷺ لم يجمع في البطحاء.)`,
        f: [`(ص308) ❖ فتاوى: ١– المسجد الحرام ينطبق عليه أحكام الستر لأن هذا كان في البطحاء وهي من مكة من أرض الحرم، فالصحيح أن ذلك في كل مكان. ٢– وهذا الحرج موجود في المسجد الحرام والمسجد النبوي ومع كل زحام، ومع ذلك فالنبي ﷺ كان يتخذ السترة في الحرم.`, `(ص309) ٣– الخطوط الموجودة على أرضية المسجد لا تعتبر سترة؛ هذا إن عجز عن اتخاذ سترة فنهاية الموكيت والمصلية. ٤– إذا سألك أحد: أأنت مؤمن؟ تقول: آمنت بالله ورسوله أو أنا مؤمن إن شاء الله.`] },
      { q: `الحمار والكلب خلف السترة وقدامها: هل يقطعان الصلاة؟ (المرور وراء السترة)، ولبس الحلة الحمراء المشمّرة ورفع الثوب عن الكعبين`, p: `308`,
        n: `قوله: (يمرّ بين يديه الحمار والكلب لا يُمنع) معناه يمرّ الحمار والكلب وراء السترة وقدّامها إلى القبلة؛ كما قال في الحديث الآخر: (ورأيت الناس والدواب يمرّون بين يدي العنزة)، وفي الحديث الآخر (فيمرّ من ورائها المرأة والحمار)، وفي الحديث السابق (ولا يضرّه من مرّ وراء ذلك). قوله: (وخرج رسول الله ﷺ في حلّة حمراء مشمّرًا) يعني رافعها إلى أنصاف ساقيه ونحو ذلك كما قال في الرواية السابقة (كأني أنظر إلى بياض ساقيه)، – وفيه رفع الثوب عن الكعبين.`,
        o: NO_O,
        s: NO_N,
        f: [] },
      { q: `قول ابن عباس «وأنا يومئذ قد ناهزت الاحتلام» (سنه عند وفاة النبي ﷺ)، وفوائد حديث الحمار الأتان: صلاة الصبي صحيحة، وسترة الإمام سترة لمن خلفه (ومرور الحمار بين بعض الصف)، واختلافهم: هل سترة الأمام سترة للمأموم؟`, p: `309–310`,
        n: `قوله: (أقبلت راكبًا على أتان) وفي الرواية الأخرى (على حمار)، وفي رواية للبخاري (على حمار أتان). قال أهل اللغة: (الأتان) هي الأنثى من جنس الحمير، ورواية من روى (حمار) محمولة على إرادة الجنس، ورواية البخاري مبيّنة للجميع. قوله: (وأنا يومئذٍ قد ناهزت الاحتلام) معناه قاربته. واختلف العلماء في سنّ ابن عباس ﵄ ما عند وفاة رسول الله ﷺ فقيل: عشر سنين، وقيل: ثلاث عشرة، وقيل: خمس عشرة، وهو رواية سعيد بن جبير عنه. قال أحمد بن حنبل ﵁: وهو الصواب. قوله: (فأرسلت الأتان ترتع) أي ترعى. قوله: (يصلي بمنى) فيها لغتان الصرف وعدمه، ولهذا يكتب بالألف والياء، والأجود صرفها وكتابتها بالألف، سُمّيت (منى) لما يُمنى بها من الدماء أي يُراق ومنه قول الله تعالى: {من منيّ يُمنى}. وفي هذا الحديث: – أن صلاة الصبيّ صحيحة، – وأن سترة الإمام سترة لمن خلفه. قال القاضي عياض رحمه الله تعالى: واختلفوا هل سترة الأمام بنفسها سترة لمن خلفه، أم هي سترة له خاصة وهو سترة لمن خلفه، مع الاتفاق على أنهم مصلّون إلى سترة؟ قال: ولا خلاف أن السترة مشروعة، إذا كان في موضع لا يأمن المرور بين يديه، واختلفوا إذا كان في موضع يأمن المرور بين يديه، وهما قولان في مذهب مالك. ومذهبنا أنها مشروعة مطلقًا لعموم الأحاديث، ولأنها تصون بصره، وتمنع الشيطان المرور والتعرض لإفساد صلاته كما جاءت الأحاديث.`,
        o: `القاضي عياض: هل سترة الإمام سترة له خاصة وهو سترة لمن خلفه، أم سترة لمن خلفه؟ قولان في مذهب مالك: السترة مشروعة في موضع لا يؤمن المرور، وفي موضع يؤمن المرور؟ (مذهب الشافعية: مشروعة مطلقًا). اختلفوا في سنّ ابن عباس: عشر، أو ثلاث عشرة، أو خمس عشرة (وهو الصواب عند أحمد).`,
        s: `(صحيحة: أي مقبولة مثاب عليها يؤمر بها.) (لمرور الأتان بين يدي بعض الصف فلو كان هذا ممنوعاً لأنكر عليه الصحابة ﷺ ولكن طالما مرت خلف الإمام وبين يدي بعض الصف – أي أمام جزء من الصف فقط – فلا حرج في ذلك؛ ولذا المرور بين يدي بعض الصف للحاجة جائز كأن انتقض وضوءه وكان هناك مكان بالداخل ولن يستطيع المرور إليه إلا من خلال المرور أمام المصلين جاز طالما أن هناك حاجة.) (فلو قلنا هي سترة لمن خلفه، فالذي يمنع فقط هو المرور أمام الإمام وسترته؛ ولو قلنا الإمام سترة لمن خلفه، يكون كل صف هو سترة لمن بعده وهنا لا يجوز المرور بين يدي بعض الصف وبين الإمام ومن ورائه مباشرة وهذا ليس بصحيح لأن النبي ﷺ جعل البهيمة تمر من ورائه وكانت تريد أن تمر بين يديه، فلو كان الإمام سترة لمن خلفه لكان ذلك قاطعاً لصلاتهم أو نقصاً في صلاتهم، ولكن قد دل هذا الحديث على أن سترة الإمام سترة للمأمومين فيكون الممنوع ما بين الإمام وسترته.) (بمعنى أن المأمومين لا يحتاجون أن يضع كل واحد منهم سترة أمامه.) (درجة المشروعية فيها خلاف بين العلماء، فعامة العلماء على أنها سنة مؤكدة وبعضهم يقول بالوجوب لأن النبي ﷺ أمر بها: (فليستتر)، والصحيح أنها سنة مؤكدة؛ فدل ذلك على أنه لا تبطل الصلاة بمرور غير ذلك، وقول النبي ﷺ: «مِثْلُ مُؤْخِرَةِ الرَّحْلِ تَكُونُ بَيْنَ يَدَيْ أَحَدِكُمْ ثُمَّ لاَ يَضُرُّهُ مَا مَرَّ بَيْنَ يَدَيْهِ». وَقَالَ ابْنُ نُمَيْرٍ «فَلاَ يَضُرُّهُ مَنْ مَرَّ بَيْنَ يَدَيْهِ». فجعل ذلك مردوداً إلى فعله، فدل ذلك على صحة الصلاة من غير سترة.) (فإذا أمن المرور فإنها مستحبة أيضاً لأنه قد يمر مار.)`,
        f: [] },
    ],
  },
  {
    title: `باب منع المارّ بين يدي المصلي (ص311–312)`,
    items: [
      { q: `دفع المار بين يدي المصلي: حكمه (ندب أم وجوب؟) ومعنى «فليقاتله فإنما هو شيطان»`, p: `312`,
        n: `قوله ﷺ: (إذا كان أحدكم يصلّي فلا يدع أحدًا يمرّ بين يديه، وليدرأ ما استطاع فإن أبى فليقاتله؛ فإنما هو شيطان) معنى (يدرأ) يدفع، وهذا الأمر بالدفع أمر ندب، وهو ندب مؤكَّد، ولا أعلم أحدًا من العلماء أوجبه، بل صرّح أصحابنا وغيرهم بأنه مندوب غير واجب.`,
        o: NO_O,
        s: `(هناك من أهل الحديث من أوجبه مع الظاهرية.)`,
        f: [] },
      { q: `مقاتلة المار بين يدي المصلي: هل يلزمه القتال بالسلاح؟ ودية من مات بدفعه، وهل يجب فيه قود؟ وقول القاضي عياض في اتفاق العلماء على مشروعية الدفع`, p: `313`,
        n: `قال القاضي عياض: وأجمعوا على أنه لا يلزمه مقاتلته بالسلاح، ولا ما يؤدّي إلى هلاكه، فإن دفعه بما يجوز فهلك من ذلك فلا قود عليه باتفاق العلماء، وهل تجب ديته أم يكون هدرًا؟ فيه مذهبان للعلماء، وهما قولان في مذهب مالك ﵁، قال: واتفقوا على أن هذا كله لمن لم يفرّط في صلاته، بل احتاط وصلّى إلى سترة أو في مكان يأمن المرور بين يديه، ويدلّ عليه قوله في حديث أبي سعيد في الرواية التي بعد هذه (إذا صلّى أحدكم إلى شيء يستره، فأراد أحد أن يجتاز بين يديه، فليدفع في نحره، فإن أبى فليقاتله) قال: وكذا اتفقوا على أنه لا يجوز له المشي إليه من موضعه ليردّه، وإنما يدفعه ويردّه من موقفه، لأنّ مفسدة المشي في صلاته أعظم من مروره من بعيد بين يديه، وإنما أبيح له قدر ما تناله يده من موقفه، ولهذا أُمر بالقرب من سترته، وإنما يردّه إذا كان بعيدًا منه بالإشارة والتسبيح. قال: وكذلك اتفقوا على أنه إذا مرّ لا يردّه لئلا يصير مرورًا ثانيًا إلا شيئًا رُوي عن بعض السلف أنه يردّه وتأوّله بعضهم. هذا آخر كلام القاضي رحمه الله تعالى، وهو كلام نفيس.`,
        o: `اختلف في دية من هلك بدفع المصلي: تجب أو هدر (قولان في مذهب مالك). بعض السلف: يرده إذا مر.`,
        s: `(القود هو القصاص كرجل كبير في السن ثم دفعه فوقع فأصيب فمات.) (الصحيح أنه لا قود ولا دية لأنه فعل مأموراً به، ومن أمر الشرع بقتاله بالمشروع وبالجائز فهلك في ذلك بغير زيادة من الدافع لم يكن عليه ديه ولا شيء.) (هذا إذا كان مفرط وغير قريب من السترة وأراد أحد أن يمر فليس له أن يمشي إليه؛ ولكن إذا كان قريب من السترة فله أن يمشي الخطوة والخطوتين لأن النبي ﷺ اقترب من الجدار حتى كانت بطنه تلتصق بالجدار فجعل البهمة تمر من خلفه فدل ذلك أن له أن يمشي إذا كان قريباً من السترة.)`,
        f: [] },
      { q: `الذي يدفعه المصلي إذا أراد المرور بينه وبين سترته (بأسهل الوجوه)، ومقاتلة المار المباحة لا ضمان فيها، ومفسدة المشي إذا كان قريبًا من سترته، ومرور الأشياء`, p: `314`,
        n: `والذي قاله أصحابنا أنه يردّه إذا أراد المرور بينه وبين سترته بأسهل الوجوه، فإن أبى فبأشدّها، وإن أدّى إلى قتله فلا شيء عليه كالصائل عليه لأخذ نفسه أو ماله، وقد أباح له الشرع مقاتلته، والمقاتلة المباحة لا ضمان فيها.`,
        o: NO_O,
        s: `(مفسدة المشي إذا كان قريباً من سترته ولا يتمكن من دفعه إلا بأن يمشي خطوة أو خطوتين حتى يمر من ورائه فليمشي وليتقدم لأن النبي ﷺ فعل ذلك، فأحياناً يكون الدفع غير وارد إلا أن يتقدم لإصرار المار على المرور أو لكونه لا يعي أو لا يفهم، فنقول عليه أن يتقدم ليجعله يمر من ورائه. – مرور الأشياء ككتب أو غير ذلك هو مثل البهيمة، فلا يجوز مرور الأشياء بين يدي المصلي.)`,
        f: [] },
      { q: `معنى «فإنما هو شيطان» (الأقوال)، وإطلاق كلمة «شيطان» على الإنسان العاصي، وهل يقتضي التكفير؟`, p: `314`,
        n: `قوله ﷺ: (فإنما هو شيطان) قال القاضي: معناه إنما حمله على مروره وامتناعه من الرجوع الشيطان، وقيل: معناه يفعل فعل الشيطان لأن الشيطان بعيد من الخير وقبول السنة، وقيل: المراد بالشيطان القرين كما جاء في الحديث الآخر (فإن معه القرين). والله أعلم.`,
        o: `القاضي عياض: حمله الشيطان على المرور؛ أو يفعل فعل الشيطان؛ أو المراد القرين.`,
        s: `(فشطن بمعنى بعُدَ، فالذي يمر بين يدي المصلي شطن أي بعد عن الحق فهو شيطان بهذا الاعتبار.) (هو شيطان أي الدافع له على المرور، والإطلاق للتغليظ ولو قيل إنها هو شيطان على أن الشخص شيطان فيكون دليل على أن كلمة شيطان إذا أطلقت على المسلم لا تقتضي التكفير ويمكن أن تطلق على المسلم العاصي.)`,
        f: [] },
      { q: `إثم المار بين يدي المصلي: هل هو من الكبائر؟ وكم الوقوف أربعين (يومًا أو شهرًا أو سنة)؟`, p: `315`,
        n: `قوله ﷺ: (لو يعلم المارّ بين يدي المصلّي ماذا عليه لكان أن يقف أربعين خير له من أن يمرّ بين يديه) معناه: لو يعلم ما عليه من الإثم لاختار الوقوف أربعين على ارتكاب ذلك الإثم، ومعنى الحديث النهي الأكيد والوعيد الشديد في ذلك.`,
        o: NO_O,
        s: `(بل يدل على تحريم المرور بين يدي المصلي وأنه من الكبائر ولو كان أقل شيء أربعين يوماً، فلنتخيل أن شخصاً يقف أربعين يوماً أهون عليه أن يمر بين يدي المصلي فضلاً عن ما هو أشد من ذلك كأربعين شهراً أو سنة.)`,
        f: [] },
    ],
  },
  {
    title: `باب دنوّ المصلي من السترة (ص315–317)`,
    items: [
      { q: `قرب المصلي من السترة (ثلاثة أذرع أم ممر شاة؟)، وقوله «كان بين مصلى رسول الله ﷺ وبين الجدار ممر الشاة»، وإعادة الركوع والحركة لمصلحة الصلاة`, p: `316`,
        n: `قوله: (كان بين مصلّى رسول الله ﷺ وبين الجدار ممرّ الشاة) يعني بالمصلّى موضع السجود، – وفيه أن السنّة قُرب المصلّى من سترته.`,
        o: NO_O,
        s: `(إذا كان قائماً يكون الموضع بينه وبين الستره قدر ثلاثة أذرع لأن النبي ﷺ لما صلى في الكعبة جعل بينه وبين الجدار ثلاثة أذرع؛ أما هنا فالكلام على موضع السجود لذا وهو واقف متر ونصف وهو ساجد قدر ممر شاة حوالي ثلاثين سم تقريباً.) (وهذا الحديث فهمه الناس خطأً وظن أنه يقرب ممر شاة بأن يكون بينه وبين الستره ممر شاة وهو قائم يكاد يلتصق بالجدار وكلما أراد أن يسجد رجع إلى الوراء، ولا شك أن هذا فهم قاصر منكر لم يقل به أهل العلم، فإنه قد عمل بحديث وأهمل آخر وظن أن هذا هو الفهم المعتبر فيه وهو ليس كذلك، وإنما المقصود هو موضع السجود.) (النهي عن المرور يكون بين يدي الإمام وسترته والمنفرد وسترته أما إذا مر بين يدي بعض الصفوف خلف الإمام فلا يدخل في هذا الوعيد.) (الحركة إلى الأمام والخلف لا تبطل الصلاة طالما كانت يسيرة – خطوة أو خطوتين – في الركعة ولو تكررت لأن النبي ﷺ صلى على المنبر فنزل ثلاث درجات وصعد في كل ركعة ليعلمهم الصلاة فدل ذلك على أن مثل هذه الحركة لا تبطل الصلاة وإذا كانت لها مصلحة للصلاة مثل القرب من الستره أو تعليم الناس فهي مشروعة. – والنبي ﷺ كان يتحرك حتى كادت بطنه أن تلتصق في الجدار للمحافظة على كمال الصلاة وهو أن مرور أي شيء ينقص الصلاة فهو يحافظ على صلاة نفسه وصلاة المأمومين خلفه ثم رجع بعد أن مرت بين يديه، فهذه الحركة إذا كانت لمصلحة الصلاة فمشروعة.)`,
        f: [] },
      { q: `التحري بالصلاة عند الأسطوانة (ملازمة موضع واحد للصلاة)، ومعنى «يسبح» (النافلة)، وجواز الصلاة بين الأساطين والصف بين السواري (كراهة؟)`, p: `317–318`,
        n: `المراد بالتسبيح صلاة النافلة، والسجود صلاة النافلة، وفي المصحف ثلاث لغات ضم الميم وفتحها وكسرها. وفي هذا أنه لا بأس بإدامة الصلاة في موضع واحد إذا كان فيه فضل. وأما النهي عن إيطان الرجل موضعًا من المسجد يُلازمه فهو فيها لا فضل فيه ولا حاجة إليه، فأما ما فيه فضل فقد ذكرناه، وأما من يحتاج إليه لتدريس علم أو للإفتاء أو سماع الحديث ونحو ذلك فلا كراهة فيه، بل هو مستحب لأنه من تسهيل طرق الخير، وقد نقل القاضي ﵀ خلاف السلف في كراهة الإيطان لغير حاجة، والاتفاق عليه لحاجة نحو ما ذكرناه. قوله: (كان بين المنبر والقبلة قدر ممر الشاة) المراد بالقبلة الجدار وإنما أخّر المنبر عن الجدار لئلا ينقطع نظر أهل الصف الأول بعضهم عن بعض. قوله: (كان يتحرّى الصلاة عند الأسطوانة) فيه ما سبق أنه لا بأس بإدامة الصلاة في مكان واحد إذا كان فيه فضل. وفيه جواز الصلاة بحضرة الأساطين، فأما الصلاة إليها فمستحبة، لكن الأفضل أن لا يصمد إليها بل يجعلها عن يمينه أو شماله كما سبق. وأما الصلاة بين الأساطين فلا كراهة فيها عندنا، واختلف قول مالك في كراهتها إذا لم يكن عذر، وسبب الكراهة عنده أنه يقطع الصف ولأنه يصلي إلى غير جدار قريب.`,
        o: `مالك (اختلف قوله): يكره الصلاة بين الأساطين إذا لم يكن عذر (لأنها تقطع الصف). الشافعية: لا كراهة.`,
        s: `(إذا كان نافلة ثواب ذلك مثل الروضة تجد هناك من يقول هذا مكان الاسطوانة التي كان يصلي عندها النبي ﷺ فيستحب الصلاة فيه إذا قدر عليه، ولكن لا يشرع التمسح بهذه الاسطوانة مثلاً.) (أي يجوز جعل الاسطوانة سترة وهذا سبب وضع مسلم الحديث في هذا الباب (باب الستره).) (الحديث في ذلك ضعيف، والصحيح أنه يصلي إليها.) (والصحيح الكراهة وليس عدم الكراهة كما رجح هو.) (فإذا كان هناك اتساع فلا ينبغي أن يصلوا بين الأساطين لأن الصحابة ﷺ كانوا يدفعون عن الصلاة بين السواري: فعَنْ عَبْدِ الْحَمِيدِ بْنِ مَحْمُودٍ قَالَ: كُنَّا مَعَ أَنَسٍ فَصَلَّيْنَا مَعَ أَمِيرٍ مِنَ الأُمَرَاءِ، فَدَفَعُونَا حَتَّى قُمْنَا وَصَلَّيْنَا بَيْنَ السَّارِيَتَيْنِ، فَجَعَلَ أَنَسٌ يَتَأَخَّرُ وَقَالَ: "قَدْ كُنَّا نَتَّقِي هَذَا عَلَى عَهْدِ رَسُولِ اللَّهِ ﷺ " ، (س) ٨٢١ [قال الألباني]: صحيح، وعَنْ قُرَّةَ بْنِ إِيَاسٍ ﷺ قَالَ: "كُنَّا نُنْهَى أَنْ نَصُفَّ بَيْنَ السَّوَارِي عَلَى عَهْدِ رَسُولِ اللَّهِ ﷺ ، وَنُطْرَدُ عَنْهَا طَرْدًا " ((جة) ١٠٠٢ ، (خز) ١٥٦٧ ، (حب) ٢٢١٩، (ك) ٧٩٤ ، انظر الصَّحِيحة: ٣٣٥ [قال الألباني]: حسن صحيح)، وذلك لأنه يقطع الصف والأفضل أن تكون الصفوف متصلة؛ وأما مع وجود العذر كضيق المسجد واحتاجوا إلى أن يصفوا بين الأعمدة فلا بأس بذلك للحاجة. – وجود الأطفال لا يقطع الصف إذا كان مميزاً [سبع سنين فما زاد] فابن عباس ﷺ كان يناهز الاحتلام [أي لم يحتلم بعد] وصُف في الصف؛ والظاهر أن الصبي إذا وجد فُرجة في الصف الأول وقف فيها ولم يُدفع؛ وأما إذا كان دون ذلك فالصحيح أنه يقطع الصف لأنه لا يصلي، فلا يجعل من دون سبع سنين في الصف فيمكن جعله في الأطراف أو أمام أبيه وأمه.)`,
        f: [`(ص318) (والصحيح الكراهة وليس عدم الكراهة كما رجح هو.) — فإذا كان هناك اتساع فلا ينبغي أن يصلوا بين الأساطين.`] },
    ],
  },
  {
    title: `باب قدر ما يستر المصلي (ص318–321)`,
    items: [
      { q: `هل يقطع الصلاة مرور الحمار والمرأة والكلب الأسود؟ (مذاهب العلماء والجمع بين الأحاديث والنسخ)`, p: `319–320`,
        n: `قوله ﷺ: (يقطع صلاته الحمار والمرأة والكلب الأسود) اختلف العلماء في هذا: – فقال بعضهم: يقطع هؤلاء الصلاة، – وقال أحمد بن حنبل ﵁: يقطعها الكلب الأسود، وفي قلبي من الحمار والمرأة شيء، ووجه قوله [إن الكلب لم يجيء في الترخيص فيه شيء يعارض هذا الحديث]، وأما المرأة ففيها حديث عائشة رضي الله عنها المذكور بعد هذا، وفي الحمار حديث ابن عباس السابق، – وقال مالك وأبو حنيفة والشافعي ﵁ وجمهور العلماء من السلف والخلف: لا تبطل الصلاة بمرور شيء من هؤلاء ولا من غيرهم، وتأوّل هؤلاء هذا الحديث على أن المراد بالقطع نقص الصلاة لشغل القلب بهذه الأشياء، وليس المراد إبطالها، ومنهم من يدّعي نسخه بالحديث الآخر: [لا يقطع صلاة المرء شيء وادرؤوا ما استطعتم]، وهذا غير مرضيّ لأنّ النسخ لا يُصار إليه إلا إذا تعذّر الجمع بين الأحاديث وتأويلها وعلمنا التاريخ، وليس هنا تاريخ، ولا تعذّر الجمع والتأويل، بل يُتأوّل على ما ذكرناه، مع أن حديث (لا يقطع صلاة المرء شيء) ضعيف. والله أعلم.`,
        o: `بعضهم: يقطع الصلاة (وهو قول الظاهرية وطائفة من أهل الحديث). أحمد: يقطعها الكلب الأسود (وفي قلبه من الحمار والمرأة شيء). مالك وأبو حنيفة والشافعي والجمهور: لا تبطل بمرور شيء، والقطع المراد به نقص الصلاة. ومنهم من يدعي النسخ.`,
        s: `(وهو قول الظاهرية وطائفة من أهل الحديث وهو الصحيح.) (لماذا المرأة؟ الحديث عائشة رضي الله عنها، ولماذا الحمار؟ لحديث ابن عباس ﷺ. – وليس في حديث عائشة دلالة ولا في حديث ابن عباس؛ فحديث ابن عباس ﷺ فإنه مر خلف الإمام أو بين يدي بعض الصف وليس بين الإمام وسترته، وفي حديث عائشة رضي الله عنها فإنها كانت معترضة وليست مارة ثم كانت على السرير فالسرير هو الستره.) (ولكن ما الفرق بين هؤلاء وبين غيرها؟ فيؤخذ عليهم هذا الكلام. فالنبي ﷺ خصص قطع الصلاة بهذه الثلاثة مع أنه يضره كل من مر بين يديه فلذا قال: (فلا يضره من مر بين يديه) إذا كان يصلي إلى سترة والآخرين غير الثلاث إذا مروا وهو إلى غير سترة ضروه ضرر نقصان فلا يصح حمل الثلاثة على أن ضررهم ضرر نقصان مثل الآخرين بل هو ضرر بطلان.) (هذا الحديث ضعيف، ولا يحتج بالحديث الضعيف في مقابلة الصحيح.) (إذاً فلا يلجأ إلى الجمع حتى يثبت الحديث أصلاً؛ فهذا تعارض بين صحيح وضعيف فلا قوة للضعيف على معارضة الصحيح، فلا نلجأ للجمع ولا الترجيح ولا للنسخ مع ضعف الحديث.)`,
        f: [] },
    ],
  },
  {
    title: `باب الاعتراض بين يدي المصلي (ص321–326)`,
    items: [
      { q: `اعتراض المرأة بين يدي المصلي (كاعتراض الجنازة): هل تقطع الصلاة؟ وصلاة الرجل إليها وكراهة الصلاة إلى امرأة لغير النبي ﷺ (خوف الفتنة)`, p: `322–323`,
        n: `قوله: (عن عائشة رضي الله عنها أنها قالت: كان النبي ﷺ يصلي من الليل وأنا معترضة بينه وبين القبلة كاعتراض الجنازة) استدلّت به عائشة رضي الله عنها والعلماء بعدها على أن المرأة لا تقطع صلاة الرجل، وفيه جواز صلاته إليها، وكره العلماء أو جماعة منهم الصلاة إليها لغير النبي ﷺ لخوف الفتنة بها وتذكّرها، وإشغال القلب بها بالنظر إليها، وأما النبي ﷺ فمنزّه عن هذا كلّه وصلاته مع أنه كان في الليل، والبيوت يومئذ ليس فيها مصابيح.`,
        o: `العلماء أو جماعة منهم: تكره الصلاة إلى المرأة لغير النبي ﷺ خوف الفتنة.`,
        s: `(فيه: جواز النوم على السرير لنوم عائشة –رضي الله عنها– عليه وكان ستره للنبي ﷺ.) (قلنا أن توجيهها أنها معترضة وليست مارة.) (الصحيح أن الأمر معلق على الفتنة، فإن كان رجل لا يفتن بامرأته أو امرأة كانت ممن لا يشتهيها لا يكره الصلاة إليها ولو كانت امرأته وهو يتحكم في شهوته فلا تكره الصلاة إليها لأن النبي ﷺ فعل ذلك ولا دليل على الخصوصية فالأصل عدم الخصوصية فإذا قال أن الخصوصية أن النبي ﷺ يأمن الفتنة نقول إذاً نعلق الأمر على الفتنة.)`,
        f: [] },
      { q: `تأخير الوتر إلى آخر الليل وإيقاظ النائم للصلاة في وقتها، وقول عائشة «إن المرأة لدابة سوء» (الإنكار عليهم في قولهم: إن المرأة تقطع الصلاة)`, p: `323`,
        n: `قولها: (فإذا أراد أن يوتر أيقظني فأوترت) – فيه استحباب تأخير الوتر إلى آخر الليل، – وفيه أنه يُستحب لمن وثق باستيقاظه إما بنفسه وإما بإيقاظ غيره أن يؤخّر الوتر، وإن لم يكن له تهجّد، فإن عائشة رضي الله عنها كانت بهذه الصفة، وأما من لا يثق باستيقاظه، ولا له من يوقظه فيوتر قبل أن ينام، – وفيه استحباب إيقاظ النائم للصلاة في وقتها، وقد جاءت فيه أحاديث أيضًا غير هذا. قوله: (إن المرأة لدابّة سوء) تريد به الإنكار عليهم في قولهم: إن المرأة تقطع الصلاة.`,
        o: NO_O,
        s: `(إذا كان يوقظها للنافلة فبالأولى يجب أن يوقظ الولي أهله لصلاة الفريضة للصلاة في وقتها.) (هذا استنباط من عائشة رضي الله عنها وليس نصاً طالما أنه ثبت فيه حديث فلا يُعتد بقول أحد في خلافه ويبدوا أنها لم تسمع الحديث مرفوعاً إلى النبي ﷺ، أو أنها سمعته فوهمت الناقل أو السامع.)`,
        f: [] },
      { q: `غمز النبي ﷺ لعائشة عند السجود (لمس المرأة هل ينقض الوضوء؟)، ومعنى «والبيوت يومئذ ليس فيها مصابيح» وجواز الصلاة بجانب الحائض`, p: `324`,
        n: `قولها: (فإذا سجد غمزني فقبضت رجلي) استدلّ به من يقول لمس النساء لا ينقض الوضوء، والجمهور على أنه ينقض وحملوا الحديث على أنه غمزها فوق حائل، وهذا هو الظاهر من حال النائم، فلا دلالة فيه على عدم النقض. قولها: (والبيوت يومئذٍ ليس فيها مصابيح) أرادت تقول: لو كان فيها مصابيح لقبضت رجلي عند إرادته السجود، ولما أحوجته إلى غمزي. قولها: (كان النبي ﷺ يصلي من الليل وأنا إلى جنبه وأنا حائض وعليّ مرط وعليه بعضه إلى جنبه) (المرط) كساء، وفي هذا دليل على أن وقوف المرأة بجنب المصلّي لا يُبطل صلاته وهو مذهبنا ومذهب الجمهور، وأبطلها أبو حنيفة ﵁، وفيه أن ثياب الحائض طاهرة إلا موضعًا ترى عليه دمًا أو نجاسة أخرى، وفيه جواز الصلاة بحضرة الحائض، وجواز الصلاة في ثوب بعضه على المصلّي وبعضه على حائض أو غيرها.`,
        o: `الجمهور: لمس النساء ينقض الوضوء (والحديث محمول على أنه كان فوق حائل). أبو حنيفة: وقوف المرأة بجنب المصلي يبطل صلاته. الجمهور: لا يبطلها.`,
        s: `(ظاهر الحديث أنه لمسها من غير حائل (غمزني) فلمسها هي وليس ثوبها؛ وهناك أحاديث أخرى تدل على عدم النقض.) (لكن لا يصح أن تصلي بجواره فيجب أن تكون المرأة خلف الرجال، لكن لا تبطل الصلاة بوقوفها بجوار الرجل وهي لا تصلي فهذا لا يجوز.) (البهيمة لا تقطع الصلاة، فمرور أي شيء غير الثلاث (الكلب والحمار والمرأة) لا يبطل الصلاة ولكن تنقص منها.)`,
        f: [`(ص324) (ظاهر الحديث أنه لمسه من غير حائل (غمزني) فلمسها هي وليس ثوبها؛ وهناك أحاديث أخرى تدل على عدم النقض.)`] },
      { q: `استقبال المصلي وجه غيره (كراهة)، ومعنى «الكلب الأسود شيطان» (شيطان الحيوانات)، وحكم من مر بين يديه الثلاثة (يبدأ الصلاة من جديد)، واللمس عمومًا`, p: `325`,
        n: `وأما استقبال المصلّي وجه غيره فمذهبنا ومذهب الجمهور كراهته، ونقله القاضي عياض عن عامة العلماء رحمهم الله تعالى.`,
        o: NO_O,
        s: `(مع أنه لم يثبت فيه حديث.) – (والكلب الأسود شيطان أي شيطان الحيوانات ولا يلزم أنه بمعنى جن.) – (والكلب الأسود والحمار والمرأة إذا مروا فليبدأ الصلاة من جديد.) – (اللمس عموماً لا ينقض الوضوء سواء الزوجة أو غيرها.)`,
        f: [] },
    ],
  },
  {
    title: `باب الصلاة في ثوب واحد وصفة لُبسه (ص325–330)`,
    items: [
      { q: `الصلاة في الثوب الواحد: حكمها (وصلاة الثوبين أفضل)، ومعنى «أو لكلكم ثوبان؟»، وصلاة النبي ﷺ والصحابة في ثوب واحد`, p: `327–328`,
        n: `قوله: (سُئل رسول الله ﷺ عن الصلاة في ثوب واحد فقال: أَوَلِكُلِّكم ثوبان؟) فيه جواز الصلاة في ثوب واحد، ولا خلاف في هذا إلا ما حُكي عن ابن مسعود ﵁ فيه، ولا أعلم صحّته، وأجمعوا أن الصلاة في ثوبين أفضل. – ومعنى الحديث: أن الثوبين لا يقدر عليهما كل أحد، فلو وجبا لعجز من لا يقدر عليهما عن الصلاة، وفي ذلك حرج، وقد قال الله تعالى: {ما جعل عليكم في الدين من حرج}. – وأما صلاة النبي ﷺ والصحابة ﵃ في ثوب واحد: ففي وقت كان لعدم ثوب آخر، وفي وقت كان مع وجوده لبيان الجواز كما قال جابر ﵁ ليراني الجُهّال، وإلا فالثوبان أفضل كما سبق.`,
        o: `ابن مسعود (حُكي عنه ولا تصح): منع الصلاة في ثوب واحد. الإجماع: الصلاة في ثوبين أفضل.`,
        s: `(أي جواز الصلاة في الثوب الواحد، أما الصلاة في ثوبين فهي أفضل لأنها أستر، وأما الصلاة في الثوب الواحد فجائزة بشرط أن يغطي به منكبيه وذلك يحصل بأن يجعل له طرفان بحيث يكون الثوب واسع كبير فيلف نصفه الأسفل بجزء منه ويبقى طرفان فيلقي بطرف على كتفه الأيمن وطرف على كتفه الأيسر.) (نحن في كم نصلي؟ فالفقير الآن قد يصلي في خمسة مثلاً. – ففيه: ما كان عليه الصحابة من ضيق وشدة الحال والفقر والزهد في الدنيا ﷺ.) (وثوبه على المشجب (وعنده ثيابه).) (فلا يلزم أن يصلي في ثوبين وإنما يصلي أحياناً بثوب واحد بيان للجواز.)`,
        f: [] },
      { q: `الصلاة في الثوب الواحد ليس على عاتقه منه شيء: النهي عن ذلك (للتنزيه أم للتحريم؟) وحكمة النهي (ستر المنكبين)، ومذهب أحمد في وجوب وضع شيء على العاتق`, p: `328–329`,
        n: `قوله ﷺ: (لا يصلي أحدكم في الثوب الواحد ليس على عاتقه منه شيء) قال العلماء: حكمته أنه إذا ائتزر به ولم يكن على عاتقه منه شيء لم يؤمن أن تنكشف عورته بخلاف ما إذا جعل بعضه على عاتقه، ولأنه قد يحتاج إلى إمساكه بيده أو يديه فيشغل بذلك، وتفوته سنة وضع اليد اليمنى على البدن وموضع اليسرى تحت صدره، ورفعهما حيث شرع الرفع، وغير ذلك، لأن فيه ترك ستر أعلى البدن وموضع الزينة وقد قال الله تعالى: {خذوا زينتكم}. – ثم قال مالك وأبو حنيفة والشافعي رحمهم الله تعالى والجمهور: هذا النهي للتنزيه لا للتحريم، فلو صلى في ثوب واحد ساتر لعورته ليس على عاتقه منه شيء صحّت صلاته مع الكراهة، سواء قدر على شيء يجعله على عاتقه أم لا. – وقال أحمد وبعض السلف رحمهم الله: لا تصحّ صلاته إذا قدر على وضع شيء على عاتقه إلا بوضعه لظاهر الحديث. – وعن أحمد بن حنبل رحمه الله تعالى رواية أنه تصح صلاته، ولكن يأثم بتركه، وحجة الجمهور قوله ﷺ في حديث جابر ﵁: «فإن كان واسعًا فالتحف به، وإن كان ضيّقًا فأتزر به» رواه البخاري، ورواه مسلم في آخر الكتاب في حديثه الطويل.`,
        o: `مالك وأبو حنيفة والشافعي والجمهور: النهي للتنزيه، فتصح الصلاة مع الكراهة. أحمد وبعض السلف: لا تصح إذا قدر على وضع شيء على عاتقه. وعن أحمد رواية: تصح ويأثم بتركه. الظاهرية: يجزئ ستر العاتق بشيء ولو بحبل. أحمد في التفصيل: إذا كان الثوب ضيقًا اتزر به.`,
        s: `(وهذا هو الصحيح كما قلنا (على صدره) وليس تحته.) (أي عند الركوع والرفع منه وعند القيام للركعة الثالثة.) (فهذه عدة علل في هذا النهي، فهذا من الزينة وإن لم يكن الكتف عورة ولكن الستره من الزينة التي شرعها الله (خذوا زينتكم عند كل مسجد) أي عند كل صلاة، وهذا من المأمور به أن يكون الإنسان مستور الكتف طالما أمكنه ذلك، وقد يضطر إلى إمساك الثياب، إذا كان ثوب واحد مؤتزر به فقط، والائتزار: أن يلف الثوب على نصفه الأسفل، فيترتب على ذلك ترك بعض سنن الصلاة.) (وعندنا حديث صحيح البخاري عن سعيد بن الحارث قال سألنا جابر بن عبد الله، عن الصلاة في الثوب الواحد فقال خرجت مع النبي ﷺ في بعض أسفاره فجئت ليلة لبعض أمري فوجدته يصلي وعلى ثوب واحد فاشتملت به وصليت إلى جانبه فلما انصرف، قال: ما السُّرى يا جابر فأخبرته بحاجتي فلما فرغت، قال: [ما هذا الاشتمال الذي رأيت؟] قلت: كان ثوب يعني ضاق قال: [فإن كان واسعاً فالتحف به وإن كان ضيقاً فاتزر به]. فالاتزار إذا كان ضيقاً وهو دليل على صحة الصلاة، ولكن قد يقال: هذا فيها لم يجد ما يغطي به كتفه.) (وهي أقرب الروايات إلى الصحة، فهذا الأمر واجب لتصريح الحديث بالنهي، لأن هذا النفي (لا يصلي) بمعنى النهي أو هو نهي وظاهره التحريم؛ أما بطلان الصلاة فيحتاج إلى دليل آخر، وهذا نهي عن وصف خارج عن الصلاة وليس كما ذكرنا من باب ستر العورة، فالصحيح أنه إذا فعل ذلك عمداً يأثم ولا تبطل صلاته.) (ولكن هذا الحديث لا يدل على عدم التحريم إذا كان واجداً لشيء يستر به كتفيه.) (الظاهرية قالوا: يجزئ أن يستر عاتقيه بشيء ولو بحبل، والظاهر أن الحبل لا يجزئ عن الستر فهو ليس بستر والأخذ بالزينة أن يغطي كتفه؛ وأقل شيء في حكمها أن الصلاة بها مكروهة والله أعلم، فينبغي أن يستر كتفه. – أما أنه ستر الكتف ونزل على العضد ولم يستر كل الزراع فلا حرج، والصلاة بثوب [نصف كم] والكتف كله مستور فلا حرج عليه أو أن معظمه مستور أو لو وضع فوطه تجزئه.)`,
        f: [] },
      { q: `الاشتمال في الثوب الواحد، والتوشح، والمخالفة بين الطرفين، ومعنى «مشتملًا» و«متوشحًا» و«ملتحفًا» (وجواز الصلاة في ثوب واحد)`, p: `329`,
        n: `قوله: (رأيت رسول الله ﷺ يصلي في ثوب واحد مشتملًا به واضعًا طرفيه على عاتقيه) وفي الرواية الأخرى (مخالفًا بين طرفيه). وفي حديث جابر (متوشحًا به) المشتمل والمتوشح والمخالف بين طرفيه معناها واحد هنا. قال ابن السكّيت: التوشح أن يأخذ طرف الثوب الذي ألقاه على منكبه الأيمن من تحت يده اليسرى، ويأخذ طرفه الذي ألقاه على الأيسر من تحت يده اليمنى، ثم يعقدهما على صدره. وفيه جواز الصلاة في ثوب واحد.`,
        o: NO_O,
        s: `(وعن أحمد بن حنبل رحمه الله تعالى رواية أنه تصح صلاته، ولكن يأثم بتركه...) (ولكن هذا الحديث لا يدل على عدم التحريم إذا كان واجداً لشيء يستر به كتفيه.)`,
        f: [] },
      { q: `الصلاة على الحصير والبساط ونحوه: حكمها (على شيء يحول بينه وبين الأرض)، وفتاوى: الصلاة في البنطال الضيق، والصلاة على السرير أو مكان مرتفع (فتوى)`, p: `330`,
        n: `قوله: (فرأيته يصلي على حصير يسجد) فيه دليل على جواز الصلاة على شيء يحول بينه وبين الأرض من ثوب وحصير وصوف وشعر وغير ذلك، وسواء نبت من الأرض أم لا. – وهذا مذهبنا ومذهب الجمهور. – وقال القاضي رحمه الله تعالى: أما ما نبت من الأرض فلا كراهة فيه، وأما البُسط واللُّبود وغيرها مما ليس من نبات الأرض فتصحّ الصلاة فيه بالإجماع، لكن الأرض أفضل منه إلا لحاجة حرّ أو برد أو نحوهما، لأن الصلاة سرّها التواضع والخشوع. والله ﷻ أعلم.`,
        o: `القاضي عياض: ما نبت من الأرض لا كراهة فيه، وما ليس منه تصح الصلاة فيه بالإجماع لكن الأرض أفضل إلا لحاجة.`,
        s: `(والصحيح أنه لا كراهة فيهم سواء كان من نبت من الأرض أو من غيرها.) ❖ فتاوى: (الصلاة في البنطال الضيق أقل أحوالها الكراهة والظاهر التحريم إذا كان مجسم العورة وأما الواسع فتصح الصلاة فيه.) (الصلاة على السرير أو على أي مكان مرتفع صحيح طالما أنه يتمكن من السجود ووضع جبهته على مكان سجوده.) (فتوى)`,
        f: [] },
    ],
  },
];
